-- Targeted TCF Reading distractor polish. 15_20: only 6 immutable banks, 2 questions per bank.
-- Original passages, stems, keys, weights, UI, prior versions, attempts and progress retained.
begin;
select pg_advisory_xact_lock(hashtext('tcf-reading-distractor-polish-20261119'));
create temp table cleanup_before on commit drop as
select (select count(*) from academy_tcf_reading.papers) as banks,
 (select count(*) from academy_tcf_reading.attempts) as attempts,
 (select md5(coalesce(string_agg(to_jsonb(a)::text,'' order by id),'')) from academy_tcf_reading.attempts a) as attempts_digest,
 (select md5(coalesce(string_agg(to_jsonb(p)::text,'' order by id,version),'')) from academy_tcf_reading.papers p) as banks_digest;
create temp table cleanup_other_pointers on commit drop as
select test_id,version from academy_tcf_reading.published_papers where test_id not in ('tcf-reading-15','tcf-reading-16','tcf-reading-17','tcf-reading-18','tcf-reading-19','tcf-reading-20');
create temp table cleanup_scope(test_id text,changed integer[]) on commit drop;
insert into cleanup_scope values
('tcf-reading-15',array[28,33]::integer[]),
('tcf-reading-16',array[27,31]::integer[]),
('tcf-reading-17',array[28,36]::integer[]),
('tcf-reading-18',array[32,34]::integer[]),
('tcf-reading-19',array[28,31]::integer[]),
('tcf-reading-20',array[31,37]::integer[]);
do $preflight$ begin
 if (select count(*) from academy_tcf_reading.published_papers)<>20 then raise exception 'Expected 20 published reading papers'; end if;
 if (select count(*) from academy_tcf_reading.published_papers where test_id between 'tcf-reading-01' and 'tcf-reading-06' and version='tcf-reading-2026-11-close-reading-v6')<>6 then raise exception 'Tests 01-06 changed'; end if;
 if (select count(*) from academy_tcf_reading.published_papers where test_id between 'tcf-reading-07' and 'tcf-reading-14' and version='tcf-reading-2026-11-distractor-polish-v5')<>8 then raise exception 'Earlier cleanup batch pointer changed'; end if;
 if (select count(*) from academy_tcf_reading.published_papers where test_id in ('tcf-reading-15','tcf-reading-16','tcf-reading-17','tcf-reading-18','tcf-reading-19','tcf-reading-20') and version='tcf-reading-2026-11-close-reading-v4')<>6 then raise exception 'Expected exactly 6 original v4 catalog pointers'; end if;
 if (select count(*) from academy_tcf_reading.papers where id in ('tcf-reading-15','tcf-reading-16','tcf-reading-17','tcf-reading-18','tcf-reading-19','tcf-reading-20') and version='tcf-reading-2026-11-distractor-polish-v5')<>0 then raise exception 'Target new versions already exist'; end if;
 if exists (select 1 from (values
('tcf-reading-15','949704f67dc2d0b6afadbc9a80d0ebbd'),
('tcf-reading-16','89f6a323e166ecf1479a5d729036d972'),
('tcf-reading-17','ec8b2cb24e27ca0625503fd8d4ff5332'),
('tcf-reading-18','588103751906a1705f4c21423c279286'),
('tcf-reading-19','8c5d93c0894c97ad1a472b9bcc0f7627'),
('tcf-reading-20','ae58eab67555bc45de32598d0d6746df')
) as expected(id,digest)
 join academy_tcf_reading.papers p on p.id=expected.id and p.version='tcf-reading-2026-11-close-reading-v4'
 where md5(p.content::text)<>expected.digest) then raise exception 'Published source bank digest changed since editorial inspection'; end if;
end $preflight$;
insert into academy_tcf_reading.papers(id,version,content) values
('tcf-reading-15','tcf-reading-2026-11-distractor-polish-v5',$paper_15${"id":"tcf-reading-15","title":"TCF Reading · Test 15","seconds":3600,"version":"tcf-reading-2026-11-distractor-polish-v5","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"D","options":["Un remboursement sans ticket","Un échange sans limite de temps","Une reprise par n'importe quel magasin","Un échange sous conditions"],"passage":"Les articles soldés peuvent être échangés pendant quinze jours avec le ticket. Cette offre ne prévoit pas de remboursement.\n\nL'article doit être rapporté dans son état d'origine. Le personnel vérifiera les conditions indiquées sur le document remis au moment de l'achat.","question":"Quelle possibilité est annoncée ?","explanation":"Le passage indique : « Les articles soldés peuvent être échangés pendant quinze jours avec le ticket. Cette offre ne prévoit pas de remboursement. » Cela justifie la réponse : Un échange sous conditions."},{"number":2,"points":3,"correct":"A","options":["Le prix doit être recalculé","Le devis initial s'applique toujours","Le service devient gratuit","Le délai disparaît"],"passage":"Le devis reste valable trente jours. Toute modification de la demande donnera lieu à un nouveau calcul.\n\nLe client recevra les nouvelles conditions avant toute intervention.","question":"Que se passe-t-il si la demande change ?","explanation":"Le passage indique : « Le devis reste valable trente jours. Toute modification de la demande donnera lieu à un nouveau calcul. » Cela justifie la réponse : Le prix doit être recalculé."},{"number":3,"points":3,"correct":"D","options":["Chez un commerçant voisin","À la caisse principale obligatoirement","Dans l'atelier fermé","À l'arrière du magasin"],"passage":"Le retrait des commandes se fait derrière le magasin. L'accueil principal reste réservé aux achats sur place.\n\nUn panneau indiquera l'accès depuis le parking. Présentez la confirmation reçue pour que l'équipe retrouve les articles déjà préparés à votre nom.","question":"Où retirer une commande ?","explanation":"Le passage indique : « Le retrait des commandes se fait derrière le magasin. L'accueil principal reste réservé aux achats sur place. » Cela justifie la réponse : À l'arrière du magasin."},{"number":4,"points":3,"correct":"C","options":["Remplacer lui-même toutes les pièces","Envoyer une publicité","Accepter ou refuser le devis","Venir chercher une commande déjà achevée"],"passage":"La réparation est suspendue en attendant votre accord sur le devis. Aucune pièce supplémentaire ne sera commandée avant votre réponse.\n\nLe réparateur vous indiquera ensuite le délai, selon votre choix et la disponibilité des pièces.","question":"Quelle action est attendue du client ?","explanation":"Le passage indique : « La réparation est suspendue en attendant votre accord sur le devis. Aucune pièce supplémentaire ne sera commandée avant votre réponse. » Cela justifie la réponse : Accepter ou refuser le devis."},{"number":5,"points":9,"correct":"B","options":["Payer nécessairement le moins cher sur douze mois","Limiter la durée d'engagement","Obtenir un contrat définitif","Éviter toute facture"],"passage":"J'ai choisi l'abonnement mensuel, même s'il coûte plus cher sur un an. Je ne sais pas encore combien de temps j'utiliserai le service.\n\nJe pourrai passer à une formule plus longue lorsque mon emploi du temps sera stabilisé. Pour le moment, je préfère garder la possibilité d'arrêter sans payer toute une année.","question":"Pourquoi ce choix est-il fait ?","explanation":"Le passage indique : « J'ai choisi l'abonnement mensuel, même s'il coûte plus cher sur un an. Je ne sais pas encore combien de temps j'utiliserai le service. » Cela justifie la réponse : Limiter la durée d'engagement."},{"number":6,"points":9,"correct":"B","options":["Une livraison gratuite à l'étranger","Un délai de retrait prolongé","Une annulation automatique","Un achat supplémentaire obligatoire"],"passage":"Votre colis est arrivé dans un autre point de retrait. Vous disposez de deux jours supplémentaires pour le récupérer.\n\nLe message précise l'adresse et les nouveaux horaires. Merci de vérifier ces informations avant de vous déplacer au lieu que vous utilisez habituellement.","question":"Quelle adaptation est proposée ?","explanation":"Le passage indique : « Votre colis est arrivé dans un autre point de retrait. Vous disposez de deux jours supplémentaires pour le récupérer. » Cela justifie la réponse : Un délai de retrait prolongé."},{"number":7,"points":9,"correct":"A","options":["L'ensemble des frais liés au contrat","Le nombre de publicités","La couleur du matériel","Le prix du premier mois uniquement"],"passage":"Je veux comparer le coût total, pas seulement la première mensualité. Peux-tu vérifier les frais d'installation et de résiliation ?\n\nUne petite différence annoncée peut devenir importante sur plusieurs mois. J'aimerais donc noter les conditions dans le même tableau avant de comparer les deux offres proposées.","question":"Quelle information est recherchée ?","explanation":"Le passage indique : « Je veux comparer le coût total, pas seulement la première mensualité. Peux-tu vérifier les frais d'installation et de résiliation ? » Cela justifie la réponse : L'ensemble des frais liés au contrat."},{"number":8,"points":9,"correct":"C","options":["Venir sans signaler son besoin","Attendre la fin de la réparation","Demander le prêt dès le dépôt","Acheter un appareil neuf obligatoirement"],"passage":"La boutique prête un appareil pendant certaines réparations. Signalez ce besoin lors du dépôt ; le stock est limité.\n\nLe prêt ne sera pas automatiquement possible pour chaque modèle ou à toutes les périodes de l'année.","question":"Que doit faire le client intéressé ?","explanation":"Le passage indique : « La boutique prête un appareil pendant certaines réparations. Signalez ce besoin lors du dépôt ; le stock est limité. » Cela justifie la réponse : Demander le prêt dès le dépôt."},{"number":9,"points":9,"correct":"D","options":["Commander trois tailles","Produire sans connaître les dimensions","Attendre le retour de tous les clients","Mesurer avant fabrication"],"passage":"Merci de ne pas commander deux tailles pour notre atelier de fabrication sur mesure. Nous pouvons organiser une prise de mesures avant de lancer la production.\n\nUn conseiller vous expliquera les étapes et les délais.","question":"Quelle solution évite les commandes multiples ?","explanation":"Le passage indique : « Merci de ne pas commander deux tailles pour notre atelier de fabrication sur mesure. Nous pouvons organiser une prise de mesures avant de lancer la production. » Cela justifie la réponse : Mesurer avant fabrication."},{"number":10,"points":9,"correct":"C","options":["Une suppression de la main-d'œuvre","Une hausse automatique","Une présentation plus détaillée","Une réduction des fournitures"],"passage":"La facture distingue maintenant les fournitures et la main-d'œuvre. Le montant total ne change pas.\n\nLes clients pourront poser une question sur chaque rubrique. Le service souhaite rendre le document plus facile à comprendre sans modifier les conditions du travail déjà convenu.","question":"Quel changement est annoncé ?","explanation":"Le passage indique : « La facture distingue maintenant les fournitures et la main-d'œuvre. Le montant total ne change pas. » Cela justifie la réponse : Une présentation plus détaillée."},{"number":11,"points":15,"correct":"A","options":["L'historique des réparations effectuées","La liste des anciens utilisateurs","Une promesse de fonctionnement éternel","Le prix de tous les objets neufs"],"passage":"Une coopérative répare les objets avant de les revendre. Les clients reçoivent une description des interventions réalisées.\n\nLes intervenants indiquent les pièces remplacées et les limites éventuelles du matériel. L'acheteur peut ainsi demander une précision avant de décider. La coopérative veut distinguer une remise en état vérifiée d'un objet simplement présenté comme une bonne affaire. Les bénévoles gardent une trace des contrôles et expliquent les conditions du service après la vente. Ils ne promettent pas qu'un produit d'occasion sera identique à un appareil neuf, mais souhaitent que la comparaison repose sur des informations suffisamment claires pour les personnes intéressées.","question":"Quelle information accompagne la vente ?","explanation":"Le passage indique : « Une coopérative répare les objets avant de les revendre. Les clients reçoivent une description des interventions réalisées. » Cela justifie la réponse : L'historique des réparations effectuées."},{"number":12,"points":15,"correct":"B","options":["Comparer uniquement les couleurs","Faciliter une comparaison homogène","Éviter de montrer les prix","Garantir que la plus grosse bouteille coûte moins cher"],"passage":"Un magasin affiche le prix à l'unité et au litre. Cela permet de comparer des bouteilles de contenances différentes.\n\nLe personnel peut montrer où lire cette indication sur les étiquettes. Le magasin utilise la même base pour éviter que les clients comparent seulement le prix placé en grands caractères. Le format le plus économique dépend aussi de la quantité réellement utilisée. Une grande bouteille n'est donc pas présentée comme toujours préférable.","question":"Quel objectif poursuit cet affichage ?","explanation":"Le passage indique : « Un magasin affiche le prix à l'unité et au litre. Cela permet de comparer des bouteilles de contenances différentes. » Cela justifie la réponse : Faciliter une comparaison homogène."},{"number":13,"points":15,"correct":"D","options":["L'association signe tous les contrats","Tous les fournisseurs sont exclus","Le consommateur doit changer d'offre","La décision reste au consommateur"],"passage":"Une association aide à lire les contrats, sans choisir un fournisseur à la place du consommateur.\n\nLes conseillers expliquent les termes et aident à repérer les frais annoncés. Ils peuvent aussi proposer une liste de questions à adresser au fournisseur. Le service ne connaît pas forcément tous les besoins personnels et ne transforme pas son accompagnement en vente d'une offre particulière. Les personnes restent libres de poursuivre leur comparaison après la rencontre. L'association souhaite surtout que la signature corresponde à une décision comprise, plutôt qu'à un accord donné rapidement parce que le document semblait trop complexe pour être examiné ou discuté avant l'engagement.","question":"Quelle est la limite de l'accompagnement ?","explanation":"Le passage indique : « Une association aide à lire les contrats, sans choisir un fournisseur à la place du consommateur. » Cela justifie la réponse : La décision reste au consommateur."},{"number":14,"points":15,"correct":"B","options":["L'autorisation du client n'a aucun rôle","Tout n'est pas inclus dans le forfait","Le forfait interdit les interventions","Chaque réparation est nécessairement gratuite"],"passage":"Une entreprise vend un service d'entretien annuel. Les interventions supplémentaires sont facturées séparément et doivent être autorisées.\n\nLes clients recevront une fiche avec les opérations habituelles comprises dans l'abonnement. Une intervention inhabituelle fera l'objet d'une proposition précisant le travail et son montant. L'entreprise veut éviter une confusion entre un service régulier et une prise en charge illimitée de tout incident. Le bilan de l'année indiquera aussi les demandes les plus fréquentes, afin de voir si la formule correspond bien aux usages réels ou si elle doit être revue pour rester compréhensible et utile.","question":"Quelle information est importante ?","explanation":"Le passage indique : « Une entreprise vend un service d'entretien annuel. Les interventions supplémentaires sont facturées séparément et doivent être autorisées. » Cela justifie la réponse : Tout n'est pas inclus dans le forfait."},{"number":15,"points":15,"correct":"C","options":["Supprimer toutes les réservations","Acheter une machine pour chaque heure","Mieux utiliser un équipement commun","Réduire les compétences nécessaires"],"passage":"Un atelier partage une machine coûteuse entre plusieurs professionnels. Les horaires sont coordonnés pour réduire les temps inutilisés.\n\nLes utilisateurs réservent des plages et signalent leurs besoins avant les périodes les plus chargées. Le collectif souhaite éviter qu'une machine accessible en principe soit presque toujours indisponible au moment où chacun en a besoin. Les horaires seront donc réexaminés après les premiers mois. Le projet ne consiste pas seulement à répartir un prix d'achat, mais à organiser un équipement capable de servir correctement plusieurs activités dans la durée, avec des responsabilités connues de toutes les personnes concernées.","question":"Quel avantage économique est recherché ?","explanation":"Le passage indique : « Un atelier partage une machine coûteuse entre plusieurs professionnels. Les horaires sont coordonnés pour réduire les temps inutilisés. » Cela justifie la réponse : Mieux utiliser un équipement commun."},{"number":16,"points":15,"correct":"A","options":["Un nettoyage inclus","Un achat définitif","La possibilité de découper le vêtement","Une fabrication sur mesure automatique"],"passage":"Une boutique propose la location d'une tenue de cérémonie. Le nettoyage est compris, mais les retouches personnelles sont interdites.\n\nLe personnel vérifie l'état du vêtement au départ et au retour avec le client. Il explique les précautions et les accessoires fournis. Une demande particulière doit être discutée avant la réservation, car le même article sera ensuite porté par d'autres personnes. La boutique souhaite offrir une solution ponctuelle sans laisser croire qu'une location donne tous les droits d'un achat.","question":"Que peut attendre le client ?","explanation":"Le passage indique : « Une boutique propose la location d'une tenue de cérémonie. Le nettoyage est compris, mais les retouches personnelles sont interdites. » Cela justifie la réponse : Un nettoyage inclus."},{"number":17,"points":15,"correct":"A","options":["Identifier la cause avant d'engager une dépense","Changer immédiatement tout l'appareil","Vendre uniquement du matériel neuf","Garantir une panne précise sans examen"],"passage":"Un réparateur refuse un remplacement coûteux avant d'avoir vérifié une panne simple. Il explique les étapes du diagnostic.\n\nIl décrit les observations nécessaires et indique le coût du premier examen. Les clients peuvent ensuite décider s'ils souhaitent poursuivre. Le professionnel veut éviter qu'une solution techniquement possible soit choisie avant que son utilité soit appréciée. Certains défauts demandent une intervention importante, d'autres une vérification plus simple. Le service conserve une trace des échanges pour que les opérations réalisées correspondent à ce qui a été expliqué.","question":"Quelle démarche adopte-t-il ?","explanation":"Le passage indique : « Un réparateur refuse un remplacement coûteux avant d'avoir vérifié une panne simple. Il explique les étapes du diagnostic. » Cela justifie la réponse : Identifier la cause avant d'engager une dépense."},{"number":18,"points":15,"correct":"D","options":["Garantir l'absence de toute facture","Payer un service déjà terminé uniquement","Supprimer le montant final","Financer une partie de la préparation"],"passage":"Une entreprise demande un acompte pour acheter les matériaux. Le solde sera payé après la livraison convenue.\n\nLe document précise le calendrier, les matériaux concernés et les étapes qui restent à réaliser. L'entreprise souhaite expliquer pourquoi une somme est demandée alors que l'objet n'a pas encore été livré. Les conditions d'une modification ou d'un abandon seront indiquées avant le versement, afin que les personnes sachent quels engagements elles prennent et quelles questions poser si la préparation ne peut pas avancer comme prévu.","question":"À quoi sert l'acompte ?","explanation":"Le passage indique : « Une entreprise demande un acompte pour acheter les matériaux. Le solde sera payé après la livraison convenue. » Cela justifie la réponse : Financer une partie de la préparation."},{"number":19,"points":15,"correct":"A","options":["Le contrôle ne garantit pas tous les aspects techniques","Aucune observation n'est réalisée","Les objets sont tous neufs","Le prix assure automatiquement la sécurité"],"passage":"Le marché d'occasion organise un contrôle visuel des objets électriques. Les organisateurs précisent qu'il ne remplace pas une vérification technique complète.\n\nLes bénévoles regardent les signes de dommage visibles et les informations présentes sur l'appareil. Ils orientent les cas douteux vers un professionnel et refusent de promettre une sécurité complète sur cette seule base. Le marché souhaite réduire les risques sans transformer une inspection rapide en certification. Les acheteurs sont invités à demander les limites du contrôle et à vérifier l'adaptation de l'objet à leur usage.","question":"Quelle limite est reconnue ?","explanation":"Le passage indique : « Le marché d'occasion organise un contrôle visuel des objets électriques. Les organisateurs précisent qu'il ne remplace pas une vérification technique complète. » Cela justifie la réponse : Le contrôle ne garantit pas tous les aspects techniques."},{"number":20,"points":21,"correct":"A","options":["L'adéquation entre quantité achetée et besoin","La musique diffusée","Le nombre de caisses du magasin","La taille de l'affiche"],"passage":"Une promotion propose un prix bas pour trois articles. Un conseiller rappelle que l'économie n'existe que si l'acheteur utilise réellement ces quantités. Une personne vivant seule pourra préférer un article à l'unité, même si le prix annoncé pour un lot semble plus avantageux. Le conseiller propose de comparer le montant total et la consommation prévue. Il souhaite éviter que le mot promotion suffise à faire acheter une quantité sans rapport avec les habitudes. Les dates et les possibilités de conservation restent des informations utiles pour apprécier la proposition dans chaque foyer.","question":"Quelle condition faut-il examiner ?","explanation":"Le passage indique : « Une promotion propose un prix bas pour trois articles. Un conseiller rappelle que l'économie n'existe que si l'acheteur utilise réellement ces quantités. » Cela justifie la réponse : L'adéquation entre quantité achetée et besoin."},{"number":21,"points":21,"correct":"B","options":["Un retrait obligatoire à l'usine","Moins de rapidité contre une meilleure organisation","Une suppression de tous les délais","Une livraison immédiate garantie partout"],"passage":"Une entreprise baisse ses coûts de livraison en regroupant les commandes. Elle annonce des délais moins rapides mais plus prévisibles. L'entreprise explique pourquoi elle ne promet plus un départ immédiat après chaque commande. Les économies réalisées seront suivies avec les retards et les difficultés de regroupement. Le service veut éviter qu'un gain pour sa propre organisation se traduise par une attente mal expliquée ou par une obligation pour les clients de rester disponibles sans connaître un créneau de réception.","question":"Quel compromis est proposé ?","explanation":"Le passage indique : « Une entreprise baisse ses coûts de livraison en regroupant les commandes. Elle annonce des délais moins rapides mais plus prévisibles. » Cela justifie la réponse : Moins de rapidité contre une meilleure organisation."},{"number":22,"points":21,"correct":"C","options":["Vendre tous les objets au même prix","Abandonner son propre atelier","Participer à la tenue de la boutique","Refuser les nouveaux clients"],"passage":"Des artisans créent une boutique collective. Les ventes soutiennent chacun, mais la permanence est partagée selon un calendrier commun. Les membres s'engagent sur des créneaux compatibles avec leur travail de production. Une personne de remplacement pourra être prévue lorsque plusieurs marchés ont lieu le même jour. Les résultats seront discutés à partir des ventes et du temps réellement consacré au lieu, afin de savoir si la coopération apporte un avantage soutenable à chacun plutôt qu'un surcroît de tâches mal réparti.","question":"Quelle obligation accompagne cette organisation ?","explanation":"Le passage indique : « Des artisans créent une boutique collective. Les ventes soutiennent chacun, mais la permanence est partagée selon un calendrier commun. » Cela justifie la réponse : Participer à la tenue de la boutique."},{"number":23,"points":21,"correct":"C","options":["Le nombre de slogans","La date des publicités","La possibilité d'entretenir le produit","Le volume de l'emballage seulement"],"passage":"Un client compare deux produits de prix proches. Celui dont les pièces sont disponibles longtemps pourrait coûter moins cher à l'usage, même si l'achat initial est légèrement supérieur. Le client se renseigne sur les références et les délais de commande. Il cherche aussi à savoir si l'appareil peut être ouvert avec un outillage courant. Les documents disponibles lui permettront de comparer des situations possibles, sans garantir à l'avance qu'aucune panne ne surviendra. Son choix repose sur plusieurs dépenses probables au cours du temps.","question":"Quel critère complète le prix d'achat ?","explanation":"Le passage indique : « Un client compare deux produits de prix proches. Celui dont les pièces sont disponibles longtemps pourrait coûter moins cher à l'usage, même si l'achat initial est légèrement supérieur. » Cela justifie la réponse : La possibilité d'entretenir le produit."},{"number":24,"points":21,"correct":"D","options":["Interdire la monnaie habituelle","Supprimer les prix","Obliger tous les magasins à participer","Soutenir certains échanges de proximité"],"passage":"Une commune teste une monnaie locale auprès de commerces volontaires. L'objectif est de favoriser les échanges dans le réseau, pas de remplacer tous les moyens de paiement. Les participants reçoivent une information sur les lieux acceptant le dispositif et les modalités de fonctionnement. Les organisateurs veulent observer les achats effectivement réalisés dans le réseau, sans confondre inscriptions et échanges. Les commerçants restent libres de participer selon les règles annoncées.","question":"Quelle ambition est précisée ?","explanation":"Le passage indique : « Une commune teste une monnaie locale auprès de commerces volontaires. L'objectif est de favoriser les échanges dans le réseau, pas de remplacer tous les moyens de paiement. » Cela justifie la réponse : Soutenir certains échanges de proximité."},{"number":25,"points":21,"correct":"C","options":["Le frais compense une perte qui peut survenir aussi pour une annulation précoce, même lorsque le créneau reste disponible.","La facturation tardive assure au prestataire une nouvelle réservation, puisqu'elle rend le créneau immédiatement visible aux autres clients.","Le créneau annulé tard risque de rester inutilisé, faute de temps pour le proposer aux personnes en attente.","La pénalité est avant tout justifiée lorsque les conditions n'ont pas été suffisamment mises en évidence avant le paiement."],"passage":"Un service de réservation facture une annulation tardive. Il explique cette règle avant paiement, car le créneau ne peut pas toujours être attribué à un autre client. Les clients peuvent annuler sans frais jusqu'à une limite clairement annoncée. Au-delà, le prestataire examine les conditions prévues au contrat. Il souhaite éviter que plusieurs rendez-vous restent inutilisés alors que d'autres personnes attendent une place. Les responsables vérifieront cependant que la règle est visible et comprise avant la confirmation. Deux clients annulent à 24 heures d'intervalle; seul le premier reste dans le délai gratuit, car la place du second n'a plus pu être proposée à temps. Le service affiche la limite lors du choix du créneau.","question":"Quelle justification de la facturation tardive ressort de la règle ?","explanation":"C est fondée sur la difficulté de proposer à temps un créneau libéré tardivement. A ne distingue plus le seuil de gratuité, B promet une réattribution que la situation contredit et D transforme un défaut d'information en justification de la pénalité."},{"number":26,"points":21,"correct":"C","options":["Elle oblige les clients à reconnaître que chaque poste de coût a augmenté dans la même proportion.","Elle remplace toute possibilité de comparaison puisque les dépenses ont été détaillées.","Elle rend les motifs évaluables sans imposer aux clients l'acceptation de la décision tarifaire.","Elle élimine la hausse dès lors que les raisons sont comprises par les acheteurs."],"passage":"Une entreprise annonce une hausse de prix et décrit les coûts concernés. Certains clients restent mécontents, mais peuvent comparer les raisons données plutôt que découvrir un montant sans explication. Les explications distinguent les éléments durables des variations temporaires. Le commerce ne demande pas aux clients d'accepter toute décision parce qu'un motif est présenté. Il souhaite leur donner des repères pour juger si l'offre reste adaptée à leur budget et à leurs besoins. Le fournisseur détaille une hausse liée au transport et une autre à un matériau devenu plus cher. Un client accepte la première justification mais envisage une offre concurrente; le commerçant ne considère pas cette décision comme une erreur.","question":"Quel rôle l'explication des coûts joue-t-elle dans la relation commerciale ?","explanation":"Les motifs donnent des repères sans garantie de satisfaction ou d'adhésion. C. A/D/B imposent des conséquences non dites."},{"number":27,"points":21,"correct":"D","options":["Les réponses publiées ne représentent qu'une partie des achats, mais elles suffisent si le nombre d'avis extrêmes est élevé.","Le nombre d'avis recueillis doit être rapporté au nombre de références vendues pour corriger un écart de satisfaction.","Les avis les plus tranchés doivent être analysés séparément puis exclus pour retrouver une expérience moyenne des acheteurs.","La surreprésentation des clients très satisfaits ou mécontents dans les avis spontanés, au détriment d'expériences ordinaires moins visibles."],"passage":"Une étude de satisfaction reçoit surtout les réponses des clients très contents ou très déçus. Le commerce ajoute des entretiens courts avec des acheteurs ordinaires. Les enquêteurs demandent aux personnes comment s'est déroulé un achat récent, sans les choisir uniquement à partir d'une note déjà publiée. Le commerce souhaite conserver les critiques et les compliments, mais savoir aussi comment ils se répartissent parmi les clients. Sur cent achats, une poignée de clients laisse des avis extrêmes. Les enquêteurs contactent également des personnes qui n'ont publié aucune note afin de mieux comprendre les expériences moins visibles.","question":"Quel défaut d'échantillonnage l'enquête complémentaire cherche-t-elle à corriger ?","explanation":"D désigne la surreprésentation spontanée des avis très positifs ou très négatifs. A confond intensité des avis et représentativité; B rapporte les avis aux produits plutôt qu'aux clients; C supprimerait des réponses plutôt que compléter l'échantillon."},{"number":28,"points":21,"correct":"B","options":["La formule publicitaire reporte le financement sur les annonceurs, tandis que l'abonnement reflète directement le temps consacré par l'utilisateur.","L'absence de paiement direct peut correspondre à un financement par l'attention commercialisée aux annonceurs.","L'offre financée par les annonces ne demande aucune contribution économique aux utilisateurs, puisque seuls les annonceurs versent de l'argent.","À fonctionnalités égales, seul le prix affiché distingue les deux offres."],"passage":"Une offre gratuite est financée par la publicité. Les utilisateurs ne paient pas directement, mais leur attention intéresse les annonceurs. Il ne souhaite pas que l'absence de paiement direct soit comprise comme l'absence de tout échange économique. Les utilisateurs pourront ainsi apprécier ce qui finance les fonctions proposées, au lieu de devoir déduire le fonctionnement de la seule mention gratuite placée en tête de la présentation commerciale du produit. Deux offres proposent la même fonctionnalité. La première demande un abonnement; la seconde affiche des annonces et mesure l'exposition publicitaire des utilisateurs. Le mot « gratuit » décrit uniquement l'absence de prix payé directement.","question":"Quelle différence doit comprendre l'utilisateur lorsqu'il compare ces deux offres ?","explanation":"B distingue l'absence de paiement direct du financement par l'attention vendue aux annonceurs. A attribue à l'abonnement un tarif lié au temps non décrit; C ignore la contribution d'attention; D réduit l'échange au prix malgré la publicité."},{"number":29,"points":21,"correct":"C","options":["Remplacer les engagements de livraison par une présentation plus séduisante des produits en vitrine.","Rendre impossibles les demandes particulières des clients afin de maintenir un catalogue fixe.","Réduire la gamme suivie pour mieux tenir les engagements annoncés concernant la disponibilité.","Augmenter le nombre d'articles présentés sans vérifier la capacité des fournisseurs à livrer."],"passage":"Un commerçant préfère une petite gamme suivie à un choix très vaste souvent indisponible. Il veut rendre plus fiables les promesses de stock. Les fournisseurs connaissent mieux les quantités et les dates auxquelles le magasin s'engage. Les clients peuvent demander un article particulier, mais la boutique préfère annoncer un délai réaliste plutôt qu'une disponibilité supposée immédiate. Le responsable suivra les commandes non satisfaites pour ajuster la gamme. Sur une ancienne gamme de cinquante produits, douze manquent souvent. La boutique limite désormais son assortiment à trente références pour lesquelles les livraisons sont suivies; les commandes spéciales restent possibles avec un délai annoncé.","question":"Quel arbitrage commercial guide la réduction de l'assortiment ?","explanation":"Le magasin sacrifie la largeur affichée pour la disponibilité crédible. C. D/B/A ignorent stock et délais."},{"number":30,"points":26,"correct":"B","options":["Calculer pour chaque appareil le prix d'achat et la dépense d'entretien maximale afin de sécuriser la comparaison.","Estimer les frais cumulés selon les usages et la durée, plutôt que le seul prix d'achat affiché.","Comparer les garanties et le coût initial, puis n'ajouter les consommables qu'en cas de panne réellement observée.","Estimer d'abord l'économie à l'achat, et attribuer ensuite les frais de fonctionnement aux différences de marque."],"passage":"Le coût d'un produit comprend parfois des dépenses reportées : consommables, entretien et remplacement d'accessoires. Un prix de départ attractif ne suffit donc pas à juger une offre. Comparer suppose de définir une durée et des usages vraisemblables. Les utilisateurs peuvent ainsi comparer les offres sur une base plus cohérente. Une estimation restera cependant liée aux hypothèses retenues, qu'il faut rendre lisibles plutôt que présenter comme des dépenses futures certaines pour chaque personne. Un appareil peu cher exige des consommables fréquents, tandis qu'un autre plus coûteux initialement demande peu d'entretien. Le meilleur choix varie selon l'intensité et la durée d'utilisation prévues.","question":"Quel calcul permet une comparaison pertinente des deux appareils ?","explanation":"B évalue le coût cumulé selon un horizon et des usages annoncés, dont les consommables et l'entretien. A traite un maximum comme coût prévu; C omet les consommables réguliers; D ne calcule pas les frais liés à l'usage."},{"number":31,"points":26,"correct":"B","options":["Il indique que les demandes deviennent moins complexes et nécessitent moins de vérifications.","Il améliore la vitesse d'un échange tout en pouvant dégrader la résolution durable des problèmes.","Il prouve que les salariés ne consacrent plus aucun temps à expliquer leurs réponses.","Il établit que le nombre de clients servis diminue, quelle que soit la fréquence des rappels."],"passage":"Une entreprise mesure le service client par la durée moyenne des appels. Les employés raccourcissent les échanges, mais les mêmes personnes rappellent davantage. L'amélioration apparente d'un indicateur peut donc masquer une résolution moins efficace des problèmes. L'entreprise ajoute donc le nombre de demandes résolues sans rappel à son suivi. Elle souhaite que les salariés puissent prendre le temps utile, sans confondre rapidité de l'échange et qualité du résultat obtenu pour le client. La durée moyenne passe de six à quatre minutes, mais la part des problèmes réglés au premier appel baisse et les rappels doublent. Le directeur ajoute un suivi de résolution sur plusieurs jours.","question":"Pourquoi le raccourcissement des appels peut-il tromper sur le progrès du service ?","explanation":"Les appels courts cachent parfois des dossiers non résolus. B; A/C/D ne suivent pas des données."},{"number":32,"points":26,"correct":"C","options":["Le magasin peut publier une rémunération moyenne des fournisseurs sans distinguer les postes du prix payé par les clients.","Un label extérieur peut rendre la promesse crédible même si les versements et leur évolution ne sont pas consultables.","Rendre vérifiable la répartition du prix payé, grâce à des éléments chiffrés, datés et régulièrement mis à jour.","La répétition du terme équitable permet d'identifier une politique constante, sans qu'un calcul détaillé des prix soit nécessaire."],"passage":"Un magasin affirme pratiquer des prix équitables. Pour rendre l'engagement compréhensible, il explique la répartition du prix entre production, transport et distribution. Une formule valorisante devient plus informative lorsqu'elle renvoie à des éléments que l'on peut examiner. Le magasin mettra ces informations à jour lorsque ses conditions d'achat changent. Il souhaite que les clients puissent poser des questions précises, au lieu de devoir accepter une formule générale qui paraît positive sans expliquer ce qu'elle garantit réellement. Deux magasins revendiquent une rémunération équitable des producteurs. L'un publie des parts de prix et leur évolution, tandis que l'autre ne communique qu'un slogan. Le premier laisse au client des éléments pour vérifier la portée de sa promesse.","question":"Quelle propriété distingue l'engagement le plus vérifiable ?","explanation":"C exige une répartition documentée et actualisée des prix. A n'éclaire pas les différentes parts, B remplace la vérification par la réputation d'un label et D confond constance du message et preuve de rémunération."},{"number":33,"points":26,"correct":"D","options":["Les adhésions mesurent les achats évités si on les rapporte à la durée des prêts.","La durée d'utilisation des objets empruntés mesure l'économie de matière, les déplacements pouvant être considérés dans un bilan séparé.","L'ouverture de nouveaux points de retrait augmente le service rendu, ce qui compense la hausse des transports des équipements.","La réduction effective des achats et les coûts de transport ou d'entretien doivent être comparés dans l'usage réel."],"passage":"Un service de location réduit l'achat individuel d'équipements rarement utilisés. Son intérêt dépend toutefois de la durée de vie du matériel et des déplacements nécessaires. Le partage constitue une possibilité d'économie, pas une garantie indépendante de son organisation. Les responsables regardent les prêts achevés, les réparations et les trajets nécessaires. Cette observation permet de distinguer une intention de partage et une organisation qui remplace effectivement des achats individuels dans les conditions ordinaires d'utilisation. Un outil partagé remplace plusieurs achats individuels, mais son transport augmente après l'ouverture de nouveaux points de retrait. L'association mesure les trajets, la durée de vie et le nombre d'achats effectivement évités.","question":"Pourquoi le seul nombre d'adhérents au service ne démontre-t-il pas un bénéfice matériel ?","explanation":"D demande de comparer les achats réellement remplacés et les ressources consacrées au partage. A infère des achats évités des inscriptions, B laisse de côté l'effet des transports sur le bilan matériel et C présume une compensation non mesurée."},{"number":34,"points":26,"correct":"A","options":["Elle déplace certains achats vers les promotions au lieu d'en créer.","Elle empêche les clients de reconnaître les prochaines campagnes de réduction.","Elle augmente les ventes hors promotion dans la même proportion que les achats réduits.","Elle transforme les achats immédiats en achats récurrents indépendants de tout prix."],"passage":"Une boutique veut fidéliser ses clients par des réductions fréquentes. Certains attendent alors systématiquement la prochaine promotion. Le mécanisme qui devait stimuler l'achat immédiat transforme la perception du prix habituel et peut ralentir les ventes entre deux offres. Elle veut savoir si les offres augmentent réellement les achats ou les déplacent, et comprendre les attentes qu'elles installent chez les clients lorsqu'ils reviennent hors promotion. Les ventes grimpent pendant les semaines de promotion, mais restent faibles entre deux réductions. Les clients interrogés expliquent avoir reporté un achat qu'ils envisageaient au prix habituel.","question":"Quel effet non prévu l'opération commerciale semble-t-elle produire ?","explanation":"Les clients attendent le prochain rabais; A distingue déplacement et création de demande. C/D/B ne cadrent pas."},{"number":35,"points":26,"correct":"B","options":["Une procédure uniforme qui évite aux conseillers d'examiner les situations lorsque le document contractuel existe.","Expliquer les clauses et orienter les cas particuliers vers un spécialiste, lors d'une situation contractuelle inhabituelle.","La possibilité pour chaque conseiller de modifier les clauses afin d'adapter rapidement le contrat au client.","Une réponse identique formulée dans un langage plus simple, même lorsque la clause ne décrit pas le cas."],"passage":"Un contrat standard facilite la vente rapide. Mais lorsqu'une situation particulière apparaît, le client doit pouvoir comprendre ses options. Une entreprise forme donc ses équipes à expliquer les clauses plutôt qu'à renvoyer systématiquement vers un document difficile à lire. Les conseillers disposent d'exemples et peuvent reconnaître les cas qui demandent un avis spécialisé. L'entreprise souhaite conserver une procédure commune sans traiter toutes les questions comme si la lecture du même paragraphe apportait nécessairement une réponse suffisante. Un client rencontre une clause particulière sur le remboursement. Le conseiller présente les règles communes puis l'oriente vers un spécialiste lorsque le contrat ne couvre pas clairement son cas.","question":"Que doit permettre une bonne application d'un contrat standard ?","explanation":"B combine explication et orientation d'un cas particulier vers un spécialiste. A/D répètent une réponse standard insuffisante, C accorde au conseiller un pouvoir de modification non prévu."},{"number":36,"points":33,"correct":"D","options":["Le nombre de commandes antérieures reflète surtout la qualité des produits, les écarts de visibilité restant secondaires.","Les classements calculés sur les ventes mesurent la popularité sans modifier les décisions futures des clients.","Présenter plus souvent les nouveaux vendeurs permettrait de rendre immédiatement les historiques de ventes comparables.","L'exposition initiale favorise certaines offres, dont les nouvelles ventes renforcent ensuite la popularité affichée au classement suivant."],"passage":"Une plateforme classe les offres selon leur popularité. Les nouveaux fournisseurs, encore peu visibles, ont alors moins de chances d'obtenir les achats qui amélioreraient leur classement. Un indicateur censé refléter le succès peut aussi contribuer à reproduire l'avantage de ceux qui sont déjà installés. Les clients voient surtout les offres déjà achetées par d'autres et hésitent à essayer celles qui n'ont pas encore reçu d'avis. La plateforme étudie des moyens de présenter de nouveaux fournisseurs sans prétendre qu'ils auraient déjà la même expérience. Elle devra aussi expliquer les critères utilisés, afin que le classement ne paraisse pas une simple photographie indépendante des règles du site. Les responsables veulent distinguer la popularité observée et les effets produits par leur propre présentation. Cette distinction devient importante lorsqu'un outil d'information influence directement les possibilités de vendre et de se faire connaître. Le classement met en avant les offres ayant déjà reçu de nombreuses commandes. Les nouveaux vendeurs sont moins consultés et accumulent donc plus lentement les données qui feraient progresser leur position.","question":"Pourquoi la popularité affichée n'est-elle pas indépendante de l'algorithme ?","explanation":"D décrit la boucle entre classement, exposition et ventes qui renforcent ensuite le rang. A réduit le succès à la qualité; B ignore l'effet du classement sur les achats; C suppose qu'une exposition nouvelle efface l'historique."},{"number":37,"points":33,"correct":"D","options":["Mesurer d'abord le délai de livraison, puis traiter les reprises comme un coût extérieur au service étudié.","Rétablir les vérifications supprimées afin de retrouver les anciens délais sans analyser le motif des retours.","Suivre le nombre de contrôles retirés comme indicateur principal, même lorsque des erreurs restent non résolues.","Évaluer le temps total d'un dossier, y compris les reprises et corrections causées par les erreurs."],"passage":"Une entreprise revendique un service rapide en supprimant certaines étapes de contrôle. Les délais diminuent, mais les retours augmentent. Elle doit comparer le gain initial au travail supplémentaire causé par les erreurs. L'efficacité ne se mesure pas toujours au temps économisé à une seule étape du parcours. Les équipes doivent alors rouvrir les dossiers, répondre aux clients et organiser des échanges. Ces tâches mobilisent parfois davantage de moyens que les vérifications supprimées au départ. Les responsables vont comparer plusieurs organisations sur une durée suffisante. Ils ne souhaitent pas revenir automatiquement à chaque ancienne étape, mais identifier celles qui évitent un travail plus lourd ensuite. Le résultat sera décrit avec les retards et les erreurs, pas uniquement avec le délai initial. Dans le nouveau parcours, chaque dossier est traité deux minutes plus vite avant livraison, mais les reprises liées aux erreurs ajoutent trois minutes par dossier en moyenne. Le gain local devient une perte globale.","question":"Quel calcul de performance respecte cette observation ?","explanation":"D additionne temps initial et travail de reprise pour évaluer le processus. A/C omettent les corrections, B rétablit toutes les anciennes étapes sans examen de leur utilité."},{"number":38,"points":33,"correct":"B","options":["La disponibilité des accessoires influence la solidité matérielle sans intervenir dans la décision d'acheter un autre modèle.","Des campagnes de renouvellement peuvent raccourcir l'usage réel d'un produit encore techniquement fonctionnel à long terme.","La résistance des composants détermine presque toute la durée d'usage, les campagnes ayant un effet secondaire.","L'apparition de versions nouvelles indique qu'un appareil ancien n'a plus les fonctionnalités nécessaires aux utilisateurs."],"passage":"Un consommateur choisit un article durable pour limiter ses achats. Les campagnes du fabricant l'encouragent néanmoins à le remplacer souvent pour suivre de nouvelles versions. La durée de vie technique d'un produit ne garantit pas sa durée réelle d'usage si les pratiques commerciales poussent à son renouvellement. Les associations demandent des informations sur les réparations et les mises à jour permettant de continuer à utiliser l'appareil. Certains clients choisiraient de le garder plus longtemps s'ils savaient comment traiter une panne ou conserver les fonctions nécessaires. Le fabricant devra donc regarder ses services et ses messages commerciaux, pas seulement les caractéristiques du modèle neuf. Une promesse de durabilité peut perdre une partie de son sens lorsque toute l'organisation pousse à renouveler rapidement les achats. Les utilisateurs pourront comparer ces dimensions avant de juger si l'engagement annoncé correspond réellement à leurs possibilités d'usage dans le temps. Une machine fonctionne encore bien après dix ans, mais une nouvelle version est annoncée chaque année et ses accessoires ne sont plus mis à jour. Le propriétaire la remplace malgré sa durabilité matérielle.","question":"Quel écart l'exemple met-il en lumière ?","explanation":"B distingue capacité technique de durer et conservation effective influencée par campagnes et accessoires. A/C minimisent ces influences, D infère une obsolescence fonctionnelle sans preuve."},{"number":39,"points":33,"correct":"A","options":["Varier les horaires a révélé des usages absents du premier atelier, mais leur fréquence dans l'ensemble des clients reste à vérifier.","Le public du soir constitue une base de choix représentative si les participants effectuent les mêmes tâches que les groupes du jour.","La présence de journaux d'usage plus fréquents chez les personnes du soir prouve qu'elles seules ont besoin de sauvegardes.","La fonction de sauvegarde concerne surtout ceux qui ne comprennent pas encore la procédure et peut être supprimée après une formation."],"passage":"Une entreprise associe des clients à la conception d'un service. Les participants les plus disponibles ne représentent pas tous les futurs usagers. L'équipe cherche donc d'autres retours avant de stabiliser le projet. La participation fournit des informations précieuses sans supprimer la question de ceux qui n'ont pas pu participer. Elle organise des essais courts à plusieurs horaires et propose des échanges à distance pour ceux qui ne peuvent pas venir. Les personnes rencontrées ne deviennent pas pour autant un portrait exact de tous les clients. Elles apportent d'autres difficultés et d'autres façons d'utiliser le service. Les concepteurs souhaitent comparer ces retours avant de choisir des règles durables. Le travail participatif reste utile, mais doit être décrit avec ses conditions et ses limites. Un groupe enthousiaste peut aider à améliorer un projet sans suffire à garantir qu'il conviendra ensuite aux publics qui n'étaient pas présents lors de sa préparation. Les premiers ateliers sont fréquentés surtout par des personnes libres en journée. Des essais le soir révèlent d'autres besoins, notamment la possibilité d'effectuer une démarche en plusieurs fois. Une seconde phase associe des participants de jour et du soir aux mêmes tâches d'essai. Plusieurs personnes du soir signalent qu'elles interrompent une procédure en cours de route, alors que les premiers ateliers avaient surtout évalué les étapes réalisables d'une seule traite. Le nouveau dispositif recueille des journaux d'usage sur une semaine: quelques participants de jour connaissent eux aussi ces interruptions, mais leur fréquence est supérieure chez ceux qui ne peuvent se libérer qu'après le travail. Le service ajoute une fonction de sauvegarde provisoire. Le comité précise qu'il n'a pas recruté un échantillon représentatif de tous les clients et que les horaires d'atelier ne sont qu'un indice imparfait des conditions de vie. Il refuse d'en déduire que tous les usagers du soir ont les mêmes besoins ou que tous les usagers de jour réalisent les tâches sans interruption.","question":"Quelle conclusion peut guider la conception sans transformer un échantillon de volontaires en portrait de toute la clientèle ?","explanation":"A tient compte des besoins révélés par les essais variés sans extrapoler leur fréquence à tous les clients. B confond variété des volontaires et représentativité, C transforme un écart de fréquence en exclusivité, D attribue les interruptions à un manque de compréhension absent du passage."}]}$paper_15$::jsonb),
('tcf-reading-16','tcf-reading-2026-11-distractor-polish-v5',$paper_16${"id":"tcf-reading-16","title":"TCF Reading · Test 16","seconds":3600,"version":"tcf-reading-2026-11-distractor-polish-v5","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"D","options":["La tour","La salle haute","Le toit","La cour"],"passage":"La tour se visite uniquement l'après-midi cette semaine. La cour reste accessible dès neuf heures.\n\nUn panneau rappellera les créneaux de visite à l'entrée. Les billets peuvent être retirés à l'accueil pendant les horaires habituels.","question":"Quel espace ouvre le matin ?","explanation":"Le passage indique : « La tour se visite uniquement l'après-midi cette semaine. La cour reste accessible dès neuf heures. » Cela justifie la réponse : La cour."},{"number":2,"points":3,"correct":"C","options":["La pièce d'identité","Le billet de visite","Les sacs","Les lunettes"],"passage":"La visite des archives exige une pièce d'identité. Les sacs seront déposés dans les casiers avant l'entrée.\n\nLe personnel indiquera les règles de manipulation des documents.","question":"Que faut-il laisser au vestiaire ?","explanation":"Le passage indique : « La visite des archives exige une pièce d'identité. Les sacs seront déposés dans les casiers avant l'entrée. » Cela justifie la réponse : Les sacs."},{"number":3,"points":3,"correct":"D","options":["Le passage fermé","Le sommet des remparts","La sortie sans panneau","La porte sud"],"passage":"Le passage sous les remparts est fermé pour travaux. Suivez les panneaux bleus vers la porte sud.\n\nLa déviation ajoute quelques minutes de marche. Les agents demandent de ne pas déplacer les barrières, même lorsque le chantier semble inoccupé.","question":"Quelle direction faut-il prendre ?","explanation":"Le passage indique : « Le passage sous les remparts est fermé pour travaux. Suivez les panneaux bleus vers la porte sud. » Cela justifie la réponse : La porte sud."},{"number":4,"points":3,"correct":"B","options":["L'accès à toutes les rues","La visite accompagnée","La lecture des panneaux","L'entrée libre à l'exposition"],"passage":"L'exposition de maquettes est gratuite samedi. Les visites guidées restent sur réservation.\n\nLe personnel pourra expliquer les horaires et les places encore disponibles. Une entrée gratuite ne garantit pas automatiquement une place dans un groupe déjà complet.","question":"Quel service exige toujours une réservation ?","explanation":"Le passage indique : « L'exposition de maquettes est gratuite samedi. Les visites guidées restent sur réservation. » Cela justifie la réponse : La visite accompagnée."},{"number":5,"points":9,"correct":"D","options":["Acheter une usine","Revoir uniquement le château","Éviter toute activité culturelle","Découvrir une histoire moins familière"],"passage":"J'ai choisi la visite du quartier industriel. Nous connaissons déjà le château et je voudrais découvrir un autre aspect de la ville.\n\nLe guide parlera aussi des habitants qui travaillaient dans les anciens ateliers. Nous pourrons comparer ce parcours avec les visites habituelles, sans chercher uniquement les monuments les plus connus.","question":"Pourquoi choisir cette visite ?","explanation":"Le passage indique : « J'ai choisi la visite du quartier industriel. Nous connaissons déjà le château et je voudrais découvrir un autre aspect de la ville. » Cela justifie la réponse : Découvrir une histoire moins familière."},{"number":6,"points":9,"correct":"B","options":["Prouver la propriété d'un bâtiment","Observer les transformations du quartier","Remplacer la carte de transport","Décorer uniquement la salle d'accueil"],"passage":"Apportez une photo ancienne de votre rue, si vous en avez une. Nous la comparerons aux lieux actuels pendant la promenade.\n\nLes images seront observées avec leur date, lorsque celle-ci est connue. Vous pourrez repartir avec les originaux après leur numérisation pour le groupe.","question":"À quoi servira la photo ?","explanation":"Le passage indique : « Apportez une photo ancienne de votre rue, si vous en avez une. Nous la comparerons aux lieux actuels pendant la promenade. » Cela justifie la réponse : Observer les transformations du quartier."},{"number":7,"points":9,"correct":"A","options":["Le projet présenté","Le numéro de téléphone uniquement","L'horaire initial","La date de publication du bulletin"],"passage":"La réunion sur la place rénovée est avancée d'une heure. Le plan présenté ne change pas ; seule l'heure a été modifiée.\n\nLes participants recevront une confirmation et pourront préparer leurs questions. Les responsables souhaitent garder le même temps d'échange malgré ce changement d'organisation.","question":"Quel élément est conservé ?","explanation":"Le passage indique : « La réunion sur la place rénovée est avancée d'une heure. Le plan présenté ne change pas ; seule l'heure a été modifiée. » Cela justifie la réponse : Le projet présenté."},{"number":8,"points":9,"correct":"C","options":["Le retirer dans la boutique voisine","Acheter une place assise spéciale","Le demander à l'accueil","Attendre la fin du parcours"],"passage":"Le musée prête des sièges pliants pour suivre la visite. Demandez-les à l'accueil avant le départ du groupe.\n\nLes sièges doivent être rapportés avant de quitter le musée. Le personnel expliquera les endroits où ils peuvent être utilisés sans gêner les passages.","question":"Comment obtenir ce matériel ?","explanation":"Le passage indique : « Le musée prête des sièges pliants pour suivre la visite. Demandez-les à l'accueil avant le départ du groupe. » Cela justifie la réponse : Le demander à l'accueil."},{"number":9,"points":9,"correct":"D","options":["Exposer un travail déjà terminé","Gagner un prix dès la première séance","Éviter toute pratique","Se former sans compétition"],"passage":"Je participerai à l'atelier de photographie plutôt qu'au concours. Je veux apprendre sans avoir à présenter immédiatement un résultat.\n\nL'animateur présentera plusieurs techniques et laissera chacun essayer à son rythme. Je pourrai ensuite décider si je souhaite montrer des images lors d'une prochaine rencontre.","question":"Quel besoin guide ce choix ?","explanation":"Le passage indique : « Je participerai à l'atelier de photographie plutôt qu'au concours. Je veux apprendre sans avoir à présenter immédiatement un résultat. » Cela justifie la réponse : Se former sans compétition."},{"number":10,"points":9,"correct":"A","options":["Une personne ayant un souvenir à raconter","Uniquement un propriétaire d'archives papier","Un vendeur de matériel audio","Seulement un historien diplômé"],"passage":"Notre collecte de souvenirs accepte aussi des récits enregistrés. Il n'est pas nécessaire de posséder un document écrit.\n\nUne permanence permettra de choisir la forme de la contribution et de vérifier les informations associées. Les personnes restent libres de ne pas publier certains détails trop personnels.","question":"Qui peut contribuer ?","explanation":"Le passage indique : « Notre collecte de souvenirs accepte aussi des récits enregistrés. Il n'est pas nécessaire de posséder un document écrit. » Cela justifie la réponse : Une personne ayant un souvenir à raconter."},{"number":11,"points":15,"correct":"B","options":["Une fermeture au public","Un nouvel usage respectant des éléments du bâtiment","Une démolition complète","Un retour obligatoire au commerce d'origine"],"passage":"Une ancienne halle devient une bibliothèque. Les grandes ouvertures sont conservées, tandis que l'intérieur est adapté aux collections et aux lecteurs.\n\nLes architectes ont prévu des espaces calmes et des tables de groupe, tout en gardant visible le volume de la halle. Les futurs lecteurs pourront visiter un secteur témoin avant l'ouverture complète. La ville souhaite éviter qu'une conservation purement décorative laisse le bâtiment inutilisé. Elle explique donc les choix techniques et les contraintes du nouvel accueil. Les éléments anciens ne seront pas tous maintenus au même endroit, mais ceux qui racontent le mieux le fonctionnement du lieu feront l'objet d'une présentation accessible au public.","question":"Quel type de transformation est réalisé ?","explanation":"Le passage indique : « Une ancienne halle devient une bibliothèque. Les grandes ouvertures sont conservées, tandis que l'intérieur est adapté aux collections et aux lecteurs. » Cela justifie la réponse : Un nouvel usage respectant des éléments du bâtiment."},{"number":12,"points":15,"correct":"C","options":["La taille des dossiers municipaux","Les horaires des magasins uniquement","La mémoire des pratiques locales","Le prix des panneaux routiers"],"passage":"Des habitants identifient les noms anciens des rues sur un plan. Le projet recueille aussi les usages populaires qui n'apparaissent pas dans les archives administratives.\n\nLes témoins indiquent où ils ont entendu un nom et à quelle période il était utilisé. Les animateurs rapprochent ces récits des plans conservés, sans effacer les différences. Le projet ne cherche pas à remplacer les noms actuels par une version unique supposée authentique.","question":"Quelle information complète les sources officielles ?","explanation":"Le passage indique : « Des habitants identifient les noms anciens des rues sur un plan. Le projet recueille aussi les usages populaires qui n'apparaissent pas dans les archives administratives. » Cela justifie la réponse : La mémoire des pratiques locales."},{"number":13,"points":15,"correct":"A","options":["La compatibilité avec les matériaux existants","La dureté maximale à tout prix","La rapidité de la publicité","La couleur de l'emballage"],"passage":"Un chantier restaure les joints d'un pont avec un matériau compatible avec la pierre. Un produit plus dur pourrait provoquer des dégradations au lieu de protéger l'ensemble.\n\nUne partie du chantier servira de test pour observer le résultat. Le responsable souhaite éviter qu'un produit paraissant plus solide soit considéré comme automatiquement meilleur. Les propriétés doivent être appréciées ensemble, avec les contraintes du bâtiment. Des informations seront proposées aux riverains, afin qu'ils comprennent pourquoi les travaux ne consistent pas simplement à remplacer un ancien matériau par le plus récent ou le plus résistant disponible chez un fournisseur.","question":"Quel critère guide le choix ?","explanation":"Le passage indique : « Un chantier restaure les joints d'un pont avec un matériau compatible avec la pierre. Un produit plus dur pourrait provoquer des dégradations au lieu de protéger l'ensemble. » Cela justifie la réponse : La compatibilité avec les matériaux existants."},{"number":14,"points":15,"correct":"D","options":["Éteindre tous les services publics","Augmenter la puissance partout","Rendre les monuments invisibles en journée","Maintenir la visibilité avec moins d'éclairage"],"passage":"Une ville éclaire moins fortement ses monuments la nuit. Les visiteurs peuvent encore les voir, mais la consommation et la gêne lumineuse diminuent.\n\nLes techniciens ont réalisé plusieurs essais et recueilli les remarques sur les principaux points de vue. Les riverains peuvent encore se repérer dans les rues, tandis que les projecteurs décoratifs fonctionnent moins longtemps. Le service distingue donc les besoins de circulation et la mise en scène des façades. Il ne veut pas présenter tous les éclairages comme également nécessaires ou également inutiles.","question":"Quel compromis est recherché ?","explanation":"Le passage indique : « Une ville éclaire moins fortement ses monuments la nuit. Les visiteurs peuvent encore les voir, mais la consommation et la gêne lumineuse diminuent. » Cela justifie la réponse : Maintenir la visibilité avec moins d'éclairage."},{"number":15,"points":15,"correct":"B","options":["Uniquement des conseils de jardinage","Une compréhension de l'histoire du lieu","Une interdiction de marcher","Le programme des trains actuels"],"passage":"Une ancienne voie d'eau est remise en valeur comme promenade. Des panneaux expliquent son rôle dans le transport des marchandises, pas seulement ses qualités paysagères.\n\nDes photographies montrent les chargements, les chemins utilisés et les bâtiments liés à cette activité. Les promeneurs peuvent comparer ces repères avec ce qui reste visible aujourd'hui. Le projet veut éviter qu'un aménagement agréable efface entièrement le sens du site. Les informations ne demanderont pas aux visiteurs de suivre un cours complet, mais leur donneront des éléments pour comprendre pourquoi la voie existe et comment elle participait à la vie locale.","question":"Que souhaite transmettre l'aménagement ?","explanation":"Le passage indique : « Une ancienne voie d'eau est remise en valeur comme promenade. Des panneaux expliquent son rôle dans le transport des marchandises, pas seulement ses qualités paysagères. » Cela justifie la réponse : Une compréhension de l'histoire du lieu."},{"number":16,"points":15,"correct":"C","options":["Le stock de produits à vendre","Les plans des parkings actuels","La mémoire du travail vécu","Les tarifs des visites"],"passage":"Un atelier recueille les souvenirs d'ouvriers d'une usine fermée. Les organisateurs veulent conserver l'expérience des personnes, au-delà des machines déjà exposées.\n\nLes personnes décrivent des horaires, des gestes et des relations que les objets seuls ne permettent pas de connaître. Les récits sont datés et préparés avec les participants, afin d'éviter une image uniforme de toutes les périodes. Le musée souhaite conserver les désaccords et les changements importants lorsqu'ils aident à comprendre l'activité. Il ne présente pas un souvenir individuel comme le résumé de toute l'usine.","question":"Quel aspect du patrimoine est complété ?","explanation":"Le passage indique : « Un atelier recueille les souvenirs d'ouvriers d'une usine fermée. Les organisateurs veulent conserver l'expérience des personnes, au-delà des machines déjà exposées. » Cela justifie la réponse : La mémoire du travail vécu."},{"number":17,"points":15,"correct":"B","options":["Démolition et publicité","Accessibilité et préservation","Stationnement et circulation rapide","Fermeture et abandon"],"passage":"Un immeuble ancien accueille un ascenseur dans une extension discrète. L'objectif est de permettre l'accès tout en limitant les transformations des espaces historiques.\n\nLe parcours d'entrée et les passages entre les salles ont été examinés avec plusieurs usagers. Les spécialistes souhaitent éviter une solution annoncée comme accessible mais difficile à utiliser au quotidien. Le projet ne demande pas de choisir entre l'accueil actuel et la valeur du bâtiment : il cherche une intervention qui réponde réellement aux besoins en limitant les effets sur ce qui doit être préservé pour les visiteurs et les habitants des prochaines années.","question":"Quels besoins sont associés ?","explanation":"Le passage indique : « Un immeuble ancien accueille un ascenseur dans une extension discrète. L'objectif est de permettre l'accès tout en limitant les transformations des espaces historiques. » Cela justifie la réponse : Accessibilité et préservation."},{"number":18,"points":15,"correct":"A","options":["Vérifier la fonction de la fontaine","Boire à toutes les fontaines décoratives","Ignorer les indications","Se fier uniquement à la forme"],"passage":"Une carte présente les fontaines de la ville et indique celles qui délivrent de l'eau potable. Les visiteurs ne doivent pas déduire cette possibilité de leur seule apparence.\n\nCertains bassins ont seulement une fonction décorative, tandis que d'autres sont entretenus pour cet usage précis. Les agents mettront la carte à jour si une installation doit être temporairement arrêtée. Les visiteurs pourront retrouver les indications sur place et signaler un problème. Le service souhaite que l'information reste simple sans encourager une déduction fondée sur le seul aspect de la pierre ou sur la présence d'un robinet.","question":"Quelle précaution est demandée ?","explanation":"Le passage indique : « Une carte présente les fontaines de la ville et indique celles qui délivrent de l'eau potable. Les visiteurs ne doivent pas déduire cette possibilité de leur seule apparence. » Cela justifie la réponse : Vérifier la fonction de la fontaine."},{"number":19,"points":15,"correct":"A","options":["Des constructions récentes méritent aussi d'être comprises","Les quartiers modernes sont tous identiques","Les promenades doivent éviter les habitants","Seuls les châteaux ont une histoire"],"passage":"Une association propose des balades dans les quartiers récents. Elle estime que le patrimoine urbain ne se limite pas aux centres très anciens.\n\nLes guides présentent les choix de construction, les espaces partagés et les transformations demandées par les résidents. Ils recueillent aussi les souvenirs de personnes arrivées lors des premières années. L'association ne prétend pas que chaque bâtiment doit devenir un monument protégé. Elle souhaite ouvrir un regard sur des lieux souvent considérés comme ordinaires et sans histoire.","question":"Quelle idée défend-elle ?","explanation":"Le passage indique : « Une association propose des balades dans les quartiers récents. Elle estime que le patrimoine urbain ne se limite pas aux centres très anciens. » Cela justifie la réponse : Des constructions récentes méritent aussi d'être comprises."},{"number":20,"points":21,"correct":"C","options":["Confirmer automatiquement le premier plan","Éviter toute consultation","Observer les usages avant de fixer l'aménagement","Réduire le nombre d'arbres sans raison"],"passage":"Une ville transforme une place après une phase d'essai. Les bancs provisoires ont révélé que certains emplacements étaient trop exposés au soleil. Le plan définitif est modifié en conséquence. Les usagers ont pu déplacer les sièges et noter les heures où ils évitaient certains secteurs. Les agents ont également observé les trajets des livraisons et des personnes se déplaçant lentement. Ces retours ont révélé des contraintes absentes des premières images du projet. La ville souhaite que la phase provisoire serve à apprendre quelque chose, et pas seulement à faire accepter un plan déjà arrêté sans possibilité de modification.","question":"À quoi a servi l'essai ?","explanation":"Le passage indique : « Une ville transforme une place après une phase d'essai. Les bancs provisoires ont révélé que certains emplacements étaient trop exposés au soleil. Le plan définitif est modifié en conséquence. » Cela justifie la réponse : Observer les usages avant de fixer l'aménagement."},{"number":21,"points":21,"correct":"A","options":["Inclure des acteurs longtemps peu visibles","Remplacer l'histoire par une liste de prix","Présenter uniquement les visiteurs actuels","Supprimer toute information sur le palais"],"passage":"Un musée raconte l'histoire d'un palais en mentionnant aussi les personnes qui l'entretenaient. Le récit ne se limite plus à ses propriétaires célèbres. Les commissaires souhaitent éviter qu'un grand bâtiment soit raconté uniquement par la vie de quelques figures connues. Les visiteurs pourront relier les pièces à des usages précis et découvrir les tâches nécessaires à leur entretien. Le musée garde les récits célèbres, mais les replace dans une organisation plus large dont dépendait le fonctionnement quotidien du palais.","question":"Quelle évolution du regard est proposée ?","explanation":"Le passage indique : « Un musée raconte l'histoire d'un palais en mentionnant aussi les personnes qui l'entretenaient. Le récit ne se limite plus à ses propriétaires célèbres. » Cela justifie la réponse : Inclure des acteurs longtemps peu visibles."},{"number":22,"points":21,"correct":"B","options":["Éviter de mentionner son origine","Préserver le sens de l'objet conservé","Augmenter automatiquement sa valeur","Garantir la réouverture du commerce"],"passage":"Une commune garde une ancienne enseigne après la fermeture du commerce. Elle la documente pour qu'elle reste compréhensible aux générations qui n'ont pas connu la boutique. La notice indiquera le type d'activité, sa période et les sources utilisées pour la décrire. Les habitants pourront apporter une précision lors d'une rencontre. Le service ne cherche pas à promettre le retour d'un commerce disparu, mais à garder des repères dans une rue qui change.","question":"Pourquoi ajouter des informations ?","explanation":"Le passage indique : « Une commune garde une ancienne enseigne après la fermeture du commerce. Elle la documente pour qu'elle reste compréhensible aux générations qui n'ont pas connu la boutique. » Cela justifie la réponse : Préserver le sens de l'objet conservé."},{"number":23,"points":21,"correct":"D","options":["Réserver la place aux voitures","Interdire toute présence humaine","Accepter toute nuisance","Organiser les usages plutôt que les supprimer"],"passage":"Des riverains acceptent des événements sur une place historique, mais demandent des horaires et une gestion du bruit. Leur proposition ne vise pas à transformer le lieu en espace sans vie. Ils proposent des jours et des limites discutés avec les organisateurs. Les associations pourront continuer à préparer des fêtes, mais devront prévoir le rangement et l'accès aux logements. Le comité veut éviter un débat réduit à accepter toute activité ou à réclamer le silence permanent.","question":"Quelle position adoptent-ils ?","explanation":"Le passage indique : « Des riverains acceptent des événements sur une place historique, mais demandent des horaires et une gestion du bruit. Leur proposition ne vise pas à transformer le lieu en espace sans vie. » Cela justifie la réponse : Organiser les usages plutôt que les supprimer."},{"number":24,"points":21,"correct":"B","options":["Transformer tous les quais en exposition","Permettre aux usagers de se repérer","Limiter l'accès aux historiens","Supprimer les horaires"],"passage":"La rénovation d'une gare conserve des éléments anciens et améliore l'orientation. Les panneaux patrimoniaux sont placés sans masquer les informations nécessaires aux voyageurs. Les premiers voyageurs essaieront le parcours avec leurs bagages et pourront signaler les points difficiles à comprendre. Les panneaux historiques resteront consultables dans des zones où l'on peut s'arrêter sans bloquer les passages. Le projet souhaite rendre l'histoire visible, sans demander à un usager pressé de traverser une exposition pour trouver sa correspondance.","question":"Quelle priorité pratique demeure ?","explanation":"Le passage indique : « La rénovation d'une gare conserve des éléments anciens et améliore l'orientation. Les panneaux patrimoniaux sont placés sans masquer les informations nécessaires aux voyageurs. » Cela justifie la réponse : Permettre aux usagers de se repérer."},{"number":25,"points":21,"correct":"A","options":["On confondrait une intention documentée avec une gare effectivement construite, alors que d'autres sources décrivent un jardin.","La date du plan permettrait de dater la photographie puisqu'elle représente le même emplacement dans le quartier.","Les images de 1905 montreraient seulement que le projet avait déjà été discuté avant la construction de la gare.","L'écart entre plan et photographie rendrait le document de 1890 peu utile pour étudier les décisions de l'époque."],"passage":"Une archive montre un projet jamais construit. Les médiateurs le présentent comme une intention de l'époque, pas comme la preuve d'un état ancien de la ville. La notice expliquera qui avait préparé le plan, dans quelles circonstances et pourquoi il n'a pas été réalisé. Le musée souhaite que les archives servent à comprendre des intentions et des débats, sans transformer toute représentation ancienne en preuve de ce qui a réellement existé sur le terrain. Un plan daté de 1890 propose une gare sur la place; des photographies de 1905 montrent que l'emplacement est resté un jardin. La notice présente les deux documents pour distinguer le souhait des décideurs du résultat observé.","question":"Quelle erreur ferait-on en utilisant le plan de 1890 comme preuve de l'existence de la gare ?","explanation":"A distingue un projet d'une gare construite, alors que les photos montrent un jardin plus tard. B confond les dates des sources, C postule une construction absente et D jette à tort l'information sur les intentions."},{"number":26,"points":21,"correct":"B","options":["Sélectionner la finition la moins visible en conditions sèches, indépendamment de ses usages réels.","Comparer intégration esthétique, sécurité et entretien, sans réduire le projet à l'apparence initiale.","Privilégier l'apparence immédiatement, puis reporter l'examen de l'usure après la pose définitive.","Retenir le revêtement le plus ancien disponible, même lorsque ses qualités d'adhérence sont inconnues."],"passage":"Une rue reçoit des revêtements moins glissants à proximité d'un monument. L'équipe cherche une solution visuellement discrète, mais refuse que l'apparence rende le passage dangereux. Les essais seront menés avec des personnes utilisant des aides à la marche et avec le service chargé de l'entretien. Les spécialistes devront tenir compte de la pluie et de l'usure, pas seulement de l'aspect le jour de la pose. La commune veut une solution qui reste praticable et lisible, tout en respectant l'ensemble architectural. Une première dalle semble parfaitement adaptée au style de la place, mais devient très glissante sous la pluie. Une seconde est légèrement plus visible tout en restant sûre après usure; l'équipe consulte les utilisateurs.","question":"Quel choix correspond au raisonnement de la commune ?","explanation":"Les essais portent sur style, pluie, usure et accessibilité. B; les autres privilégient un seul critère."},{"number":27,"points":21,"correct":"A","options":["L'accueil peut sécuriser les visites sans transformer les pièces patrimoniales essentielles.","L'accueil réduit les visites aux ateliers pour contrôler les files.","La conversion d'une pièce sert surtout à protéger les œuvres, les déplacements des visiteurs pouvant rester organisés comme auparavant.","L'aménagement autorise davantage d'entrées, en transférant une partie de la surveillance des salles aux visiteurs eux-mêmes."],"passage":"Une maison d'artiste conserve plusieurs pièces intactes et transforme une autre en espace d'accueil. Le projet distingue les besoins de présentation des conditions nécessaires à la visite. L'équipe prépare les flux de visiteurs, les possibilités de repos et les conditions de surveillance des œuvres. Elle souhaite éviter qu'une ouverture trop fragile oblige ensuite à fermer des salles ou à interrompre les visites. La maison manque d'espace pour les files d'attente; convertir une pièce secondaire permet de contrôler l'accès tout en gardant les ateliers intacts. L'équipe cherche à éviter une fréquentation qu'elle ne pourrait surveiller.","question":"Pourquoi transformer une pièce plutôt que conserver tout le bâtiment dans le même état ?","explanation":"A combine une circulation sûre et la préservation des pièces essentielles. B suppose une réduction des visites des ateliers, C minimise le problème de circulation, D retire une surveillance que l'équipe entend assurer."},{"number":28,"points":21,"correct":"A","options":["Parce que le nom choisi doit rester identifiable sans confusion, notamment lors des appels aux services de secours.","La commission peut retenir les propositions des services techniques dès qu'un autre nom crée un risque potentiel de confusion.","Les noms honorant une personnalité historique devraient être réservés aux rues éloignées des grands axes d'urgence.","Un nom déjà populaire peut être écarté sans nouvelle consultation dès lors que sa prononciation est jugée ambiguë."],"passage":"Des habitants participent au choix de nouveaux noms de rues. Une commission vérifie les propositions pour éviter les doublons qui compliqueraient l'orientation et les secours. Les services vérifient aussi la lisibilité sur les plans et la prononciation possible lors d'un appel. Les propositions historiques ou culturelles seront examinées avec ces contraintes. La commission souhaite que le choix reste compréhensible, plutôt que donner l'impression de rejeter une contribution sans raison. Un nom proposé honore une personnalité locale mais ressemble à celui d'une avenue voisine. Les services craignent des confusions lors d'appels aux secours et présentent une variante aux habitants.","question":"Pourquoi la commission ne retient-elle pas automatiquement le nom populaire ?","explanation":"A associe hommage et capacité d'identifier sans erreur une rue lors d'un secours. B privilégie les seuls services, C exclut arbitrairement des noms historiques et D écarte la variante soumise aux habitants."},{"number":29,"points":21,"correct":"C","options":["La restauration plus récente remplace l'histoire de l'ancienne pierre dès lors que la façade paraît homogène.","La présence d'une pierre d'origine reste le principal indice, même si sa surface a été retravaillée plus tard.","Les matériaux et retouches d'une même pierre peuvent témoigner de différentes périodes d'entretien, sans effacer son origine.","Les différences de couleur permettent de conclure que l'élément a été remplacé entièrement lors de la restauration."],"passage":"Une visite montre des traces de réparations successives sur un bâtiment. Elles témoignent de son histoire matérielle plutôt que d'un état originel resté inchangé. Les médiateurs montrent les différences de matière et expliquent les circonstances connues de chaque réparation. Ils ne cherchent pas à cacher toutes les interventions pour présenter un bâtiment resté inchangé. Le public pourra comprendre comment le lieu a été entretenu, abîmé et adapté selon les périodes. Sur une façade, une pierre ancienne porte des traces d'une restauration du XXe siècle. L'équipe indique les deux périodes plutôt que de présenter l'élément comme entièrement original ou entièrement récent.","question":"Quelle interprétation des traces rend le mieux compte de l'histoire matérielle ?","explanation":"C restitue des interventions de différentes périodes dans un même élément. A efface la couche ancienne; B minimise les traces de restauration; D conclut à un remplacement complet que l'observation ne prouve pas."},{"number":30,"points":26,"correct":"D","options":["Limiter les transformations aux bâtiments qui n'ont plus aucun usage quotidien.","Supprimer le classement patrimonial pour permettre n'importe quelle intervention.","Conserver toute règle existante même lorsque son effet exclut une partie des usagers.","Concilier préservation du patrimoine et accès réel par une intervention adaptée."],"passage":"La protection d'un centre ancien peut rendre certaines adaptations plus difficiles. Un urbaniste propose de discuter les effets concrets des règles : préserver des qualités ne suppose pas de refuser toute évolution des usages. Les personnes chargées du projet consulteront les usagers et les spécialistes avant de définir les interventions. Elles souhaitent distinguer une transformation nécessaire et une modification qui ne répondrait à aucun besoin clairement expliqué dans le dossier. Un escalier classé est difficile à utiliser pour certains habitants. Le projet étudie une rampe réversible qui laisse les éléments d'origine lisibles sans empêcher l'accès aux activités du lieu.","question":"Quel critère guide ici le traitement d'une adaptation nécessaire ?","explanation":"La rampe réversible vise conservation et usage. D. C/B/A suppriment une dimension du compromis."},{"number":31,"points":26,"correct":"D","options":["Les gestes reconstitués à partir des images décrivent les pratiques anciennes avec plus de fidélité que les récits individuels.","La démonstration restitue directement le geste historique, au-delà des sources écrites.","La valeur de l'explication repose sur le geste visible, les précisions matérielles ou historiques devenant moins importantes.","Elle peut éclairer l'usage pratique de l'objet sans prétendre reproduire exactement toutes les expériences anciennes."],"passage":"Un objet quotidien devient une pièce de musée. Sa conservation change le regard porté sur lui, mais peut aussi l'éloigner des gestes qui expliquaient son usage. Les médiateurs ajoutent des démonstrations pour rendre cette dimension perceptible. La démonstration sera présentée comme une interprétation appuyée sur des sources. Elle donnera des repères sur les gestes et les matières, sans faire croire que l'expérience d'un ancien utilisateur peut être entièrement reproduite dans une salle actuelle. La présentation d'un outil agricole ancien comprend une démonstration à partir de descriptions et d'images historiques. Le guide précise que le geste reconstitué peut différer de celui de certains utilisateurs passés.","question":"Quelle valeur et quelle limite la démonstration doit-elle conserver ?","explanation":"D conserve la valeur illustrative de la démonstration sans la confondre avec la reproduction exacte d'expériences passées. A suppose une fidélité supérieure non établie, B prend une reconstitution pour un accès direct et C minore les sources et matières que le guide utilise."},{"number":32,"points":26,"correct":"C","options":["Le besoin d'éviter tout point de vue déjà diffusé sur les réseaux sociaux.","La présence d'un point de vue connu qui rend nécessairement toute visite inutile.","L'image célèbre risque de résumer abusivement un lieu aux multiples histoires.","L'impossibilité de photographier un monument après avoir consulté son histoire."],"passage":"Les touristes photographient un monument depuis un même point, devenu célèbre en ligne. Le gestionnaire ouvre un second parcours pour montrer des aspects moins connus. Il ne conteste pas la première vue, mais veut éviter qu'elle résume toute l'expérience du lieu. Les nouveaux parcours expliquent d'autres usages et des points de vue complémentaires. Les visiteurs resteront libres de regarder l'image connue, mais disposeront de moyens pour ne pas réduire le site à ce seul cadrage déjà rencontré ailleurs. Le nouveau circuit montre des traces d'un autre usage du monument et explique pourquoi la photographie célèbre ne fait apparaître qu'une façade. Les visiteurs peuvent choisir les deux itinéraires.","question":"Quel défaut du parcours unique le second itinéraire cherche-t-il à limiter ?","explanation":"Le nouvel itinéraire enrichit le regard sans interdire la vue célèbre; C. B/D/A surinterprètent."},{"number":33,"points":26,"correct":"D","options":["Les marques d'usure garantissent mieux la stabilité que des pierres neuves, ce qui explique leur conservation.","Conserver les traces anciennes oblige à laisser les fissures en place pour préserver la lecture des usages.","Le remplacement d'une pierre usée supprimerait toutes les preuves de la présence d'un lavoir dans ce quartier.","Les marques d'usage documentent l'histoire, contrairement aux fissures qui représentent un risque pour la conservation du lavoir."],"passage":"Une ville restaure un ancien lavoir tout en conservant les marques d'usure. Les pierres abîmées ne sont pas toutes remplacées : certaines portent les traces des gestes répétés. La valeur historique ne se réduit pas à une apparence parfaitement neuve. Le choix de garder une marque n'est donc pas une absence d'intervention, mais une décision à expliquer dans l'ensemble du travail de restauration. Les artisans conservent un creux dans la pierre du lavoir, formé par des années de frottement, tout en réparant une fissure qui menaçait la stabilité. La décision sépare traces d'usage et désordres techniques.","question":"Pourquoi conserver une marque d'usure plutôt que restaurer toute la pierre à neuf ?","explanation":"D distingue les traces d'usage historiquement informatives des fissures dangereuses. A leur attribue une résistance non prouvée; B confond conservation des traces et réparation nécessaire; C généralise la perte d'un indice à toute l'histoire du quartier."},{"number":34,"points":26,"correct":"D","options":["La fonction réelle du lieu peut être déduite du seul plan dès lors que sa date est connue.","Les témoignages ne peuvent aider à comprendre les transformations puisqu'ils restent subjectifs.","Le plan devient faux dès que l'usage réel diffère de l'intention politique initiale.","Il faut distinguer les intentions de conception des pratiques constatées pour comprendre l'histoire de l'espace."],"passage":"Une exposition sur l'urbanisme confronte plans officiels et récits de résidents. Les premiers montrent des intentions et des règles ; les seconds révèlent des usages parfois différents. Comprendre la ville suppose de regarder ce qui a été prévu et ce qui a été vécu. L'exposition ne cherche pas un gagnant entre ces sources, mais ce que leur rapprochement rend visible sur la construction et l'évolution des espaces urbains. Un plan municipal prévoit une grande place publique, tandis que des récits décrivent son emploi comme parking pendant des années. Les deux sources éclairent des étapes différentes de la vie du lieu.","question":"Que révèle l'écart entre le plan et les récits ?","explanation":"Les plans sont des intentions, les récits les usages. D les rapproche sans en annuler un."},{"number":35,"points":26,"correct":"B","options":["Un ancien bâtiment reste préférable si ses matériaux peuvent être conservés, même lorsque son adaptation coûte davantage.","La pertinence du réemploi dépend des travaux requis pour accueillir les nouvelles fonctions dans ce bâtiment ancien.","Une réutilisation n'est efficace que si la nouvelle fonction correspond assez étroitement à celle prévue lors de la construction.","L'intérêt historique du bâtiment devrait primer dans l'analyse, puisqu'il assure une meilleure adaptation aux usages futurs."],"passage":"La réutilisation d'un bâtiment semble éviter une construction neuve. Son intérêt doit néanmoins être étudié avec les adaptations nécessaires et les besoins futurs. Conserver à tout prix une structure très inadaptée peut déplacer les coûts plutôt que résoudre le problème d'usage. Les études compareront les possibilités avant de choisir. Elles éviteront de considérer la seule présence d'un ancien bâtiment comme une réponse suffisante, sans examiner les travaux qu'il demande pour accueillir correctement les activités prévues. La transformation d'un entrepôt ancien en école demande des travaux d'isolation très lourds, alors qu'un autre bâtiment proche pourrait être réutilisé avec moins de modifications. Le conseil compare les coûts et l'usage futur.","question":"Pourquoi la réutilisation de n'importe quel bâtiment n'est-elle pas automatiquement optimale ?","explanation":"B impose de confronter les travaux nécessaires à la fonction scolaire et d'autres lieux disponibles. A privilégie automatiquement la conservation matérielle, C exige une continuité d'usage non prévue et D déduit à tort l'adéquation fonctionnelle du prestige patrimonial."},{"number":36,"points":33,"correct":"C","options":["Il privilégie les témoignages des habitants anciens comme version de référence, puis invite les nouveaux à les illustrer.","Il rassemble les souvenirs selon une chronologie commune pour atténuer les différences entre les personnes.","Il recueille plusieurs expériences situées et les met en relation, sans condition d'ancienneté pour contribuer.","Il traite les usages récents du quartier comme une mémoire indépendante de l'histoire partagée documentée."],"passage":"Un quartier souhaite valoriser son histoire. Les habitants les plus anciens possèdent beaucoup de souvenirs, mais les nouveaux arrivants contribuent aussi à la vie actuelle du lieu. Le projet accueille les deux perspectives. Le patrimoine partagé peut se construire à partir d'héritages différents sans exiger une ancienneté identique pour participer. Les personnes arrivées récemment découvrent les récits anciens et peuvent apporter leurs propres repères. Le comité souhaite que la transmission crée des rencontres plutôt qu'un examen implicite de la légitimité à parler du quartier. Les archives restent importantes, mais ne résument pas toute la vie du lieu. Les prochaines activités associeront donc plusieurs générations et périodes d'installation. Cette ouverture permettra de discuter ce que les habitants partagent et ce qu'ils découvrent différemment, sans exiger qu'ils possèdent les mêmes souvenirs ou qu'un seul groupe définisse définitivement le sens de l'espace commun. Lors d'un atelier, une habitante arrivée récemment raconte un usage actuel de la place, tandis qu'un ancien résident présente une photographie du même lieu trente ans plus tôt. Le comité expose les deux sans assimiler leurs expériences.","question":"Comment le projet construit-il une mémoire commune sans effacer les différences ?","explanation":"C met en relation souvenirs anciens et usages nouveaux sans condition d'ancienneté. A hiérarchise les voix, B cherche à gommer les écarts, D sépare les récits plutôt que de les confronter."},{"number":37,"points":33,"correct":"A","options":["Une restitution visuelle peut transmettre une image sans constituer la continuité intégrale des éléments historiques.","La ressemblance de la façade permet de traiter les fonctions et les matériaux reconstruits comme ceux d'origine.","La valeur historique d'une reconstruction tient uniquement à son authenticité matérielle, sans apport visuel possible.","La date des photographies suffit à justifier l'emploi des matériaux récents comme s'ils avaient été conservés."],"passage":"La reconstruction d'une façade disparue peut redonner une image familière à une place. Elle ne restitue pourtant ni tous les matériaux ni toutes les fonctions du bâtiment d'origine. Une ressemblance visuelle doit être distinguée d'une continuité historique complète. Les notices expliqueront la date et les matériaux de la nouvelle intervention. Les visiteurs pourront ainsi apprécier le travail sans le confondre avec un élément resté en place depuis l'origine. Les responsables souhaitent éviter aussi bien la promesse d'un retour complet dans le passé que le refus de reconnaître tout intérêt à la reconstruction. Celle-ci peut modifier une place et transmettre des repères, mais son statut doit rester lisible. Le débat gagnera en précision si chacun sait ce qui a été conservé, ce qui a été étudié et ce qui a été recréé aujourd'hui. La façade reconstruite ressemble à des photographies du XIXe siècle, mais la structure, les matériaux et les fonctions intérieures datent de la restauration récente. La notice distingue les éléments d'origine des ajouts.","question":"Quelle précision doit accompagner la reconstruction pour éviter un malentendu historique ?","explanation":"A distingue restitution visuelle et continuité matérielle et fonctionnelle. B/D effacent cette distinction, C nie l'intérêt documentaire et urbain d'une reconstruction."},{"number":38,"points":33,"correct":"C","options":["Les photographies touristiques permettent de prévoir la pérennité des ateliers si les visiteurs les diffusent régulièrement.","Le prix des souvenirs complète les entrées touristiques parce qu'il traduit directement l'offre de services aux résidents.","La stabilité des logements, ateliers et commerces nécessaires aux habitants, au-delà du seul nombre de visiteurs.","Le classement patrimonial régional permet d'estimer la continuité des logements lorsque les visiteurs augmentent."],"passage":"Une ville veut attirer des visiteurs grâce à un label patrimonial. Certains ateliers et logements risquent de devenir des hébergements touristiques. Le conseil débat donc d'outils pour conserver des fonctions ordinaires. Valoriser un lieu peut fragiliser ce qui le rend habitable si l'attractivité devient son seul objectif. Les élus étudient notamment la place des commerces utiles au quotidien et les possibilités pour les salariés de se loger. Les associations rappellent qu'une rue attractive pour une visite courte peut devenir difficile à vivre si les fonctions ordinaires disparaissent. Le programme cherchera donc des indicateurs qui ne se limitent pas aux entrées dans les monuments. Il devra aussi regarder la stabilité des habitants et l'accès aux services. Le patrimoine est ici lié à une vie présente, dont l'affaiblissement pourrait finir par réduire la diversité et l'intérêt du quartier que l'on souhaite précisément mettre en valeur. Après l'obtention du label, les visiteurs augmentent mais deux ateliers ferment pour devenir des locations de courte durée. La commune suit désormais le maintien des fonctions quotidiennes parallèlement aux entrées touristiques.","question":"Quel indice compléterait utilement les chiffres de fréquentation patrimoniale ?","explanation":"C retient la stabilité de logements, ateliers et commerces utilisés au quotidien. A, B et D reposent sur des indicateurs de promotion ou de vente qui ne mesurent pas le maintien des fonctions locales."},{"number":39,"points":33,"correct":"C","options":["Remplacer sans trace les anciennes catégories dans l'index, mais conserver les originaux uniquement dans les copies téléchargeables aux chercheurs spécialisés.","Afficher les anciens intitulés sans commentaire pour préserver une recherche neutre, en réservant les notes aux documents ouverts après sélection.","Garder les termes historiques identifiables et consultables, en expliquant leurs limites directement dans les résultats de recherche affichés aux lecteurs.","Masquer les expressions contestées dans tous les résultats publics, puis les restituer seulement si un lecteur démontre leur valeur historique."],"passage":"Des archives numérisées rendent une collection plus largement consultable. Pourtant, certaines descriptions reflètent d'anciennes catégories contestées. L'équipe conserve la trace historique tout en ajoutant des explications. Faciliter l'accès à une source ne dispense pas d'aider à comprendre les conditions dans lesquelles elle a été produite. Les utilisateurs pourront voir le vocabulaire d'origine tout en disposant d'une note sur son contexte et sur les limites qu'il comporte aujourd'hui. Les archivistes ne veulent ni corriger silencieusement le passé ni laisser les descriptions anciennes fonctionner comme des catégories naturelles. Ils rendront leurs interventions identifiables pour permettre la recherche. Les documents restent des sources à examiner, pas des récits automatiquement fiables parce qu'ils sont anciens ou désormais disponibles sur un écran. La numérisation élargit les possibilités de consultation, mais elle augmente aussi l'importance des repères qui accompagnent leur lecture par un public nouveau. Une fiche ancienne emploie une catégorie aujourd'hui contestée. La base conserve le texte original dans un champ identifié et lui ajoute une note récente expliquant son contexte et ses limites. Les archivistes examinent ensuite deux modes de recherche. Dans le premier, une requête utilisant le terme ancien retrouve les fiches, mais les résultats affichent aussi une note indiquant sa provenance et les catégories auxquelles il renvoyait à l'époque. Dans le second, le terme a été remplacé dans les métadonnées sans conserver de lien visible vers la formulation d'origine; certains documents deviennent difficiles à retrouver pour les chercheurs qui étudient précisément l'histoire de ce vocabulaire. Un groupe d'usagers relève toutefois que l'affichage du mot ancien sans contexte dans les aperçus peut encore laisser croire qu'il s'agit d'une catégorie actuelle. L'équipe décide donc de signaler la médiation éditoriale jusque dans les listes de résultats, sans supprimer le champ d'origine. Elle précise que cette solution ne garantit pas que tous les lecteurs interpréteront correctement les archives.","question":"Quelle décision concilie le mieux la traçabilité scientifique et le risque de naturaliser une catégorie ancienne ?","explanation":"C concilie une source historique visible et recherchable avec un avertissement contextuel également visible dans les résultats. A efface la trace dans les métadonnées, limitant la recherche; B laisse les aperçus hors contexte; D établit un filtre d'accès non prévu qui empêche une consultation historique normale. Le texte ne prétend pas que la note élimine toute mauvaise interprétation."}]}$paper_16$::jsonb),
('tcf-reading-17','tcf-reading-2026-11-distractor-polish-v5',$paper_17${"id":"tcf-reading-17","title":"TCF Reading · Test 17","seconds":3600,"version":"tcf-reading-2026-11-distractor-polish-v5","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"B","options":["Dans chaque salle d'activité","Dans l'espace près de l'entrée","Sur l'escalier","Dans la cuisine"],"passage":"L'accueil parents-enfants ouvre à neuf heures trente. Les poussettes doivent rester dans l'espace prévu près de l'entrée.\n\nL'équipe vous indiquera ensuite la salle de jeux. Merci de libérer le passage pour les autres familles.","question":"Où déposer les poussettes ?","explanation":"Le passage indique : « L'accueil parents-enfants ouvre à neuf heures trente. Les poussettes doivent rester dans l'espace prévu près de l'entrée. » Cela justifie la réponse : Dans l'espace près de l'entrée."},{"number":2,"points":3,"correct":"C","options":["Ils doivent tous payer une seconde fois","Le groupe change de destination obligatoirement","Leur inscription est conservée","La sortie est annulée définitivement"],"passage":"La sortie intergénérationnelle est reportée à jeudi. Les inscriptions déjà confirmées restent valables.\n\nLe lieu de rendez-vous reste le même. Merci de prévenir les personnes qui vous accompagnent.","question":"Que doivent savoir les inscrits ?","explanation":"Le passage indique : « La sortie intergénérationnelle est reportée à jeudi. Les inscriptions déjà confirmées restent valables. » Cela justifie la réponse : Leur inscription est conservée."},{"number":3,"points":3,"correct":"C","options":["Seulement les enfants majeurs","Uniquement une famille au complet","Un parent non accompagné","Les professionnels exclusivement"],"passage":"La permanence familiale reçoit aussi sans enfant. Un parent peut venir seul poser ses questions.\n\nLes échanges sont gratuits et confidentiels. Aucune inscription préalable n'est demandée pour cette première rencontre.","question":"Qui peut être accueilli ?","explanation":"Le passage indique : « La permanence familiale reçoit aussi sans enfant. Un parent peut venir seul poser ses questions. » Cela justifie la réponse : Un parent non accompagné."},{"number":4,"points":3,"correct":"D","options":["Un gâteau chacun","Des boissons sucrées","Un repas complet","Aucun plat n'est obligatoire"],"passage":"Le goûter partagé ne demande aucune préparation maison. Des fruits et de l'eau sont déjà prévus.\n\nVous pouvez simplement venir avec votre famille. Merci de signaler les allergies lors de votre inscription à l'accueil.","question":"Que doivent nécessairement préparer les participants ?","explanation":"Le passage indique : « Le goûter partagé ne demande aucune préparation maison. Des fruits et de l'eau sont déjà prévus. » Cela justifie la réponse : Aucun plat n'est obligatoire."},{"number":5,"points":9,"correct":"A","options":["Une heure de fin à respecter","Un changement d'école","Une obligation de rester jusqu'au soir","Un refus de toute garde"],"passage":"Je garderai les enfants mardi, mais peux-tu les récupérer à dix-sept heures ? Mon rendez-vous suivant ne peut pas être déplacé.\n\nJe préparerai leurs affaires avant ton arrivée et laisserai les manteaux près de la porte. Préviens-moi si tu as besoin de l'adresse exacte.","question":"Quelle contrainte est exprimée ?","explanation":"Le passage indique : « Je garderai les enfants mardi, mais peux-tu les récupérer à dix-sept heures ? Mon rendez-vous suivant ne peut pas être déplacé. » Cela justifie la réponse : Une heure de fin à respecter."},{"number":6,"points":9,"correct":"C","options":["Respecter le lieu de départ","Prendre connaissance de l'horaire","Être accompagné d'un enfant","Participer à la promenade"],"passage":"Notre groupe de marche accueille aussi les grands-parents sans petits-enfants. Le thème rapproche les générations sans imposer de venir en famille.\n\nLe départ se fait devant le centre social. Le parcours est court et comprend une pause sur la place du village.","question":"Quelle condition n'est pas exigée ?","explanation":"Le passage indique : « Notre groupe de marche accueille aussi les grands-parents sans petits-enfants. Le thème rapproche les générations sans imposer de venir en famille. » Cela justifie la réponse : Être accompagné d'un enfant."},{"number":7,"points":9,"correct":"D","options":["Les horaires de la cuisine","Uniquement les prix des ingrédients","Le nom des magasins","Les gestes et conseils associés à la recette"],"passage":"J'aimerais enregistrer les recettes de grand-mère avec ses explications. La liste des ingrédients seule ne raconte pas ses astuces.\n\nJe pourrais ensuite partager ces souvenirs avec mes cousins qui habitent loin. Veux-tu lui demander si elle accepte que nous venions dimanche avec un microphone ?","question":"Quel aspect veut-on conserver ?","explanation":"Le passage indique : « J'aimerais enregistrer les recettes de grand-mère avec ses explications. La liste des ingrédients seule ne raconte pas ses astuces. » Cela justifie la réponse : Les gestes et conseils associés à la recette."},{"number":8,"points":9,"correct":"B","options":["Imposer un jeu unique à toutes les familles","Aider à choisir un jeu partagé","Remplacer les parents pendant une semaine","Vendre tous les jouets neufs"],"passage":"La ludothèque prête des jeux de plusieurs âges. L'équipe peut conseiller un jeu utilisable par des enfants de niveaux différents.\n\nLe prêt dure trois semaines. Pensez à vérifier le contenu de la boîte avant de la rapporter à l'accueil.","question":"Quel service est proposé ?","explanation":"Le passage indique : « La ludothèque prête des jeux de plusieurs âges. L'équipe peut conseiller un jeu utilisable par des enfants de niveaux différents. » Cela justifie la réponse : Aider à choisir un jeu partagé."},{"number":9,"points":9,"correct":"C","options":["Une dispense de recevoir les informations","Une suppression de la réunion","Un autre accès aux informations et aux échanges","Un changement de tous les participants"],"passage":"Je ne pourrai pas venir à la réunion en soirée. Existe-t-il un compte rendu ou un autre moment d'échange ?\n\nJe souhaite comprendre les décisions prises et donner mon avis sur la prochaine sortie. Tu peux me répondre par message.","question":"Que demande cette personne ?","explanation":"Le passage indique : « Je ne pourrai pas venir à la réunion en soirée. Existe-t-il un compte rendu ou un autre moment d'échange ? » Cela justifie la réponse : Un autre accès aux informations et aux échanges."},{"number":10,"points":9,"correct":"B","options":["Publier automatiquement chaque visage","Vérifier les autorisations de diffusion","Vendre les photos aux invités","Éviter toute prise de vue privée nécessairement"],"passage":"Merci de demander l'accord des familles avant de diffuser les photos de la fête. La présence à l'événement n'autorise pas toute publication.\n\nCertaines familles acceptent les images dans l'album privé du groupe mais pas sur un site accessible à tous. Vérifiez chaque autorisation.","question":"Quelle règle est rappelée ?","explanation":"Le passage indique : « Merci de demander l'accord des familles avant de diffuser les photos de la fête. La présence à l'événement n'autorise pas toute publication. » Cela justifie la réponse : Vérifier les autorisations de diffusion."},{"number":11,"points":15,"correct":"B","options":["Le statut professionnel des parents","La diversité des contributions possibles","Une hiérarchie fixe par génération","La force physique uniquement"],"passage":"Un centre organise des ateliers où enfants et adultes construisent ensemble. Les tâches sont réparties selon les envies et les capacités, pas seulement selon l'âge.\n\nPour fabriquer une petite étagère, une personne peut mesurer, une autre tenir les pièces et une troisième préparer la peinture. Les animateurs présentent les outils et vérifient leur maniement avant chaque étape. Les rôles peuvent changer pendant la séance afin que chacun découvre plusieurs gestes. Les réalisations seront emportées par les participants après le séchage. Le centre demande simplement de porter des vêtements qui ne craignent pas les taches et de prévenir en cas de besoin particulier.","question":"Quel principe guide la répartition ?","explanation":"Le passage indique : « Un centre organise des ateliers où enfants et adultes construisent ensemble. Les tâches sont réparties selon les envies et les capacités, pas seulement selon l'âge. » Cela justifie la réponse : La diversité des contributions possibles."},{"number":12,"points":15,"correct":"C","options":["Des meubles définitifs pour chaque maison","Un transport scolaire permanent","Des équipements temporaires","Des réparations industrielles"],"passage":"Des habitants proposent une bibliothèque de poussettes et de sièges. Le prêt limite l'achat d'objets utilisés pendant de courtes périodes.\n\nLes objets sont nettoyés et vérifiés entre deux prêts. Les familles réservent le matériel dont elles ont besoin pour une visite ou une période de croissance. Une fiche indique les conditions de retour et la disponibilité des équipements. Les réservations seront confirmées par un bénévole avant chaque retrait.","question":"Quel besoin ce service vise-t-il ?","explanation":"Le passage indique : « Des habitants proposent une bibliothèque de poussettes et de sièges. Le prêt limite l'achat d'objets utilisés pendant de courtes périodes. » Cela justifie la réponse : Des équipements temporaires."},{"number":13,"points":15,"correct":"D","options":["Appliquer un questionnaire sans discussion","Présenter des informations personnelles obligatoires","Évaluer les autres familles publiquement","Définir les sujets utiles à partir de leurs besoins"],"passage":"Une association accueille les nouveaux parents sans programme imposé. Les échanges partent des questions du groupe, tout en respectant la confidentialité.\n\nLes rencontres se déroulent dans une salle où chacun peut parler ou simplement écouter. L'animatrice commence par rappeler que les situations sont différentes et qu'aucun témoignage ne sera transmis à l'extérieur. Certains participants évoquent les nuits difficiles, d'autres les démarches à réaliser après une naissance. Une information professionnelle peut être proposée lorsque le groupe le souhaite. Les coordonnées des services compétents restent disponibles à la fin de la séance, sans obligation de poursuivre un accompagnement.","question":"Quelle place est donnée aux participants ?","explanation":"Le passage indique : « Une association accueille les nouveaux parents sans programme imposé. Les échanges partent des questions du groupe, tout en respectant la confidentialité. » Cela justifie la réponse : Définir les sujets utiles à partir de leurs besoins."},{"number":14,"points":15,"correct":"B","options":["Accueillir des jeunes visiteurs","Réduire les personnes âgées à leurs souvenirs","Permettre des intérêts communs","Choisir des sujets actuels"],"passage":"Une maison de retraite invite des lycéens à un atelier radio. Chacun choisit son sujet ; les résidents ne sont pas limités au récit du passé.\n\nLes participants préparent les questions, enregistrent les voix et choisissent les sons qui accompagneront l'émission. Une résidente souhaite parler de musique actuelle tandis qu'un élève s'intéresse aux transformations de son quartier. Le journaliste qui les accompagne explique comment vérifier une information et demander l'autorisation de diffuser une voix. L'émission finale sera écoutée ensemble avant publication. Cette étape permettra à chacun de commenter le montage et de préciser un propos qui aurait été mal compris.","question":"Quelle idée est évitée ?","explanation":"Le passage indique : « Une maison de retraite invite des lycéens à un atelier radio. Chacun choisit son sujet ; les résidents ne sont pas limités au récit du passé. » Cela justifie la réponse : Réduire les personnes âgées à leurs souvenirs."},{"number":15,"points":15,"correct":"A","options":["La participation avec un accompagnateur non apparenté","La garde anonyme des enfants","La suppression des inscriptions","L'absence de tout adulte responsable"],"passage":"Un club ouvre des activités familiales sans exiger un lien de parenté entre accompagnateurs et enfants. Les adultes responsables sont identifiés à l'inscription.\n\nUne tante, un voisin ou un ami peut ainsi accompagner un enfant avec l'autorisation nécessaire. Les organisateurs souhaitent accueillir les différents réseaux de soutien qui existent autour des jeunes. Ils demandent les coordonnées des responsables pour pouvoir les joindre pendant la séance. Les activités sont présentées à l'avance afin de choisir celles qui conviennent aux capacités du groupe. Le mot familial décrit ici une façon de participer ensemble, sans imposer un modèle unique de composition du foyer.","question":"Quelle souplesse est prévue ?","explanation":"Le passage indique : « Un club ouvre des activités familiales sans exiger un lien de parenté entre accompagnateurs et enfants. Les adultes responsables sont identifiés à l'inscription. » Cela justifie la réponse : La participation avec un accompagnateur non apparenté."},{"number":16,"points":15,"correct":"C","options":["Supprimer les documents individuels","Confier toutes les décisions au groupe","Partager sans effacer toute confidentialité","Rendre tous les dossiers publics"],"passage":"Un atelier aide les familles à organiser des documents communs. Il distingue les pièces utiles à partager et les informations personnelles à conserver séparément.\n\nLes participants classent notamment les contrats, les contacts utiles et les consignes concernant les personnes à prévenir. L'animatrice rappelle qu'une organisation pratique ne donne pas automatiquement le droit de consulter tous les dossiers d'un proche. Chaque personne décide des accès qu'elle souhaite autoriser. Une liste indique où se trouvent les documents sans nécessairement en reproduire le contenu.","question":"Quel apprentissage est proposé ?","explanation":"Le passage indique : « Un atelier aide les familles à organiser des documents communs. Il distingue les pièces utiles à partager et les informations personnelles à conserver séparément. » Cela justifie la réponse : Partager sans effacer toute confidentialité."},{"number":17,"points":15,"correct":"B","options":["La présence des nouveaux habitants","L'incompatibilité de certains horaires","Le nombre de salles seulement","Le manque de sujets à discuter"],"passage":"Une commune propose des réunions en journée et en soirée. Elle souhaite toucher des familles ayant des horaires de travail différents.\n\nLes premières rencontres avaient lieu à une heure qui convenait surtout aux personnes déjà présentes dans les associations. Les agents ont demandé aux absents quels moments seraient possibles pour eux. Une synthèse commune circulera après chaque séance pour que les échanges ne se divisent pas en deux groupes sans lien. Les familles pourront aussi envoyer une remarque écrite. Le conseil municipal comparera les propositions avant d'arrêter le calendrier du trimestre suivant.","question":"Quel obstacle cherche-t-elle à réduire ?","explanation":"Le passage indique : « Une commune propose des réunions en journée et en soirée. Elle souhaite toucher des familles ayant des horaires de travail différents. » Cela justifie la réponse : L'incompatibilité de certains horaires."},{"number":18,"points":15,"correct":"A","options":["Le refus ponctuel reste possible","Le calendrier est fixé pour dix ans","Une absence entraîne une exclusion automatique","Toute demande doit être acceptée"],"passage":"Des voisins échangent des heures de garde selon un calendrier. Chacun peut refuser un créneau sans perdre définitivement l'accès au réseau.\n\nLe règlement prévoit une confirmation écrite pour chaque garde et un échange préalable entre les adultes concernés. Les disponibilités sont mises à jour chaque semaine afin d'éviter les malentendus. Un membre peut être très présent pendant les vacances puis beaucoup moins disponible au moment d'un changement professionnel. Le réseau cherche à reconnaître ces variations plutôt qu'à imposer une contribution identique chaque mois.","question":"Quelle règle protège la souplesse du dispositif ?","explanation":"Le passage indique : « Des voisins échangent des heures de garde selon un calendrier. Chacun peut refuser un créneau sans perdre définitivement l'accès au réseau. » Cela justifie la réponse : Le refus ponctuel reste possible."},{"number":19,"points":15,"correct":"A","options":["Partager un moment autour de la lecture","Préparer un concours obligatoire","Mesurer la vitesse de lecture uniquement","Classer les familles"],"passage":"Un programme de lecture associe un adulte et un enfant autour d'un livre choisi ensemble. L'objectif est le plaisir de l'échange, pas une note scolaire.\n\nLes bénévoles proposent plusieurs albums, mais le duo peut aussi apporter un ouvrage déjà aimé. On peut s'arrêter sur une image, revenir à une page ou raconter un souvenir évoqué par l'histoire. Les organisateurs espèrent que cette liberté aidera les participants à prendre confiance et à retrouver, plus tard, le chemin de la bibliothèque.","question":"Quelle finalité est privilégiée ?","explanation":"Le passage indique : « Un programme de lecture associe un adulte et un enfant autour d'un livre choisi ensemble. L'objectif est le plaisir de l'échange, pas une note scolaire. » Cela justifie la réponse : Partager un moment autour de la lecture."},{"number":20,"points":21,"correct":"D","options":["Obligation de participer chaque soir","Séparation complète de toutes les générations","Suppression de tous les espaces privés","Rencontres possibles et respect de l'intimité"],"passage":"Une résidence intergénérationnelle prévoit des espaces communs, mais aussi des logements privés. Les relations ne doivent pas devenir une présence collective permanente imposée. Les habitants définissent ensemble les horaires des repas partagés et les modalités de réservation de la salle. Chacun conserve la possibilité de dîner chez soi ou de recevoir ses proches sans participer à l'activité annoncée. Une personne référente intervient en cas de désaccord sur le bruit ou l'entretien. Le projet repose ainsi sur des occasions régulières de se croiser et sur des limites claires qui permettent de choisir son degré de participation.","question":"Quel équilibre est recherché ?","explanation":"Le passage indique : « Une résidence intergénérationnelle prévoit des espaces communs, mais aussi des logements privés. Les relations ne doivent pas devenir une présence collective permanente imposée. » Cela justifie la réponse : Rencontres possibles et respect de l'intimité."},{"number":21,"points":21,"correct":"A","options":["Une difficulté d'accès au lieu","Une absence certaine d'intérêt","Un prix obligatoirement trop élevé","Un manque de jeux dans chaque foyer"],"passage":"Un centre reçoit de moins en moins de familles malgré des activités appréciées. Les entretiens montrent que le trajet en bus a été compliqué par une nouvelle correspondance. Le questionnaire de satisfaction avait été distribué uniquement aux personnes encore présentes. Il ne permettait donc pas de comprendre pourquoi les autres avaient cessé de venir. L'équipe a rappelé plusieurs anciens participants avec leur accord. Ceux-ci ont expliqué que le nouvel itinéraire rendait le retour difficile à l'heure du repas.","question":"Quelle cause possible est identifiée ?","explanation":"Le passage indique : « Un centre reçoit de moins en moins de familles malgré des activités appréciées. Les entretiens montrent que le trajet en bus a été compliqué par une nouvelle correspondance. » Cela justifie la réponse : Une difficulté d'accès au lieu."},{"number":22,"points":21,"correct":"C","options":["Un centre commercial obligatoire","Une salle sans possibilité de discussion","Un espace de sociabilité accessible","Une compétition permanente"],"passage":"Des adolescents participent à la conception d'un espace de quartier. Ils demandent un lieu où se rencontrer sans devoir consommer, pas seulement des équipements sportifs. Lors des premières réunions, les adultes avaient surtout discuté du choix des terrains et du matériel. Les jeunes ont décrit leurs habitudes après les cours et leurs difficultés à rester ensemble lorsqu'il pleut. Son fonctionnement sera discuté avec les riverains, afin que les règles répondent aux usages réels et aux contraintes du voisinage.","question":"Quel besoin expriment-ils ?","explanation":"Le passage indique : « Des adolescents participent à la conception d'un espace de quartier. Ils demandent un lieu où se rencontrer sans devoir consommer, pas seulement des équipements sportifs. » Cela justifie la réponse : Un espace de sociabilité accessible."},{"number":23,"points":21,"correct":"A","options":["Le travail d'organisation","La surface des logements uniquement","Le nombre de meubles","Les achats de loisirs"],"passage":"Une enquête sur les aidants mesure les tâches visibles, puis ajoute le temps consacré à organiser et anticiper. Cette charge moins matérielle était peu décrite dans les premiers résultats. Prendre les rendez-vous, vérifier les renouvellements de documents ou prévoir un remplacement mobilise l'attention même lorsqu'aucun soin n'est réalisé. Plusieurs personnes expliquent qu'elles doivent rester joignables pendant leur travail. La nouvelle enquête demande donc aussi qui coordonne les interventions et avec quelle fréquence.","question":"Quel aspect est mieux pris en compte ?","explanation":"Le passage indique : « Une enquête sur les aidants mesure les tâches visibles, puis ajoute le temps consacré à organiser et anticiper. Cette charge moins matérielle était peu décrite dans les premiers résultats. » Cela justifie la réponse : Le travail d'organisation."},{"number":24,"points":21,"correct":"A","options":["Adapter les échanges aux situations particulières","Éviter tous les témoignages","Imposer une méthode unique","Considérer les contraintes comme identiques"],"passage":"Un atelier réunit des personnes qui accompagnent un proche. Les animateurs rappellent que les solutions d'une famille ne conviennent pas automatiquement à toutes les autres. Les horaires professionnels, la distance entre les logements ou l'état de santé du proche modifient ce qui est réalisable. Une proposition peut être discutée comme une piste à adapter, sans devenir une consigne. Les échanges permettent aussi d'identifier les questions qui nécessitent un avis spécialisé.","question":"Quelle prudence est recommandée ?","explanation":"Le passage indique : « Un atelier réunit des personnes qui accompagnent un proche. Les animateurs rappellent que les solutions d'une famille ne conviennent pas automatiquement à toutes les autres. » Cela justifie la réponse : Adapter les échanges aux situations particulières."},{"number":25,"points":21,"correct":"D","options":["La nouvelle fréquentation des bancs garantit une hausse comparable des visites dans les autres espaces publics du quartier.","Les nouveaux bancs règlent les difficultés d'accueil des familles, même pour celles qui ont d'autres besoins d'accessibilité.","La présence de sièges peut accélérer le départ des accompagnateurs lorsqu'ils viennent seulement surveiller les jeux.","Le prolongement des visites et les échanges entre accompagnateurs, que le seul comptage des enfants ne révèle pas."],"passage":"Un quartier installe des bancs près de l'aire de jeux. Les adultes peuvent rester confortablement, ce qui facilite aussi la venue des grands-parents et les échanges entre accompagnateurs. Auparavant, plusieurs accompagnateurs partaient rapidement faute de pouvoir s'asseoir. Les nouveaux équipements sont placés à distance raisonnable des jeux, avec une vue dégagée. Elle observera les usages au cours des prochaines semaines avant de décider si d'autres installations sont nécessaires pour rendre le lieu plus accueillant. Les bancs sont surtout utilisés par des adultes accompagnant des enfants, mais certains voisins y restent même après les jeux pour discuter. La commune mesure donc aussi la durée des visites et les rencontres.","question":"Quel effet du mobilier serait sous-estimé par un comptage limité aux enfants jouant ?","explanation":"D inclut la prolongation des visites et les échanges des adultes, absents d'un comptage des seuls enfants. A généralise à d'autres parcs, B suppose que les sièges résolvent tous les besoins et C déduit à tort un départ plus rapide."},{"number":26,"points":21,"correct":"D","options":["Les illustrations peuvent compléter le vocabulaire traduit seulement lorsque la démarche ne comporte aucune pièce justificative.","La compréhension des termes administratifs suffit pour une inscription si les parents peuvent poser des questions dans leur langue.","Un dossier fictif peut faciliter la démarche, mais dispense l'usager de vérifier les documents nécessaires dans son propre cas.","La traduction des termes administratifs n'explique pas toujours les étapes concrètes d'une démarche ni les pièces attendues."],"passage":"Une association propose des conseils aux parents en plusieurs langues. Elle utilise aussi des exemples concrets plutôt que traduire uniquement des termes administratifs difficiles. Une demande d'inscription est ainsi présentée à partir d'un dossier fictif, étape par étape. Les personnes peuvent poser leurs questions oralement et repartir avec un résumé illustré. Les intervenants vérifient que les informations essentielles ont été comprises sans demander aux participants de raconter leur situation devant tout le groupe. Lors d'un essai, les parents comprennent la traduction littérale d'un mot administratif sans savoir quelle pièce joindre. Un dossier fictif et un exemple illustré clarifient l'étape attendue.","question":"Pourquoi la traduction seule ne suffit-elle pas toujours à rendre le service accessible ?","explanation":"D sépare la compréhension littérale des mots et celle des étapes à réaliser. A limite abusivement les exemples illustrés, B confond vocabulaire et procédure, C suppose qu'un exemple dispense de vérifier son dossier réel."},{"number":27,"points":21,"correct":"C","options":["L'impossibilité d'organiser des échanges avec des proches à horaires fixés à l'avance.","L'absence de toute envie de communiquer chez les personnes qui demandent une première aide.","Une aide aux réglages et aux étapes initiales pour devenir progressivement autonomes.","La nécessité d'acquérir davantage d'appareils avant toute communication vidéo."],"passage":"Des résidents souhaitent un téléphone collectif pour les appels vidéo. L'équipe organise des créneaux accompagnés, car la présence du matériel ne suffit pas à garantir son utilisation. Une première séance permet de régler le volume, de comprendre l'image et d'apprendre à terminer un appel. Les proches reçoivent aussi les horaires auxquels ils peuvent contacter la résidence. Le personnel vérifie que chacun souhaite participer avant d'organiser une conversation. Après la mise à disposition du téléphone, plusieurs résidents attendent le personnel pour régler le son ou lancer l'appel. Les séances accompagnées leur permettent progressivement de choisir eux-mêmes les créneaux.","question":"De quoi les résidents ont-ils encore besoin pour utiliser eux-mêmes le téléphone collectif ?","explanation":"C désigne l'accompagnement concret pour régler le son, lancer l'appel et ensuite choisir un créneau. A invente une impossibilité de programmer des échanges; B transforme un besoin d'aide en absence d'envie; D prescrit d'autres appareils alors que celui disponible peut être utilisé après accompagnement."},{"number":28,"points":21,"correct":"A","options":["Une vue à hauteur d'enfant révèle des problèmes visuels que les adultes perçoivent autrement.","Les photos des élèves donnent une vue suffisamment précise des risques pour retenir les travaux avant les essais complémentaires.","L'observation à hauteur d'enfant permet d'estimer la fréquence des accidents, là où les relevés mesurent surtout les véhicules.","Leurs observations confirment les dangers connus des adultes, sans apporter d'autre perspective."],"passage":"Une commune associe les enfants à l'évaluation des trajets scolaires. Leur taille et leur expérience font apparaître des obstacles peu visibles pour les adultes. Ils photographient les endroits où leur vue est cachée par un véhicule ou un panneau. Les agents comparent ensuite ces observations avec les mesures de circulation. Cette démarche complète l'expertise technique sans demander aux élèves de décider seuls des travaux. Les premières propositions seront présentées aux familles et testées sur un trajet avant un éventuel élargissement. À hauteur d'adulte, une voiture garée ne masque pas le passage; à hauteur d'enfant, elle cache l'arrivée des véhicules. Les observations des élèves sont confrontées aux relevés de circulation.","question":"Quel intérêt possède l'observation faite à hauteur d'enfant ?","explanation":"A repère un défaut de visibilité propre à la hauteur d'un enfant, complété ensuite par des relevés. B remplace indûment la consultation et les essais, C prétend quantifier les accidents, D nie la différence de perspective observée."},{"number":29,"points":21,"correct":"B","options":["Séparer les séances par tranche d'âge pour éviter que les expériences ne se contredisent.","Attribuer les rôles selon les savoirs à partager, non selon l'âge, dans chaque atelier.","Confier systématiquement le numérique aux jeunes et les objets matériels aux générations âgées.","Garder les aînés comme enseignants afin de transmettre des pratiques anciennes aux plus jeunes."],"passage":"Un groupe organise un échange de savoirs entre générations. Les jeunes ne sont pas toujours les élèves : ils présentent aussi des pratiques que les plus âgés souhaitent découvrir. Une personne âgée peut vouloir découvrir un logiciel et un adolescent apprendre à entretenir une plante. Les organisateurs constituent les petits groupes selon ces envies, plutôt qu'en distribuant les rôles à partir des dates de naissance. Dans le même atelier, une adolescente explique un réglage numérique et un retraité montre une technique de jardinage. Lors de la séance suivante, leurs rôles changent encore selon les sujets.","question":"Quel principe d'organisation rend cette transmission réellement réciproque ?","explanation":"Les rôles dépendent des savoirs et envies, non des générations. B. D/C/A réintroduisent des stéréotypes."},{"number":30,"points":26,"correct":"C","options":["La famille devrait fournir le même accompagnement dès lors qu'un proche est identifié, le service public n'intervenant qu'en second recours.","La distance des proches reflète leur degré de volonté d'aider et permet de classer directement les besoins de soutien.","La distance, le temps et les ressources des proches modifient l'aide réellement possible malgré des liens familiaux comparables, au quotidien.","La présence d'un enfant proche suffit à diminuer les besoins du parent, même si ses ressources et son temps restent inconnus."],"passage":"La solidarité familiale est parfois supposée disponible sans limite. Elle dépend pourtant du temps, de la proximité et des ressources de chacun. Un service public qui compte uniquement sur elle risque de traiter différemment des personnes ayant les mêmes besoins mais des entourages très différents. Deux voisins âgés, par exemple, peuvent avoir des enfants qui habitent à des distances très différentes. Demander le même soutien à leurs familles ne crée pas les mêmes possibilités concrètes. Deux personnes âgées ont les mêmes besoins d'aide. L'une peut compter sur des proches vivant à quelques rues, l'autre sur un fils vivant loin avec des contraintes professionnelles. Un service identique fondé sur la famille leur offrirait des soutiens très différents.","question":"Pourquoi l'administration ne peut-elle pas déduire une capacité de soutien identique des liens familiaux ?","explanation":"C explique pourquoi un lien de parenté ne donne pas les mêmes possibilités d'aide selon distance, temps et ressources. A présume un soutien égal, B infère la volonté de la distance, D confond existence d'un proche et réduction du besoin."},{"number":31,"points":26,"correct":"D","options":["Le nombre d'enfants par classe, sans rapport avec l'inscription proposée.","La présence des animateurs, dont la profession déterminait l'accessibilité du programme.","Le prix des activités, qui n'était pas décrit comme obstacle dans cette situation.","Les conditions pratiques supposées par l'organisation, malgré un intitulé inclusif."],"passage":"Une activité dite familiale peut sembler ouverte à tous. Si elle suppose deux adultes disponibles le samedi et une voiture, certaines familles restent à l'écart. Les conditions concrètes de participation comptent autant que le nom accueillant donné au programme. Les organisateurs proposent désormais une inscription individuelle et indiquent les transports possibles. Ils vérifient aussi si le matériel peut être prêté. Une activité annoncée « pour toutes les familles » demande une voiture et deux adultes disponibles le samedi. Après avoir proposé un accès par transport et une participation individuelle, les organisateurs accueillent de nouveaux foyers.","question":"Quel aspect de l'annonce pouvait masquer une exclusion ?","explanation":"Des présupposés de transport et de disponibilité excluent malgré le titre. D. Les autres paramètres ne sont pas appuyés."},{"number":32,"points":26,"correct":"D","options":["Le désaccord entre les deux récits prouve qu'une des personnes ne se trouvait pas à l'événement, malgré leur lien familial.","Les récits devraient coïncider si les deux membres ont vécu le même déménagement, indépendamment de leur âge.","La participation de l'aîné à l'organisation rend son récit plus exact sur tous les aspects du déménagement.","Des expériences et responsabilités différentes peuvent produire des souvenirs divergents d'un même événement sans supposer de mensonge."],"passage":"La mémoire familiale se construit avec des récits qui évoluent selon ceux qui les racontent. Des versions différentes ne signifient pas nécessairement qu'une personne cherche à tromper. Elles peuvent refléter des positions, des âges et des expériences distincts dans un même événement. Lors d'un atelier, deux sœurs décrivent ainsi une même fête avec des détails différents. L'animatrice conserve les deux témoignages et précise les circonstances dans lesquelles ils ont été recueillis. Deux frères se souviennent différemment d'un déménagement: l'un avait six ans, l'autre dix-sept et organisait le trajet. L'atelier relève leur âge et leur rôle avant de rapprocher les deux récits.","question":"Quelle conclusion sur ces témoignages serait la plus prudente ?","explanation":"D admet des mémoires distinctes selon l'âge et le rôle, sans présumer une tromperie. A infère une absence, B impose un souvenir identique et C transforme une responsabilité en garantie de justesse."},{"number":33,"points":26,"correct":"B","options":["La prise de décision définitive à l'ouverture du dossier, sans nouvelles consultations.","Revoir l'aide quand les besoins de la personne changent au cours du suivi.","L'attribution d'un soutien croissant automatiquement à chaque personne, indépendamment de son évolution.","La fixation d'un volume d'aide identique pour éviter toute différence entre les personnes."],"passage":"Un service souhaite soutenir les aidants sans décider à leur place. Il propose des temps de relais et demande régulièrement si les besoins ont changé. L'accompagnement ne consiste pas à fixer une fois pour toutes une solution supposée convenir à toute la durée de la situation. Une aide adaptée à une courte convalescence peut devenir insuffisante lorsque la dépendance s'installe. Un aidant bénéficie d'abord d'un relais deux heures par semaine; après une aggravation, cet horaire devient insuffisant. L'équipe revoit le soutien après échange plutôt que reconduire automatiquement l'ancien accord.","question":"Quelle qualité du suivi répond à l'évolution de la situation ?","explanation":"Le suivi est réévaluable et dialogué. B; D/A/C supposent une uniformité ou automatisme absent."},{"number":34,"points":26,"correct":"C","options":["Que les expériences diffèrent selon les parcours personnels.","Que les ateliers de jardinage exigent une qualification professionnelle.","Que les intérêts d'une personne découlent forcément de son âge.","Que le programme puisse évoluer à partir des discussions des participants."],"passage":"Un projet rapproche des générations par des activités communes. Les organisateurs évitent de supposer d'avance que les jeunes veulent uniquement du numérique et les anciens uniquement raconter le passé. Les centres d'intérêt réels émergent des rencontres. Les premières séances laissent une place à la discussion et aux propositions spontanées. Un atelier peut ainsi réunir des amateurs de jardinage de plusieurs âges. Les premières propositions viennent de participants de plusieurs âges souhaitant tous jardiner. Les organisateurs renoncent donc au programme prévu qui séparait jeux numériques et récits anciens.","question":"Quelle hypothèse initiale le groupe doit-il abandonner ?","explanation":"Des intérêts réels traversent les âges, C. Les autres hypothèses ne sont pas celles critiquées."},{"number":35,"points":26,"correct":"B","options":["Les écarts entre quartiers, même lorsque les ménages interrogés présentent des réponses familiales cohérentes.","Des besoins contradictoires entre personnes d'un même ménage malgré une adresse commune, dans leur vie quotidienne.","Le nombre de questionnaires reçus par quartier, qui doit rester indépendant de la taille des ménages.","La localisation de chaque répondant, qui serait différente pour les personnes vivant à la même adresse."],"passage":"Une consultation compte une réponse par foyer. Des participants soulignent que cette unité peut masquer les besoins différents des personnes qui y vivent. Un avis commun est utile pour certaines questions, mais ne remplace pas toujours l'écoute individuelle. Un adolescent peut demander un espace calme tandis qu'un adulte souhaite surtout un accès plus facile au stationnement. Le questionnaire distingue les avis individuels et les réponses communes. Dans une consultation sur les transports, la mère et son adolescent vivent dans le même foyer mais utilisent des trajets différents. Une réponse unique risque de faire disparaître l'un de ces besoins.","question":"Quelle information une réponse par foyer peut-elle masquer ?","explanation":"B indique que des personnes partageant une adresse peuvent avoir des besoins opposés. A déplace le problème entre quartiers, C concerne le volume de réponses, D invente des localisations différentes au sein d'un foyer."},{"number":36,"points":33,"correct":"D","options":["Le nombre de résidents qui déclarent pouvoir refuser une rencontre sans avoir à se justifier devant le groupe.","Les descriptions de liens nouveaux recueillies lors d'entretiens avec les habitants plutôt que déduites des seules présences.","La comparaison du ressenti de rencontres librement choisies et de celles vécues comme des obligations dans la résidence.","Compter les présences dans une salle commune sans mesurer la qualité des liens ni la liberté de participer."],"passage":"Une résidence promet de lutter contre la solitude en rapprochant des générations. Elle découvre que la proximité physique facilite certaines rencontres sans garantir la confiance. Des activités choisies et un respect du refus sont nécessaires. Créer les conditions d'une relation ne revient pas à pouvoir l'imposer. Lors des premières semaines, plusieurs habitants se sont sentis obligés d'assister à chaque repas annoncé, de peur de paraître peu sociables. L'équipe a donc précisé que les invitations pouvaient être refusées sans justification. Elle propose aussi des rencontres en petits groupes autour d'intérêts choisis, plutôt qu'un programme collectif quotidien. Les nouveaux arrivants disposent d'un interlocuteur pour poser leurs questions, mais restent libres d'organiser leurs journées. L'évaluation portera sur la qualité des liens décrits par les résidents et sur leur sentiment de pouvoir choisir, pas uniquement sur le nombre de personnes réunies dans la salle commune. Les résidents d'un immeuble partagent une salle commune, mais seuls ceux qui choisissent des activités à leur goût développent des liens. Ceux qui déclinent les rencontres restent pleinement membres du lieu.","question":"Quel résultat serait trompeur pour mesurer la lutte contre la solitude ?","explanation":"D est trompeur car une salle remplie ne révèle ni la confiance ni la liberté de participer. A mesure le choix, B documente la qualité des liens et C distingue les rencontres désirées de celles ressenties comme imposées; ces trois résultats contribuent au bilan plutôt que le fausser."},{"number":37,"points":33,"correct":"D","options":["Inciter des personnes âgées à découvrir une activité sans expliquer les capacités différentes nécessaires à sa pratique.","Présenter des parcours variés au risque de diminuer la cohérence du message publicitaire sur l'âge.","Valoriser des liens discrets au détriment des grands-parents ayant des pratiques plus visibles et sportives.","Faire d'un portrait valorisant une attente uniforme qui invisibilise des situations moins spectaculaires, dans les campagnes."],"passage":"Une campagne valorise les grands-parents très actifs, toujours disponibles et connectés. Des associations apprécient cette image positive, mais craignent qu'elle devienne une norme excluant les personnes fatiguées ou moins équipées. Combattre un stéréotype ne devrait pas consister à le remplacer par une exigence de performance identique pour tous. Les témoignages retenus montrent surtout des voyages, des activités sportives et des services rendus aux enfants. Ils rendent moins visibles les relations fondées sur une présence discrète, un appel régulier ou un souvenir partagé. Les associations proposent d'élargir la campagne à ces expériences, sans présenter les limitations physiques comme un échec personnel. Une image valorisante peut ouvrir des possibilités, à condition de laisser une place à la diversité des situations et au droit de ne pas correspondre au portrait le plus spectaculaire. Une affiche montre uniquement des grands-parents sportifs et parfaitement connectés. Des personnes fatiguées y voient une nouvelle manière d'être jugées insuffisantes malgré leur engagement familial.","question":"Quel effet indésirable d'une représentation positive les associations redoutent-elles ?","explanation":"D signale le risque de transformer une image positive en norme de performance uniforme. A limite l'enjeu à une activité, B réduit la diversité à un problème de campagne, C suppose un remplacement du stéréotype par son inverse."},{"number":38,"points":33,"correct":"A","options":["Confondre l'absence aux réunions de journée avec un désintérêt de parents disponibles seulement à d'autres horaires professionnels.","La contribution écrite est moins représentative que la présence physique et devrait compter moins dans les décisions de l'école.","Les réponses à distance représentent plus fidèlement les familles absentes que celles recueillies dans les réunions habituelles.","Le risque de réserver l'écoute aux réunions reste faible lorsque les parents savent que d'autres canaux existent."],"passage":"Des parents sont invités à participer aux activités de l'école. Les personnes disponibles en journée deviennent les interlocuteurs les plus visibles. L'équipe organise d'autres moyens de contribution pour entendre aussi celles qui ne peuvent pas venir. La disponibilité ne doit pas être confondue avec l'intérêt porté à la scolarité. Un questionnaire accessible par téléphone et des entretiens à des horaires variés complètent désormais les réunions habituelles. Des familles peuvent aussi apporter une contribution à distance, par exemple en proposant une lecture ou en commentant une information envoyée par l'équipe. Les enseignants veillent à ne pas réserver les décisions importantes aux échanges informels de fin de matinée. Ils résument les propositions et expliquent les suites qui leur sont données. Cette organisation permet de distinguer les obstacles pratiques d'une absence de volonté, tout en maintenant des occasions de rencontre pour les personnes qui peuvent se déplacer. Une mère souhaite s'impliquer mais travaille durant les réunions. Grâce à un entretien du soir, elle propose un changement finalement retenu. Le projet n'aurait pas recueilli cet avis avec ses seuls horaires habituels.","question":"Quelle erreur d'évaluation les nouveaux canaux de participation cherchent-ils à prévenir ?","explanation":"A évite de lire l'absence en journée comme un manque d'intérêt. B dévalorise sans preuve l'écrit, C présume une supériorité de représentativité et D suppose que des canaux disponibles suffisent même si les avis ne sont pas retenus."},{"number":39,"points":33,"correct":"B","options":["Les échanges restent sans résultat concret tant que les institutions ne créent pas de nouvelles places de remplacement pour tous les aidants participants.","Les échanges peuvent améliorer l'orientation et les arrangements ponctuels, mais leur activité ne démontre pas que le manque de service institutionnel est comblé.","Un nombre élevé de conseils partagés peut remplacer un indicateur de places professionnelles réellement disponibles.","Les arrangements entre proches devraient réduire les demandes adressées aux organismes même si la pénurie demeure."],"passage":"Un atelier réunit des aidants pour partager des pratiques. Les animateurs veillent à ce que l'échange ne transforme pas chacun en responsable de résoudre seul toutes les difficultés. L'entraide peut renforcer les personnes tout en faisant apparaître des besoins qui demandent une réponse collective ou professionnelle. Plusieurs participants décrivent des difficultés à obtenir un remplacement ou à comprendre les dispositifs existants. Le groupe peut partager des coordonnées et préparer des questions, mais il ne dispose ni des moyens ni de l'autorité nécessaires pour créer les services manquants. L'animateur propose donc de transmettre une synthèse anonyme aux organismes concernés, avec l'accord des personnes. Les rencontres restent aussi un espace où exprimer la fatigue sans devoir immédiatement trouver une solution. Reconnaître les limites de l'entraide protège les participants contre une nouvelle obligation de performance et permet de formuler plus clairement les demandes de soutien extérieur. Les aidants échangent une méthode utile pour demander un remplacement, mais constatent que le service correspondant manque dans leur zone. Le collectif transmet ce besoin aux organismes compétents sans le présenter comme un échec individuel. Un bilan compare les demandes formulées à la suite des réunions. Plusieurs aidants ont obtenu des renseignements plus précis et certains ont réussi à organiser un échange ponctuel de tâches avec des proches. Mais les demandes d'un service public de remplacement restent sans réponse faute de personnel dans la région. Les animateurs observent que les personnes les plus actives dans le groupe continuent elles aussi à manquer de temps de repos. Ils envisagent de recueillir les difficultés récurrentes dans un document anonyme adressé à l'organisme compétent, tout en maintenant un espace où les participants peuvent échanger des conseils sans devenir gestionnaires du service absent. Une participante suggère de compter le nombre de conseils échangés comme preuve que le problème institutionnel est résolu; le groupe refuse cette équivalence, sans nier l'utilité des informations partagées.","question":"Quelle conclusion distingue l'efficacité de l'entraide de ce qu'elle ne peut pas fournir à elle seule ?","explanation":"B distingue une meilleure orientation et des arrangements ponctuels d'un service institutionnel toujours manquant. A efface les bénéfices constatés, C confond conseils et prestations disponibles et D fait peser sur les proches une carence qui subsiste."}]}$paper_17$::jsonb),
('tcf-reading-18','tcf-reading-2026-11-distractor-polish-v5',$paper_18${"id":"tcf-reading-18","title":"TCF Reading · Test 18","seconds":3600,"version":"tcf-reading-2026-11-distractor-polish-v5","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"B","options":["Six heures","Six heures quarante-cinq","Huit heures","Sept heures quinze"],"passage":"Le départ vers l'île est avancé à sept heures à cause de la marée. Présentez-vous quinze minutes avant.\n\nLes billets déjà achetés restent valables. Le contrôle des réservations se fera directement sur le quai habituel.","question":"À quelle heure faut-il être présent ?","explanation":"Le passage indique : « Le départ vers l'île est avancé à sept heures à cause de la marée. Présentez-vous quinze minutes avant. » Cela justifie la réponse : Six heures quarante-cinq."},{"number":2,"points":3,"correct":"B","options":["Une bouteille de gaz","Un sac de couchage","Un oreiller neuf","Une tente obligatoire"],"passage":"Le refuge ne fournit pas de couverture cette semaine. Apportez un sac de couchage même si votre place est réservée.\n\nLe repas du soir est maintenu.","question":"Quel équipement reste nécessaire ?","explanation":"Le passage indique : « Le refuge ne fournit pas de couverture cette semaine. Apportez un sac de couchage même si votre place est réservée. » Cela justifie la réponse : Un sac de couchage."},{"number":3,"points":3,"correct":"B","options":["La surveillance est assurée par tous les visiteurs","La surveillance commence à onze heures","La baignade est surveillée toute la nuit","La plage ferme à onze heures"],"passage":"La plage surveillée ouvre à onze heures. Avant cet horaire, aucune surveillance de baignade n'est assurée.\n\nLes horaires seront affichés à l'entrée. Renseignez-vous au poste de secours avant de vous installer près de l'eau.","question":"Que précise l'annonce ?","explanation":"Le passage indique : « La plage surveillée ouvre à onze heures. Avant cet horaire, aucune surveillance de baignade n'est assurée. » Cela justifie la réponse : La surveillance commence à onze heures."},{"number":4,"points":3,"correct":"D","options":["La route fermée","Le bord des falaises","Le sommet sans balisage","Le parcours intérieur"],"passage":"Le chemin des falaises est interdit par vent fort. Le parcours intérieur reste accessible.\n\nSuivez les panneaux au départ du parking. La réouverture sera annoncée lorsque les conditions permettront de circuler sans danger.","question":"Quel itinéraire est proposé ?","explanation":"Le passage indique : « Le chemin des falaises est interdit par vent fort. Le parcours intérieur reste accessible. » Cela justifie la réponse : Le parcours intérieur."},{"number":5,"points":9,"correct":"B","options":["Parcourir le plus grand nombre de refuges","Explorer sans porter tout le matériel","Descendre immédiatement en ville","Éviter toute promenade"],"passage":"Je préfère rester deux nuits au même refuge. Nous pourrons observer le lac sans transporter les sacs toute la journée.\n\nNous pourrions laisser une partie de nos affaires dans la chambre et partir avec un petit sac. Réserve deux places si tu es d'accord.","question":"Quel avantage est recherché ?","explanation":"Le passage indique : « Je préfère rester deux nuits au même refuge. Nous pourrons observer le lac sans transporter les sacs toute la journée. » Cela justifie la réponse : Explorer sans porter tout le matériel."},{"number":6,"points":9,"correct":"A","options":["Ne pas les emporter","Les déposer au musée","Les conserver comme souvenirs","Les vendre au retour"],"passage":"La sortie sur l'estran nécessite des chaussures fermées. Les coquillages observés seront laissés sur place.\n\nLe guide expliquera comment se déplacer sans abîmer le milieu. Pensez aussi à emporter de l'eau pour la promenade.","question":"Quelle règle concerne les animaux observés ?","explanation":"Le passage indique : « La sortie sur l'estran nécessite des chaussures fermées. Les coquillages observés seront laissés sur place. » Cela justifie la réponse : Ne pas les emporter."},{"number":7,"points":9,"correct":"C","options":["Éviter de rencontrer le guide","Changer automatiquement de destination","Attendre une meilleure visibilité","Profiter d'un brouillard plus épais"],"passage":"Le guide propose de partir plus tard : le brouillard devrait se lever. Nous garderons le même parcours si les conditions le permettent.\n\nJe vous enverrai la nouvelle heure de rendez-vous ce soir. Attendez ma confirmation avant de rejoindre le parking de départ demain matin.","question":"Pourquoi modifier le départ ?","explanation":"Le passage indique : « Le guide propose de partir plus tard : le brouillard devrait se lever. Nous garderons le même parcours si les conditions le permettent. » Cela justifie la réponse : Attendre une meilleure visibilité."},{"number":8,"points":9,"correct":"A","options":["Prévoir une tenue chaude","Renoncer à toute protection","Se fier uniquement au temps sur le quai","Acheter un vêtement à chaque escale"],"passage":"Pour la croisière d'observation, apportez des vêtements chauds. Le soleil au port ne garantit pas une température agréable en mer.\n\nUn vêtement coupe-vent est conseillé. Les sacs pourront être rangés sous les sièges pendant le trajet.","question":"Quelle précaution est recommandée ?","explanation":"Le passage indique : « Pour la croisière d'observation, apportez des vêtements chauds. Le soleil au port ne garantit pas une température agréable en mer. » Cela justifie la réponse : Prévoir une tenue chaude."},{"number":9,"points":9,"correct":"D","options":["Un accès à tous les étages par ascenseur","Une fermeture complète aux visiteurs","Une montée en voiture","Une découverte sans ascension"],"passage":"La visite du phare comprend un escalier étroit. Une présentation au pied de la tour est proposée aux personnes qui ne peuvent pas monter.\n\nVous pourrez choisir la formule qui vous convient avant d'acheter votre billet.","question":"Quelle solution alternative existe ?","explanation":"Le passage indique : « La visite du phare comprend un escalier étroit. Une présentation au pied de la tour est proposée aux personnes qui ne peuvent pas monter. » Cela justifie la réponse : Une découverte sans ascension."},{"number":10,"points":9,"correct":"A","options":["Essayer le matériel avant de choisir","Obtenir un achat définitif gratuit","Remplacer les conseils du guide par un tirage au sort","Éviter toute observation"],"passage":"Je vais louer des jumelles pour cette sortie, puis décider si j'en achète. Je ne connais pas encore le modèle adapté.\n\nLe magasin permet d'essayer plusieurs grossissements. Je demanderai aussi des conseils sur le poids et le confort pendant une longue marche.","question":"Pourquoi louer d'abord ?","explanation":"Le passage indique : « Je vais louer des jumelles pour cette sortie, puis décider si j'en achète. Je ne connais pas encore le modèle adapté. » Cela justifie la réponse : Essayer le matériel avant de choisir."},{"number":11,"points":15,"correct":"D","options":["Garantir l'absence de changement","Modifier artificiellement la taille du glacier","Éviter de noter les dates","Rendre l'évolution observable de manière comparable"],"passage":"Une équipe suit l'évolution d'un glacier grâce à des photographies prises depuis des repères fixes. Des images sans localisation précise seraient plus difficiles à comparer.\n\nLes observateurs reviennent au même endroit à des périodes comparables et notent les conditions de prise de vue. Le cadrage permet de reconnaître les rochers autour de la glace et d'éviter de confondre un changement d'angle avec un recul réel. Les données sont ensuite rapprochées d'autres mesures réalisées sur le terrain. Une photographie spectaculaire prise par un visiteur peut être intéressante, mais elle ne remplace pas à elle seule cette série documentée.","question":"Pourquoi conserver les mêmes repères ?","explanation":"Le passage indique : « Une équipe suit l'évolution d'un glacier grâce à des photographies prises depuis des repères fixes. Des images sans localisation précise seraient plus difficiles à comparer. » Cela justifie la réponse : Rendre l'évolution observable de manière comparable."},{"number":12,"points":15,"correct":"A","options":["Elles ont une fonction dans le milieu","Elles empêchent toute vie animale","Elles remplacent les poubelles","Elles sont toutes dangereuses à toucher"],"passage":"Des visiteurs ramassent des déchets sur la plage, mais laissent les algues échouées. Elles servent d'abri et de ressource à plusieurs espèces.\n\nLes bénévoles utilisent des sacs séparés pour le plastique, le verre et les autres déchets. Un animateur explique au départ ce qui appartient naturellement au milieu et doit y rester. Les enfants peuvent participer avec un adulte. Les organisateurs fourniront des gants et rappelleront les précautions nécessaires.","question":"Pourquoi ne pas retirer les algues ?","explanation":"Le passage indique : « Des visiteurs ramassent des déchets sur la plage, mais laissent les algues échouées. Elles servent d'abri et de ressource à plusieurs espèces. » Cela justifie la réponse : Elles ont une fonction dans le milieu."},{"number":13,"points":15,"correct":"C","options":["Une reproduction identique chaque jour","L'absence de tout contact professionnel","Le maintien de l'activité portuaire","L'arrêt de tous les navires"],"passage":"Un port propose des visites de ses métiers. Les parcours changent selon les opérations en cours pour ne pas gêner les travailleurs.\n\nLe guide confirme l'itinéraire juste avant le départ après un échange avec les responsables des quais. Un chargement en cours peut conduire le groupe vers un autre secteur, où les visiteurs découvriront une activité différente. Le billet donne accès à une découverte du port en fonctionnement, sans promettre le passage devant chaque équipement. Le programme rappelle donc que les besoins du travail déterminent certaines étapes de la visite, même lorsque des photographies publicitaires montrent un parcours précis.","question":"Quel besoin encadre la visite ?","explanation":"Le passage indique : « Un port propose des visites de ses métiers. Les parcours changent selon les opérations en cours pour ne pas gêner les travailleurs. » Cela justifie la réponse : Le maintien de l'activité portuaire."},{"number":14,"points":15,"correct":"B","options":["Accélérer la formation des roches","Préserver un milieu sensible","Transformer la grotte en parking","Garantir un éclairage permanent"],"passage":"Une réserve limite les groupes dans une grotte. Le passage répété modifie les conditions du lieu et peut fragiliser certaines formations.\n\nLes guides expliquent notamment que la présence des visiteurs peut modifier l'humidité et apporter des éléments extérieurs. Le nombre de places a été fixé à partir d'observations régulières, et sera révisé si l'état du site le nécessite. Une réservation évite aux groupes de se présenter tous au même moment. Les personnes qui ne peuvent pas entrer disposent d'une présentation filmée à l'accueil. La réserve souhaite ainsi rendre la découverte possible tout en surveillant les effets concrets de son ouverture au public.","question":"Pourquoi encadrer la fréquentation ?","explanation":"Le passage indique : « Une réserve limite les groupes dans une grotte. Le passage répété modifie les conditions du lieu et peut fragiliser certaines formations. » Cela justifie la réponse : Préserver un milieu sensible."},{"number":15,"points":15,"correct":"A","options":["Conserver une solution de repli","Suivre uniquement les autres marcheurs","Interdire tout appareil numérique","Éviter d'apprendre les repères"],"passage":"Une association enseigne la lecture d'une carte avant d'utiliser le téléphone en randonnée. Les participants doivent pouvoir s'orienter si la batterie se vide.\n\nL'atelier commence par le repérage de quelques éléments visibles autour du village. Les participants apprennent ensuite à relier ces repères au dessin et à utiliser la légende. Le téléphone reste utile pour préparer le trajet ou confirmer une position, mais ne constitue pas l'unique ressource du groupe. Chaque équipe emporte une carte imprimée protégée de la pluie. Le guide vérifie enfin que chacun comprend le chemin de retour et les points où il sera possible de demander de l'aide.","question":"Quel objectif est poursuivi ?","explanation":"Le passage indique : « Une association enseigne la lecture d'une carte avant d'utiliser le téléphone en randonnée. Les participants doivent pouvoir s'orienter si la batterie se vide. » Cela justifie la réponse : Conserver une solution de repli."},{"number":16,"points":15,"correct":"B","options":["Vendre toutes les captures","Participer à un suivi des animaux","Décorer les billets de bateau","Remplacer les règles de navigation"],"passage":"Des pêcheurs photographient certaines captures puis les relâchent selon le protocole de suivi. Les images servent à identifier les individus observés.\n\nLes participants reçoivent une fiche indiquant les angles de vue nécessaires et les informations à noter. Une image floue ou sans date peut être difficile à exploiter. Les données sont transmises à l'équipe scientifique, qui vérifie si le même animal a été signalé auparavant. Les pêcheurs ne doivent pas prolonger la manipulation pour obtenir une image plus esthétique.","question":"Quel usage est fait des photographies ?","explanation":"Le passage indique : « Des pêcheurs photographient certaines captures puis les relâchent selon le protocole de suivi. Les images servent à identifier les individus observés. » Cela justifie la réponse : Participer à un suivi des animaux."},{"number":17,"points":15,"correct":"C","options":["La lecture des panneaux","La croissance normale des fleurs","L'usure cumulée du milieu","La diversité des itinéraires autorisés"],"passage":"Un parc conseille de rester sur les sentiers même lorsque les plantes semblent résistantes. Des passages dispersés peuvent fragiliser progressivement le sol.\n\nUne empreinte isolée paraît parfois sans conséquence, mais les passages répétés élargissent progressivement les zones dénudées. L'eau s'y écoule autrement et peut emporter les couches les plus fines. Des panneaux montrent l'évolution de plusieurs secteurs suivis depuis quelques années. Les visiteurs sont invités à utiliser les points d'arrêt aménagés pour observer le paysage ou prendre des photographies. Le parc vérifie également que les sentiers officiels restent praticables, afin que cette recommandation soit réellement facile à suivre.","question":"Quel effet veut-on limiter ?","explanation":"Le passage indique : « Un parc conseille de rester sur les sentiers même lorsque les plantes semblent résistantes. Des passages dispersés peuvent fragiliser progressivement le sol. » Cela justifie la réponse : L'usure cumulée du milieu."},{"number":18,"points":15,"correct":"D","options":["Par la vente des bateaux","Par l'arrêt définitif des cours","Par une sortie malgré l'interdiction","Par des apprentissages sans navigation"],"passage":"Une école de voile organise une séance à terre lorsque la météo empêche de sortir. Les élèves travaillent alors les nœuds et la préparation du bateau.\n\nLes moniteurs utilisent un mât d'entraînement et des cordages pour préparer les prochaines navigations. Les élèves repèrent aussi les éléments à contrôler avant le départ. La séance conserve ainsi un objectif pédagogique même sans déplacement sur l'eau. Le centre informe les familles dès que la décision est prise et explique les raisons du changement.","question":"Comment la formation continue-t-elle ?","explanation":"Le passage indique : « Une école de voile organise une séance à terre lorsque la météo empêche de sortir. Les élèves travaillent alors les nœuds et la préparation du bateau. » Cela justifie la réponse : Par des apprentissages sans navigation."},{"number":19,"points":15,"correct":"D","options":["Les relevés actuels suffisent à décrire tous les siècles","Les cartes anciennes sont toutes inutiles","La côte reste identique partout","Le littoral évolue dans le temps"],"passage":"Un musée du littoral présente les variations du trait de côte. Les cartes anciennes sont comparées aux relevés actuels, sans supposer que le rivage a toujours été fixe.\n\nL'exposition présente les sources utilisées et leurs limites de précision. Une ancienne carte peut décrire les accès d'un port sans relever chaque détail de la plage. Les visiteurs découvrent comment les spécialistes croisent plusieurs documents avant de parler d'un déplacement du rivage.","question":"Quelle idée est mise en évidence ?","explanation":"Le passage indique : « Un musée du littoral présente les variations du trait de côte. Les cartes anciennes sont comparées aux relevés actuels, sans supposer que le rivage a toujours été fixe. » Cela justifie la réponse : Le littoral évolue dans le temps."},{"number":20,"points":21,"correct":"C","options":["Fermer tous les équipements existants","Garantir de la neige toute l'année","Construire des offres qui ne dépendent pas uniquement du ski","Transformer chaque habitant en moniteur"],"passage":"Une station de montagne diversifie ses activités au-delà du ski. Les parcours à pied et les rencontres culturelles utilisent des ressources différentes, mais demandent aussi une organisation adaptée. Les accompagnateurs doivent être formés et les itinéraires entretenus en dehors de la saison habituelle. Certains commerces adaptent leurs horaires pour accueillir un public différent. La commune consulte les habitants afin de ne pas concentrer toutes les nouveautés sur les lieux déjà très fréquentés. Elle veut aussi vérifier que les recettes et les emplois ne dépendent pas simplement d'un changement d'affiche.","question":"Quel enjeu accompagne cette diversification ?","explanation":"Le passage indique : « Une station de montagne diversifie ses activités au-delà du ski. Les parcours à pied et les rencontres culturelles utilisent des ressources différentes, mais demandent aussi une organisation adaptée. » Cela justifie la réponse : Construire des offres qui ne dépendent pas uniquement du ski."},{"number":21,"points":21,"correct":"A","options":["Permettre l'accès en préservant des fonctions naturelles","Supprimer la végétation pour mieux la protéger","Interdire toute présence humaine","Remplacer toutes les dunes par du béton"],"passage":"Une commune aménage un accès à la mer sans retirer toute la végétation. Les plantes stabilisent certaines zones et participent au fonctionnement des dunes. Les visiteurs circuleront sur un passage qui évite les secteurs les plus fragiles. Les services techniques prévoient des contrôles après les tempêtes et une signalisation compréhensible depuis le parking. Des habitants avaient demandé un dégagement plus large pour voir directement l'eau ; le projet explique pourquoi cette demande ne peut pas être satisfaite partout.","question":"Quel équilibre est recherché ?","explanation":"Le passage indique : « Une commune aménage un accès à la mer sans retirer toute la végétation. Les plantes stabilisent certaines zones et participent au fonctionnement des dunes. » Cela justifie la réponse : Permettre l'accès en préservant des fonctions naturelles."},{"number":22,"points":21,"correct":"C","options":["S'approcher toujours davantage","Faire sortir les oiseaux de leurs refuges","Limiter l'observation pour respecter les animaux","Éclairer les nids en continu"],"passage":"Des chercheurs observent les oiseaux depuis un abri éloigné. Ils acceptent de voir moins de détails afin de réduire la perturbation des colonies. L'abri permet de rester longtemps au même endroit sans multiplier les déplacements près des nids. Les observations sont notées selon une méthode commune pour être comparées d'une séance à l'autre. Lorsque la visibilité est mauvaise, certaines informations restent inconnues et sont signalées comme telles. Les chercheurs préfèrent conserver cette limite plutôt que s'approcher davantage pour compléter chaque case.","question":"Quel compromis est choisi ?","explanation":"Le passage indique : « Des chercheurs observent les oiseaux depuis un abri éloigné. Ils acceptent de voir moins de détails afin de réduire la perturbation des colonies. » Cela justifie la réponse : Limiter l'observation pour respecter les animaux."},{"number":23,"points":21,"correct":"D","options":["Supprimer toute information de sécurité","Reconstruire systématiquement chaque mètre au même endroit","Garantir l'immobilité de la falaise","Adapter le parcours à l'évolution du site"],"passage":"Une promenade littorale est déplacée après l'érosion d'une portion de falaise. Les responsables expliquent que maintenir exactement l'ancien tracé serait coûteux et dangereux. Le nouveau parcours passe plus à l'intérieur des terres et rejoint le belvédère par une pente douce. Des panneaux expliquent les raisons du déplacement avec des photographies datées. Les habitants pourront signaler les difficultés d'accès rencontrées pendant les premières semaines. Les services surveilleront aussi la partie fermée, car l'installation d'une barrière ne met pas fin au phénomène naturel.","question":"Quelle réponse est adoptée ?","explanation":"Le passage indique : « Une promenade littorale est déplacée après l'érosion d'une portion de falaise. Les responsables expliquent que maintenir exactement l'ancien tracé serait coûteux et dangereux. » Cela justifie la réponse : Adapter le parcours à l'évolution du site."},{"number":24,"points":21,"correct":"C","options":["La longueur du nom du refuge","La couleur des couvertures","La capacité réelle des ressources et des services","Le nombre de photos en ligne"],"passage":"Un refuge mesure ses besoins en eau avant d'augmenter sa capacité. Accueillir plus de personnes n'est possible que si les ressources et les équipements suivent. Les responsables examinent les réserves disponibles en fin de saison et le fonctionnement de l'assainissement. Ils prennent en compte les visiteurs de passage, qui utilisent également les installations. Plusieurs solutions seront comparées avant de décider du nombre de lits supplémentaire. Le projet pourrait être revu à la baisse si les besoins dépassent les possibilités du lieu.","question":"Quelle condition limite l'agrandissement ?","explanation":"Le passage indique : « Un refuge mesure ses besoins en eau avant d'augmenter sa capacité. Accueillir plus de personnes n'est possible que si les ressources et les équipements suivent. » Cela justifie la réponse : La capacité réelle des ressources et des services."},{"number":25,"points":21,"correct":"D","options":["La possibilité d'apprendre à partir de traces et d'indices en l'absence d'animaux visibles.","L'intérêt de respecter le déplacement libre des animaux dans leur milieu.","L'idée qu'un parcours peut être adapté aux conditions observées sur place.","L'exigence de photographier chaque espèce annoncée pour que l'activité soit considérée comme réussie."],"passage":"Une sortie d'observation annonce des espèces possibles, pas une rencontre garantie. Le guide rappelle que les animaux restent libres et que l'absence d'apparition ne signifie pas que le milieu est vide. L'itinéraire suit les conditions du jour et les observations récentes, sans poursuivre les animaux lorsqu'ils s'éloignent. Une partie de la séance est consacrée aux traces, aux habitats et aux techniques de repérage. Les participants repartent donc avec des connaissances même si aucune espèce spectaculaire ne se montre. À la fin de la marche, aucun grand mammifère n'a été aperçu mais les participants savent reconnaître plusieurs empreintes et habitats. Le guide considère ces observations comme un résultat valable.","question":"Quelle attente la sortie demande-t-elle de modifier ?","explanation":"L'annonce promet des espèces possibles, pas une observation garantie. D désigne l'attente erronée; A/C/B sont compatibles avec le guide."},{"number":26,"points":21,"correct":"D","options":["La couche de découverte détermine l'importance historique de l'objet, même lorsque son usage reste encore inconnu.","Deux objets semblables relevés sur un même chantier peuvent être attribués au commerce ancien malgré des couches différentes.","Un objet trouvé dans un remblai récent date nécessairement de cette période, quelles que soient ses traces de fabrication.","La position des objets et les éléments trouvés autour d'eux précisent le contexte historique de leur interprétation."],"passage":"Une ville portuaire expose des objets trouvés lors d'un chantier. Leur emplacement de découverte est documenté, car un objet isolé de son contexte perd une partie des informations qu'il peut apporter. Les archéologues relèvent aussi les éléments proches et les couches dans lesquelles chaque découverte apparaît. Ces indications peuvent renseigner sur la date, les usages ou les échanges commerciaux. Dans l'exposition, une photographie du chantier accompagne les principales pièces. Deux objets semblables sont retrouvés, l'un dans une couche datée du commerce maritime ancien et l'autre dans des remblais récents. Leur interprétation historique diffère grâce aux relevés d'origine.","question":"Pourquoi la ressemblance matérielle des objets ne suffit-elle pas à leur attribuer le même sens ?","explanation":"D explique que l'emplacement et les objets associés modifient l'interprétation d'une même forme. A confond contexte et valeur intrinsèque, B ignore les couches distinctes, C attribue sans preuve la date du remblai à celle de fabrication."},{"number":27,"points":21,"correct":"B","options":["La fermeture prouve que les animaux ne fréquentent jamais les secteurs ouverts en hiver.","Adapter l'accès selon les observations du cycle de reproduction, même en cas d'avance.","Le calendrier touristique est désormais le principal critère des ouvertures de sentier.","Les visiteurs doivent renoncer à tout itinéraire lorsque la reproduction commence."],"passage":"Un parc autorise certains accès en hiver et les ferme au printemps pendant la reproduction. La règle suit les besoins du milieu plutôt qu'un calendrier touristique identique toute l'année. Les gardes expliquent les périodes sensibles sur les panneaux et proposent des itinéraires de remplacement. Les dates sont réévaluées à partir des observations, car la reproduction ne commence pas toujours exactement au même moment. Une année, la reproduction commence plus tôt et les gardes avancent de quelques jours la fermeture d'un secteur. Les panneaux expliquent le suivi des espèces et indiquent un passage alternatif.","question":"Que révèle le changement de date d'interdiction ?","explanation":"Les règles suivent les périodes sensibles observées. B; C/D/A ajoutent des effets non établis."},{"number":28,"points":21,"correct":"D","options":["Les souvenirs locaux suffisent à dater l'intensité de la tempête lorsque les instruments officiels sont incomplets.","La diversité des dommages relatés empêche de comparer l'événement avec les relevés d'autres épisodes.","Des intensités météorologiques comparables permettent de prévoir des dégâts similaires dans les mêmes rues.","Rapprocher les relevés régionaux des conséquences locales rapportées par les habitants, sans confondre les deux sources."],"passage":"Des habitants comparent les récits d'une grande tempête avec des relevés officiels. Les souvenirs décrivent les effets vécus ; les mesures situent l'événement dans une série plus longue. Les habitants situent les routes coupées, les maisons atteintes et les décisions prises pendant la nuit. Les relevés permettent de comparer la force du vent et la hauteur de l'eau avec d'autres épisodes. Le projet conserve la distinction entre ces sources au lieu de demander à chacune de fournir les mêmes informations. Un témoin décrit l'inondation de sa rue; les relevés montrent que l'intensité régionale était comparable à celle d'un épisode antérieur, mais que les dégâts ont été concentrés dans d'autres quartiers.","question":"Quel apport résulte du rapprochement entre mémoire vécue et mesures ?","explanation":"D associe mesures régionales comparables et distribution locale des conséquences. A remplace des relevés par des souvenirs, B rejette leur complémentarité et C suppose que des intensités proches créent partout les mêmes dégâts."},{"number":29,"points":21,"correct":"A","options":["Consacrer plus de temps à chaque site plutôt que multiplier les étapes.","L'absence d'explications du guide afin de laisser toute la place au silence.","Le nombre maximal de lieux atteints au prix d'arrêts moins fréquents.","La garantie de rencontrer davantage d'espèces grâce à des déplacements plus courts."],"passage":"Une entreprise propose des excursions plus lentes en bateau. Elle réduit le nombre de sites visités pour consacrer davantage de temps à l'observation et à l'explication. Les guides peuvent arrêter le moteur à certains moments pour écouter les sons du milieu. Les clients sont informés du programme avant de réserver afin d'éviter de confondre cette formule avec un circuit rapide. L'excursion lente visite deux criques au lieu de cinq. Certains participants apprécient la durée des observations, d'autres préfèrent un programme plus dense; les deux formules sont clairement présentées avant réservation.","question":"Quel critère distingue principalement l'excursion lente d'une tournée rapide ?","explanation":"Moins de sites permet plus d'observation et d'explication. A; C est l'opposé, D/B ne sont pas justifiés."},{"number":30,"points":26,"correct":"C","options":["Lire les murets comme des éléments purement naturels puisqu'ils font partie de la vue actuelle.","Supposer que le travail humain explique toute évolution de la végétation, indépendamment du climat.","Distinguer des processus naturels et des pratiques d'entretien qui contribuent conjointement à la forme observée.","Considérer qu'un paysage apprécié doit rester inchangé pour conserver son intérêt touristique."],"passage":"La beauté d'un paysage peut donner l'impression d'un espace sans travail humain. Pourtant, terrasses, pâtures et chemins résultent souvent d'un entretien continu. Une visite guidée rend ces activités visibles sans nier les processus naturels qui façonnent aussi le lieu. Des éleveurs expliquent par exemple comment leur activité maintient certains espaces ouverts. Les visiteurs découvrent aussi les difficultés d'accès aux parcelles et les changements liés aux saisons. Cette lecture du paysage fait apparaître des décisions économiques et sociales derrière une vue souvent présentée comme uniquement naturelle. Sur une terrasse cultivée, le maintien des murets dépend du travail des habitants, tandis que la végétation évolue aussi avec les pluies. Le guide évite d'attribuer le paysage à une seule origine.","question":"Quelle interprétation du paysage la visite rend-elle possible ?","explanation":"Le paysage résulte d'interactions entre environnement et activités humaines. C. A/B/D réduisent cette complexité."},{"number":31,"points":26,"correct":"D","options":["Le classement en zone de risque faible permet de conclure à une protection suffisante sans autre examen.","Une zone inscrite sur la carte sera touchée lors du prochain épisode correspondant à sa catégorie de risque.","Les probabilités indiquées suffisent pour calculer la date et l'impact exacts sur chaque bâtiment.","La carte estime des probabilités de risque sans annoncer la date exacte d'un sinistre pour chaque parcelle."],"passage":"Une carte de risques n'annonce pas qu'un événement touchera chaque parcelle à une date précise. Elle décrit des zones et des probabilités utiles à la décision. La lire comme une prédiction individuelle certaine conduirait à des attentes que l'outil ne peut pas satisfaire. Les services accompagnent donc la carte d'exemples et d'une explication des marges d'incertitude. Une zone peu exposée ne signifie pas que tout danger y est absent. La carte classe une parcelle dans une zone où l'inondation est peu probable; un agent rappelle que cette faible probabilité ne correspond pas à une absence de danger et ne permet pas de fixer une date.","question":"Quelle lecture de la carte évite une erreur de prévision ?","explanation":"D reconnaît un outil probabiliste utile aux décisions mais non capable de dater un sinistre individuel. A confond faible et nul, B promet l'événement suivant et C prête à la carte une précision absente."},{"number":32,"points":26,"correct":"B","options":["L'accès amélioré mesure la réussite du parking sans examiner les sentiers.","Un bénéfice individuel d'accès peut accroître la pression cumulée sur les lieux fréquentés.","Les nouveaux passages montrent que les visiteurs restent sur les chemins aménagés et évitent désormais les zones sensibles.","Le gain d'accessibilité doit être évalué par les trajets évités, plutôt que par la fréquentation des sentiers fragiles."],"passage":"Un équipement touristique peut faciliter la découverte d'un site tout en augmentant sa fréquentation. Les responsables étudient donc les effets de la nouvelle accessibilité avant d'agrandir davantage. Un aménagement utile individuellement peut créer une pression collective supplémentaire. Un parking plus grand peut ainsi modifier les heures d'arrivée et les déplacements sur les chemins. Les gestionnaires suivent ces changements pendant une saison avant de prévoir de nouvelles capacités. Ils cherchent à comprendre l'ensemble des effets du projet. Le nouveau parking réduit la difficulté d'accès aux sentiers, mais les agents mesurent davantage de passages sur une zone fragile. Le projet est réexaminé avec les effets de cette hausse de fréquentation.","question":"Pourquoi un aménagement facilitant l'accès doit-il aussi être évalué collectivement ?","explanation":"B articule l'accès plus facile et la pression cumulée observée sur une zone fragile. A sépare artificiellement fréquentation et effets du projet, C suppose une concentration sur les passages sûrs démentie par les mesures et D écarte l'impact sur le site."},{"number":33,"points":26,"correct":"C","options":["La préférence des habitants pour la digue doit primer dans l'évaluation lorsque cet ouvrage est associé à l'histoire locale.","La protection par la digue doit être retenue si son coût initial est inférieur, même avec un risque résiduel élevé.","Comparer à long terme les coûts, les risques et les usages que chaque stratégie permet de préserver.","Le retrait progressif peut être jugé plus durable sans examiner les conséquences concrètes pour les résidents."],"passage":"Un littoral évolue malgré des ouvrages de protection. Certains habitants demandent d'adapter les usages plutôt que renforcer sans cesse les mêmes défenses. Le débat ne sépare pas simplement ceux qui protègent et ceux qui abandonnent : il porte aussi sur ce qui peut être maintenu et à quel coût. Les propositions comparent les dépenses sur plusieurs années et les conséquences pour les habitants concernés. Face à l'érosion, une commune compare le renforcement d'une digue et le déplacement progressif de certains équipements. Elle étudie les coûts, les risques résiduels et les habitants concernés dans chaque scénario.","question":"Quel critère doit structurer le débat entre les deux stratégies ?","explanation":"C demande une comparaison des coûts, risques et usages sur plusieurs années. A donne priorité au symbole, B au seul coût initial et D conclut sans examiner les personnes concernées."},{"number":34,"points":26,"correct":"C","options":["Des nuitées stables permettent de considérer les retombées du tourisme comme équivalentes malgré les changements de consommation d'eau.","La baisse des besoins en eau suffit à inférer une meilleure qualité d'emploi, les deux évolutions accompagnant la même fréquentation.","Une fréquentation égale ne garantit pas des effets sociaux et environnementaux équivalents, entre saisons.","Les nuitées permettent d'estimer directement la durée des contrats saisonniers."],"passage":"Une station mesure sa réussite au nombre de nuitées. Une association propose aussi d'examiner les ressources consommées et la qualité des emplois. Une hausse de fréquentation peut produire des bénéfices tout en accentuant des contraintes mal décrites par le seul volume des séjours. Le bilan peut distinguer les emplois saisonniers des emplois durables et regarder les déplacements nécessaires pour travailler. Deux saisons affichent le même nombre de nuitées, mais la seconde consomme moins d'eau et stabilise davantage les contrats de travail. L'association considère ce progrès invisible dans les seuls chiffres de fréquentation.","question":"Quelle limite de l'indicateur des nuitées ce cas illustre-t-il ?","explanation":"C distingue une fréquentation identique et des effets sociaux et environnementaux différents. A assimile fréquentation et retombées, B déduit les contrats de l'eau consommée et D déduit la qualité de l'emploi des seules nuitées."},{"number":35,"points":26,"correct":"B","options":["Les visites libres favorisent davantage la connaissance du site si elles permettent aux visiteurs de circuler sans restriction.","Les conséquences dépendent des modalités d'accès et de protection du site, dans les deux dispositifs de visite.","La présence de guides protège le site indépendamment du nombre de passages concentrés sur les zones fragiles.","Les revenus des billets compensent écologiquement les dommages dès qu'ils financent une partie du suivi de la réserve."],"passage":"La découverte d'un espace naturel peut sensibiliser à sa protection. Elle peut aussi l'abîmer si les conditions de visite sont mal organisées. Le lien entre fréquentation et préservation n'est donc ni automatique ni nécessairement impossible : il dépend des usages et de leur encadrement. Des visites limitées et accompagnées peuvent financer un suivi du site et transmettre des connaissances. À l'inverse, une publicité sans préparation peut concentrer trop de personnes sur des passages fragiles. Une réserve ouvre des parcours balisés avec des guides qui limitent les passages fragiles. Une autre campagne attire des foules sans encadrement; le même intérêt pour la nature n'entraîne pas les mêmes effets sur les sols.","question":"Que permet de distinguer la comparaison des deux dispositifs de visite ?","explanation":"B distingue l'intérêt de découvrir un site des effets d'un accès balisé ou non sur les sols. A suppose la liberté bénéfique, C attribue aux guides une protection inconditionnelle et D confond financement et compensation écologique."},{"number":36,"points":33,"correct":"A","options":["Une portion brève peut imposer des capacités particulières non visibles dans le chiffre de distance.","Le nombre total de randonneurs renseigne davantage sur la difficulté d'un passage que ses caractéristiques physiques.","Des photographies de l'itinéraire donnent une meilleure prévision des conditions du jour que l'étude du terrain.","Une faible distance traduit une faible exposition puisque les passages difficiles restent nécessairement courts."],"passage":"Un sentier réputé facile attire de nombreux débutants. La description indique une faible distance, mais ne mentionne pas un passage très exposé. Des guides demandent de compléter l'information. Une difficulté globale ne se déduit pas d'un seul chiffre lorsque certaines portions exigent des capacités particulières. Le nouveau descriptif séparera la longueur, le dénivelé, la nature du sol et les passages où une chute aurait des conséquences importantes. Des photographies datées montreront les portions qui prêtent le plus à confusion. Les accompagnateurs rappellent aussi que la pluie, la chaleur ou la fatigue peuvent modifier l'expérience d'un même trajet. Ils souhaitent donner aux visiteurs les moyens de comparer le parcours à leurs capacités et à leur équipement. La mention facile pourra rester un repère, mais elle sera accompagnée d'informations qui permettent de comprendre à quelles conditions elle correspond et quand choisir un autre itinéraire. Un itinéraire ne mesure que quatre kilomètres mais présente une courte traversée exposée au vide. Deux visiteurs capables de marcher cette distance n'ont pas nécessairement la même aisance sur ce passage.","question":"Pourquoi la faible longueur du sentier peut-elle induire les débutants en erreur ?","explanation":"A reconnaît qu'un passage exposé peut demander des capacités particulières malgré une faible distance. B confond popularité et difficulté; C privilégie des images datées; D infère la sécurité de la longueur."},{"number":37,"points":33,"correct":"B","options":["Les critères esthétiques mesurent mieux la réussite à long terme que le suivi des fonctions de stabilisation de la dune.","La restauration écologique peut être pertinente même quand ses dispositifs modifient temporairement l'apparence du paysage.","Les plantes installées apportent surtout un effet décoratif et influencent peu les mouvements de sable observés.","Les clôtures temporaires attestent que le paysage redeviendra aussi ouvert qu'avant après une seule saison."],"passage":"La restauration d'une dune peut sembler désordonnée : clôtures légères, plantes irrégulières, zones fermées. Certains visiteurs préfèrent un rivage entièrement dégagé. Les gestionnaires expliquent les fonctions du dispositif. Ce qui paraît moins soigné selon des critères décoratifs peut mieux répondre aux besoins du milieu. Les clôtures retiennent le sable et orientent les passages vers des accès précis. Certaines plantes installent leurs racines dans des secteurs qui semblaient auparavant vides, tandis que d'autres apparaissent plus lentement. Des panneaux présentent les étapes attendues de la restauration avec des images prises au même endroit. Les gestionnaires reconnaissent que le changement peut surprendre et organisent des visites pour répondre aux questions. Ils distinguent toutefois la perception esthétique immédiate du fonctionnement écologique observé sur plusieurs saisons. Sur une dune en restauration, les clôtures gênent temporairement la vue mais préservent des zones de végétation qui stabilisent le sable. Les panneaux suivent les changements sur plusieurs saisons.","question":"Pourquoi l'apparence moins ordonnée ne suffit-elle pas à juger l'opération négativement ?","explanation":"B distingue fonctionnement écologique et apparence instantanée. A privilégie l'image au suivi fonctionnel; C réduit le rôle des plantes; D promet un résultat esthétique et un calendrier non établis."},{"number":38,"points":33,"correct":"A","options":["La publicité d'un lieu solitaire attire une foule qui compromet justement la solitude promise aux visiteurs.","L'affluence actuelle prouve que les photographies d'origine exagéraient la solitude du lieu pour en accroître l'attrait.","Une forte fréquentation change l'expérience des visiteurs, mais la campagne garantit que chaque visite conserve son calme.","Orienter la fréquentation vers d'autres secteurs suffit à préserver la solitude du site principal sans examiner leur fragilité."],"passage":"Une destination valorise des images de solitude et de nature intacte. Le succès de ces images attire pourtant une fréquentation importante vers quelques lieux précis. La promesse qui motive la visite peut être fragilisée par l'ampleur même du public qu'elle attire. Des files d'attente apparaissent désormais devant les points de vue les plus diffusés sur les réseaux. Les visiteurs cherchent souvent à reproduire exactement la photographie qui leur a donné envie de venir. Les responsables du territoire réfléchissent donc à une communication plus précise sur les périodes fréquentées et les possibilités de découverte ailleurs. Ils ne souhaitent pas simplement déplacer la foule vers un autre endroit fragile. Les habitants et les gestionnaires seront associés au choix des itinéraires et aux limites d'accueil. L'objectif est de rendre l'expérience annoncée compatible avec la capacité réelle des lieux et avec la vie locale. Le lieu célèbre pour ses photos de solitude connaît désormais des files d'attente aux heures de pointe. Certains visiteurs repartent déçus, bien que la publicité ait fidèlement reproduit le paysage avant cette affluence.","question":"Quelle contradiction le succès de la campagne crée-t-il ?","explanation":"A est la contradiction: des images de solitude attirent une foule qui compromet cette même expérience. B remet sans preuve en cause les images initiales; C nie la transformation constatée; D garantit un transfert sans évaluer d'autres zones fragiles."},{"number":39,"points":33,"correct":"C","options":["Le nombre de restaurants ouverts en hiver suffit à estimer les emplois stables même lorsque les salariés résident loin.","Les offres d'emploi supplémentaires suffisent à mesurer la stabilité des travailleurs et leur accès au logement, sans suivre les contrats réellement renouvelés chaque année.","Le maintien effectif des salariés dans le temps, associé à leurs conditions de logement et de déplacement, sans attribuer tous les départs aux loyers.","La fréquentation des restaurants reste le meilleur indice de stabilité, même lorsque les postes ne sont pas durablement pourvus."],"passage":"Un village de montagne veut conserver ses activités toute l'année. Il développe des offres nouvelles, mais vérifie aussi le logement des salariés et l'accès aux services. Diversifier les loisirs ne suffit pas si les personnes qui font fonctionner le territoire ne peuvent pas y vivre dans des conditions stables. Les commerçants expliquent qu'ils peuvent ouvrir plus longtemps seulement s'ils trouvent du personnel disponible. Les salariés évoquent pour leur part les loyers, les trajets et la fermeture de certains services hors saison. Le conseil municipal examine donc ces questions avec le programme touristique, plutôt que de les traiter après le lancement des nouvelles offres. Une activité supplémentaire peut renforcer le territoire si elle s'appuie sur des conditions de travail et d'habitat durables. Le bilan portera sur la continuité des emplois, l'accès aux besoins quotidiens et les retours des habitants, en complément des chiffres de fréquentation. Un nouveau programme permet l'ouverture de restaurants en hiver, mais les employés recrutés habitent loin faute de logements abordables et doivent conduire plus longtemps. Le conseil examine l'habitat et les services avant d'étendre l'offre. Après le lancement, le nombre d'offres d'emploi d'hiver augmente et davantage de restaurants annoncent une ouverture toute l'année. Pourtant, les contrats les plus courts sont renouvelés difficilement: une enquête auprès des employés constate que plusieurs ne trouvent pas de location dans le village et renoncent après une saison de longs déplacements. Le conseil compare les postes proposés, ceux effectivement pourvus pendant six mois et la résidence des salariés. Il constate que certaines entreprises ont maintenu leurs horaires grâce à du personnel venu de loin, sans que cela établisse une stabilisation des ménages sur place. L'association touristique souhaite retenir seulement le nombre de postes créés; le conseil répond que cet indicateur signale une demande de travail, mais ne permet pas, à lui seul, d'apprécier la continuité de la main-d'œuvre et de la vie locale. Les entretiens ne permettent toutefois pas de chiffrer précisément la part des départs imputable aux seuls loyers.","question":"Quel résultat supplémentaire serait le plus pertinent pour juger la stabilité promise plutôt que la seule extension touristique ?","explanation":"C suit le maintien réel des salariés, les logements et les trajets tout en respectant l'incertitude sur les causes des départs. A confond ouverture et emploi stable, B confond offres et personnes conservées, D retient la fréquentation au détriment de la continuité."}]}$paper_18$::jsonb),
('tcf-reading-19','tcf-reading-2026-11-distractor-polish-v5',$paper_19${"id":"tcf-reading-19","title":"TCF Reading · Test 19","seconds":3600,"version":"tcf-reading-2026-11-distractor-polish-v5","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"A","options":["L'ascenseur","La cour extérieure","Le portail piéton manuel","La boîte aux lettres"],"passage":"L'électricité sera coupée dans le bâtiment de dix à onze heures. L'ascenseur ne pourra pas être utilisé pendant cette période.\n\nMerci de prévoir vos déplacements avant le début de l'intervention. Les escaliers resteront accessibles pendant toute la durée des travaux.","question":"Quel équipement sera indisponible ?","explanation":"Le passage indique : « L'électricité sera coupée dans le bâtiment de dix à onze heures. L'ascenseur ne pourra pas être utilisé pendant cette période. » Cela justifie la réponse : L'ascenseur."},{"number":2,"points":3,"correct":"A","options":["Une facture récente","Une carte de fidélité","Un devis de déménagement","Un relevé de tous les comptes"],"passage":"Le conseiller énergie reçoit gratuitement samedi sur rendez-vous. Apportez une facture récente, sans vos coordonnées bancaires.\n\nLe rendez-vous permet de comprendre vos dépenses et de préparer vos questions sur le logement.","question":"Quel document est utile ?","explanation":"Le passage indique : « Le conseiller énergie reçoit gratuitement samedi sur rendez-vous. Apportez une facture récente, sans vos coordonnées bancaires. » Cela justifie la réponse : Une facture récente."},{"number":3,"points":3,"correct":"A","options":["Laisser les robinets dans l'état demandé","Démonter les radiateurs","Couper tous les tuyaux","Ouvrir toutes les fenêtres obligatoirement"],"passage":"Le test de chauffage aura lieu jeudi matin. Merci de ne pas fermer les robinets pendant l'intervention.\n\nL'équipe passera dans chaque étage. Un avis sera affiché dans le hall lorsque les vérifications seront terminées.","question":"Quelle consigne est donnée ?","explanation":"Le passage indique : « Le test de chauffage aura lieu jeudi matin. Merci de ne pas fermer les robinets pendant l'intervention. » Cela justifie la réponse : Laisser les robinets dans l'état demandé."},{"number":4,"points":3,"correct":"B","options":["Une alimentation électrique personnelle","Un support pédagogique","Une vente automatique de batteries","Un chauffage de la rue"],"passage":"Les panneaux de démonstration ne produisent pas d'électricité pour les visiteurs. Ils servent à expliquer le fonctionnement du système.\n\nUn animateur répondra à vos questions après la présentation. Merci de ne pas manipuler les câbles exposés sur la table.","question":"Quelle est leur fonction ?","explanation":"Le passage indique : « Les panneaux de démonstration ne produisent pas d'électricité pour les visiteurs. Ils servent à expliquer le fonctionnement du système. » Cela justifie la réponse : Un support pédagogique."},{"number":5,"points":9,"correct":"B","options":["Éviter toute analyse du logement","Évaluer les besoins avant de choisir l'équipement","Supprimer les factures existantes","Acheter l'appareil le plus puissant"],"passage":"Je préfère faire vérifier l'isolation avant de changer l'appareil de chauffage. Nous saurons mieux quelle puissance sera nécessaire.\n\nSi nous réduisons d'abord les pertes, nous pourrons comparer des modèles mieux adaptés au logement. Demande au conseiller un rendez-vous la semaine prochaine. Nous comparerons ensuite les devis.","question":"Pourquoi commencer par l'isolation ?","explanation":"Le passage indique : « Je préfère faire vérifier l'isolation avant de changer l'appareil de chauffage. Nous saurons mieux quelle puissance sera nécessaire. » Cela justifie la réponse : Évaluer les besoins avant de choisir l'équipement."},{"number":6,"points":9,"correct":"B","options":["Le nombre de pièces du magasin","Le temps d'usage","La couleur de la prise","La marque du carnet"],"passage":"L'atelier prête un appareil pour mesurer les consommations des petits équipements. Notez la durée d'utilisation avec la valeur affichée.\n\nUn tableau vous aidera à classer les relevés. Rapportez le matériel à la date indiquée sur votre fiche de prêt.","question":"Quelle information faut-il relever en plus ?","explanation":"Le passage indique : « L'atelier prête un appareil pour mesurer les consommations des petits équipements. Notez la durée d'utilisation avec la valeur affichée. » Cela justifie la réponse : Le temps d'usage."},{"number":7,"points":9,"correct":"C","options":["Une certification de tous les appareils","Une obligation d'acheter auprès du conseiller","Une orientation pour préparer les décisions","Un chantier immédiatement terminé"],"passage":"Votre visite conseil ne comprend pas la réalisation des travaux. Vous recevrez des pistes à comparer avec des devis professionnels.\n\nLe document résumera les points observés dans votre logement et les questions à poser aux entreprises. Vous resterez libre de choisir les interventions à engager.","question":"Quel résultat est proposé ?","explanation":"Le passage indique : « Votre visite conseil ne comprend pas la réalisation des travaux. Vous recevrez des pistes à comparer avec des devis professionnels. » Cela justifie la réponse : Une orientation pour préparer les décisions."},{"number":8,"points":9,"correct":"C","options":["Éteindre le magasin pendant ses heures d'ouverture","Supprimer l'enseigne","Réduire l'éclairage nocturne","Ajouter des lampes à l'intérieur"],"passage":"Nous baisserons l'éclairage de la vitrine après la fermeture. L'enseigne restera visible sans garder toutes les lampes allumées.\n\nLe responsable vérifiera le résultat depuis la rue. Merci de conserver le nouvel horaire sur la fiche du magasin.","question":"Quelle modification est prévue ?","explanation":"Le passage indique : « Nous baisserons l'éclairage de la vitrine après la fermeture. L'enseigne restera visible sans garder toutes les lampes allumées. » Cela justifie la réponse : Réduire l'éclairage nocturne."},{"number":9,"points":9,"correct":"D","options":["Le nombre de réunions passées","La couleur des affiches","La date de fondation du fabricant uniquement","Le suivi de l'équipement"],"passage":"Je peux participer à l'achat collectif, mais je veux connaître les conditions d'entretien avant de confirmer.\n\nPeux-tu demander au fournisseur qui intervient en cas de panne et si des frais réguliers sont prévus dans le contrat ?","question":"Quelle information manque pour décider ?","explanation":"Le passage indique : « Je peux participer à l'achat collectif, mais je veux connaître les conditions d'entretien avant de confirmer. » Cela justifie la réponse : Le suivi de l'équipement."},{"number":10,"points":9,"correct":"A","options":["Réduire l'entrée de chaleur","Empêcher toute aération nocturne","Refroidir le trottoir","Augmenter l'éclairage artificiel"],"passage":"La salle reste fraîche le matin. Fermez les volets des fenêtres exposées avant de partir pour limiter la chaleur de l'après-midi.\n\nLa personne qui ouvre le lendemain pourra les relever. Cette organisation doit être suivie par tous les utilisateurs de la salle.","question":"Quel objectif motive cette consigne ?","explanation":"Le passage indique : « La salle reste fraîche le matin. Fermez les volets des fenêtres exposées avant de partir pour limiter la chaleur de l'après-midi. » Cela justifie la réponse : Réduire l'entrée de chaleur."},{"number":11,"points":15,"correct":"C","options":["Choisir la couleur des façades","Supprimer la mesure de consommation","Éviter d'attribuer tout changement aux travaux","Garantir des hivers identiques"],"passage":"Une résidence suit ses consommations avant et après des travaux. Les températures extérieures sont aussi prises en compte pour comparer des périodes différentes.\n\nLe conseil syndical a d'abord constaté une baisse sur les factures et souhaitait l'attribuer entièrement à l'isolation. Le technicien rappelle qu'un hiver plus doux réduit également les besoins. Il rassemble donc les relevés et décrit les conditions de chaque période. Les habitants pourront lire les résultats avec une explication de la méthode et des limites de la comparaison. Cette présentation doit aider à comprendre ce qui semble lié aux interventions réalisées, sans transformer une simple différence entre deux factures en preuve suffisante.","question":"Pourquoi ajouter cette donnée ?","explanation":"Le passage indique : « Une résidence suit ses consommations avant et après des travaux. Les températures extérieures sont aussi prises en compte pour comparer des périodes différentes. » Cela justifie la réponse : Éviter d'attribuer tout changement aux travaux."},{"number":12,"points":15,"correct":"D","options":["Le nom de la rue","Le nombre de voisins","La couleur des factures","L'exposition du toit"],"passage":"Un installateur explique que l'orientation d'un toit influence la production solaire. Deux surfaces identiques ne produiront donc pas nécessairement la même quantité.\n\nLe conseiller observe également les ombres portées par les bâtiments voisins. Il prépare une estimation propre à chaque emplacement, au lieu d'appliquer un rendement unique à tous les projets. Les résultats seront présentés avec leurs hypothèses. Le propriétaire pourra poser ses questions avant de choisir un équipement.","question":"Quel facteur complète la superficie ?","explanation":"Le passage indique : « Un installateur explique que l'orientation d'un toit influence la production solaire. Deux surfaces identiques ne produiront donc pas nécessairement la même quantité. » Cela justifie la réponse : L'exposition du toit."},{"number":13,"points":15,"correct":"D","options":["Déclarer tous les murs défectueux","Choisir uniquement la couleur la plus vive","Remplacer l'examen par une impression","Comprendre le sens des observations"],"passage":"Une bibliothèque d'outils prête une caméra thermique avec une initiation. Les images doivent être interprétées, car une zone colorée n'explique pas seule l'origine d'un défaut.\n\nUne paroi humide, un reflet ou les conditions extérieures peuvent influencer l'apparence d'une image. Le formateur montre plusieurs exemples pris dans des situations connues avant de prêter le matériel. Les utilisateurs notent les circonstances de leurs observations et évitent de conclure immédiatement qu'un élément doit être remplacé. Le prêt vise à mieux repérer les questions à examiner, sans transformer l'appareil en outil capable de fournir automatiquement un diagnostic complet du bâtiment.","question":"Quelle aide est nécessaire ?","explanation":"Le passage indique : « Une bibliothèque d'outils prête une caméra thermique avec une initiation. Les images doivent être interprétées, car une zone colorée n'explique pas seule l'origine d'un défaut. » Cela justifie la réponse : Comprendre le sens des observations."},{"number":14,"points":15,"correct":"D","options":["Augmenter la consommation immédiatement","Remplacer toutes les vitres par des écrans","Fermer l'école chaque été","Réduire le besoin avant d'ajouter un appareil"],"passage":"Une école protège ses fenêtres exposées au soleil avant d'installer un refroidissement supplémentaire. Elle cherche d'abord à limiter la chaleur qui entre.\n\nDes stores extérieurs sont testés dans les classes les plus exposées. Les enseignants notent les moments où l'éblouissement et la température gênent les activités. Le projet prend aussi en compte la lumière nécessaire pour travailler et les conditions d'ouverture des fenêtres. Les résultats serviront à décider des interventions suivantes. La direction préfère vérifier l'effet des protections sur une saison avant de choisir de nouveaux équipements, afin que les dépenses répondent aux besoins effectivement observés dans les salles.","question":"Quelle priorité est donnée ?","explanation":"Le passage indique : « Une école protège ses fenêtres exposées au soleil avant d'installer un refroidissement supplémentaire. Elle cherche d'abord à limiter la chaleur qui entre. » Cela justifie la réponse : Réduire le besoin avant d'ajouter un appareil."},{"number":15,"points":15,"correct":"B","options":["Garantir la réparation de tout appareil","Informer sur les réparations réellement possibles","Vendre des pièces incompatibles","Refuser toute prise de contact"],"passage":"Une entreprise répare des appareils dont les pièces restent disponibles. Elle publie les modèles acceptés pour éviter des déplacements inutiles.\n\nLa liste précise les références et les principales catégories de panne prises en charge. Les clients peuvent envoyer une photographie de l'étiquette avant de transporter un objet lourd. Le réparateur explique ensuite les limites du diagnostic à distance et annonce un devis après examen. Si une pièce indispensable n'est plus disponible, il le signale avant l'intervention. Le service cherche ainsi à prolonger la vie des équipements lorsque c'est possible, tout en donnant une information suffisamment claire sur les cas acceptés.","question":"Pourquoi publier cette liste ?","explanation":"Le passage indique : « Une entreprise répare des appareils dont les pièces restent disponibles. Elle publie les modèles acceptés pour éviter des déplacements inutiles. » Cela justifie la réponse : Informer sur les réparations réellement possibles."},{"number":16,"points":15,"correct":"B","options":["Le nombre de décorations","L'évolution de l'occupation","La taille des boîtes aux lettres","Le prix des plantes"],"passage":"Des habitants partagent une chaufferie. Le suivi distingue la consommation totale et sa répartition, car une variation du nombre d'occupants peut modifier le bilan.\n\nLe bilan indique les périodes d'occupation, les températures retenues et les interventions effectuées sur l'installation. Les habitants peuvent ainsi distinguer une évolution du fonctionnement et une variation des usages. Une réunion annuelle permet de poser des questions sur la facturation. Le responsable présente les règles de calcul avec des exemples, car un chiffre total ne suffit pas toujours à expliquer ce que chaque ménage doit payer.","question":"Quelle information complète le total ?","explanation":"Le passage indique : « Des habitants partagent une chaufferie. Le suivi distingue la consommation totale et sa répartition, car une variation du nombre d'occupants peut modifier le bilan. » Cela justifie la réponse : L'évolution de l'occupation."},{"number":17,"points":15,"correct":"B","options":["Supprimer toute entrée d'air","Maintenir une ventilation adaptée","Ouvrir tous les murs","Éviter de lire les consignes"],"passage":"Un logement rénové reçoit un guide de ventilation. L'amélioration de l'étanchéité ne dispense pas d'un renouvellement d'air correctement organisé.\n\nLe document explique les entrées d'air, les bouches d'extraction et les signes qui doivent conduire à demander une vérification. Les habitants sont invités à ne pas obstruer les dispositifs lorsqu'ils ressentent un courant d'air. Ils peuvent contacter le gestionnaire pour comprendre un réglage ou signaler un bruit anormal. Une séance de présentation est organisée après les travaux. L'équipe souhaite que les gains thermiques s'accompagnent de bonnes conditions d'usage, plutôt que de laisser les occupants découvrir seuls les changements apportés au logement.","question":"Quelle précaution accompagne la rénovation ?","explanation":"Le passage indique : « Un logement rénové reçoit un guide de ventilation. L'amélioration de l'étanchéité ne dispense pas d'un renouvellement d'air correctement organisé. » Cela justifie la réponse : Maintenir une ventilation adaptée."},{"number":18,"points":15,"correct":"C","options":["Un chauffage uniquement décoratif","Une indépendance totale de tous les équipements","Un trajet de chaleur plus court","Une production sans installation"],"passage":"Une commune récupère la chaleur d'un équipement public pour alimenter un bâtiment voisin. La proximité limite les pertes lors du transport.\n\nLes techniciens comparent les heures où la chaleur est disponible avec celles où le bâtiment voisin en a besoin. Ils étudient aussi le fonctionnement du réseau lorsque l'équipement principal s'arrête. Le projet comprend un système complémentaire pour assurer la continuité du service. Avant d'engager les travaux, la commune présentera les coûts, les économies attendues et les principales incertitudes.","question":"Quel avantage présente l'emplacement ?","explanation":"Le passage indique : « Une commune récupère la chaleur d'un équipement public pour alimenter un bâtiment voisin. La proximité limite les pertes lors du transport. » Cela justifie la réponse : Un trajet de chaleur plus court."},{"number":19,"points":15,"correct":"A","options":["Adapter le choix à l'usage","Choisir selon le prix de l'emballage","Ignorer la durée d'éclairage","Installer partout la même puissance sans étude"],"passage":"Un groupe compare des lampes en tenant compte des heures d'éclairage. Une pièce rarement utilisée ne présente pas les mêmes besoins qu'un accueil ouvert toute la journée.\n\nLes participants notent la puissance et la durée d'utilisation avant de calculer une consommation estimée. Ils regardent aussi la qualité de la lumière nécessaire dans chaque espace. Une lampe adaptée à un passage bref n'est pas forcément celle qui convient à un poste de travail.","question":"Quelle démarche est adoptée ?","explanation":"Le passage indique : « Un groupe compare des lampes en tenant compte des heures d'éclairage. Une pièce rarement utilisée ne présente pas les mêmes besoins qu'un accueil ouvert toute la journée. » Cela justifie la réponse : Adapter le choix à l'usage."},{"number":20,"points":21,"correct":"B","options":["Le choix du devis le plus court uniquement","La cohérence entre les étapes","La suppression de toute anticipation","L'ordre alphabétique des entreprises"],"passage":"Une copropriété planifie ses travaux en plusieurs étapes. Elle vérifie que les premières interventions ne compliqueront pas les suivantes, notamment autour des façades et des fenêtres. Le maître d'œuvre présente un ordre possible et les points à vérifier avant chaque chantier. Les habitants comparent cette proposition avec leurs contraintes de financement et d'occupation. Certaines interventions pourront être regroupées pour éviter de reprendre un ouvrage récent. Le calendrier reste révisable, mais les décisions sont documentées pour que les équipes suivantes comprennent les choix déjà faits.","question":"Quelle attention guide le calendrier ?","explanation":"Le passage indique : « Une copropriété planifie ses travaux en plusieurs étapes. Elle vérifie que les premières interventions ne compliqueront pas les suivantes, notamment autour des façades et des fenêtres. » Cela justifie la réponse : La cohérence entre les étapes."},{"number":21,"points":21,"correct":"D","options":["Maintien constant de la température maximale","Réduction fixe sans exception","Suppression de toute occupation","Économie et adaptation aux usages réels"],"passage":"Un système automatique baisse le chauffage dans les salles vides. Les utilisateurs peuvent signaler une occupation imprévue pour éviter un inconfort. Un bouton permet de prolonger temporairement la présence sans modifier le programme de toute la semaine. Les agents examinent les demandes répétées afin de repérer un horaire habituel qui aurait été mal enregistré. Ils expliquent le fonctionnement aux associations qui utilisent les locaux en soirée. L'automatisation reste ainsi liée aux usages réels, avec une possibilité de correction lorsque le calendrier ne décrit pas correctement la situation.","question":"Quel équilibre est recherché ?","explanation":"Le passage indique : « Un système automatique baisse le chauffage dans les salles vides. Les utilisateurs peuvent signaler une occupation imprévue pour éviter un inconfort. » Cela justifie la réponse : Économie et adaptation aux usages réels."},{"number":22,"points":21,"correct":"C","options":["Le nombre de pages du devis uniquement","Le nom du modèle seulement","Les dépenses futures","La taille de l'affiche"],"passage":"Un conseiller compare le coût initial et les dépenses d'entretien de deux solutions. Une installation moins chère peut demander davantage de suivi pendant sa durée de vie. Les documents incluent les contrôles périodiques, les consommables et les interventions possibles en cas de panne. Les ménages peuvent ainsi comparer plusieurs scénarios sur une même durée. L'objectif est de rendre visibles les engagements après l'achat, sans prétendre connaître exactement toutes les dépenses qui surviendront au cours des années suivantes.","question":"Quel critère élargit la comparaison ?","explanation":"Le passage indique : « Un conseiller compare le coût initial et les dépenses d'entretien de deux solutions. Une installation moins chère peut demander davantage de suivi pendant sa durée de vie. » Cela justifie la réponse : Les dépenses futures."},{"number":23,"points":21,"correct":"A","options":["Adapter la protection aux saisons","Éviter toute attention à l'orientation","Assombrir définitivement le logement","Remplacer toutes les fenêtres"],"passage":"Des habitants testent une protection solaire mobile. Ils l'ouvrent en hiver pour laisser entrer la lumière et la ferment selon l'exposition en été. Les participants notent le confort, la luminosité et la facilité de manipulation à différents moments. Les essais ne portent donc pas seulement sur la température maximale. Une protection trop difficile à déplacer pourrait rester inutilisée malgré de bons résultats théoriques. Le groupe souhaite retenir une solution adaptée aux habitudes du logement.","question":"Quel intérêt offre sa mobilité ?","explanation":"Le passage indique : « Des habitants testent une protection solaire mobile. Ils l'ouvrent en hiver pour laisser entrer la lumière et la ferment selon l'exposition en été. » Cela justifie la réponse : Adapter la protection aux saisons."},{"number":24,"points":21,"correct":"C","options":["Un remplacement de tous les agents","Une absence de décision","Une capacité d'interprétation humaine","Un affichage sans explication"],"passage":"Une ville installe des capteurs dans ses bâtiments, puis forme les agents à lire les résultats. Les données seules n'auraient pas permis d'ajuster correctement les réglages. Les premières courbes montraient des écarts sans indiquer immédiatement leur cause. Les agents ont appris à rapprocher les heures de fonctionnement des réservations de salles et des opérations d'entretien. Ils peuvent désormais repérer un réglage oublié ou demander une vérification technique. Le dispositif prévoit un temps régulier pour examiner les informations.","question":"Quel complément est prévu ?","explanation":"Le passage indique : « Une ville installe des capteurs dans ses bâtiments, puis forme les agents à lire les résultats. Les données seules n'auraient pas permis d'ajuster correctement les réglages. » Cela justifie la réponse : Une capacité d'interprétation humaine."},{"number":25,"points":21,"correct":"C","options":["Savoir intervenir sur toute installation grâce à la lecture du compteur.","Réparer les équipements complexes en suivant les mêmes gestes qu'un joint simple.","Déterminer quand agir soi-même et quand la sécurité impose de solliciter un professionnel.","Renoncer à toute observation préalable afin de laisser l'intégralité du diagnostic au spécialiste."],"passage":"Un atelier montre comment détecter de petites fuites d'eau. Les participants apprennent aussi quand faire appel à un professionnel plutôt qu'intervenir eux-mêmes. L'animateur commence par montrer comment relever un compteur lorsque tous les points d'eau sont fermés. Il explique ensuite les limites des petites réparations accessibles avec des outils courants. Les participants repartent avec une liste de signes à surveiller et les informations utiles pour décrire un problème. Une fuite légère est repérée au compteur, mais l'atelier distingue le remplacement simple d'un joint et une anomalie proche d'une installation électrique. L'animateur demande dans le second cas une intervention qualifiée.","question":"Quelle compétence l'atelier ajoute-t-il à la détection technique des fuites ?","explanation":"Le programme enseigne les limites de l'autonomie. C, contrairement aux autres, distingue observation et intervention sûre."},{"number":26,"points":21,"correct":"A","options":["Une quantité totale semblable peut masquer des correspondances horaires différentes entre la production renouvelable et la consommation effective.","Le bilan annuel permet d'inférer le prix de l'installation, même si les volumes contractuels de production sont identiques.","La coïncidence horaire compense le besoin de documenter l'origine de l'électricité puisqu'elle mesure mieux les usages.","Deux contrats promettant un volume annuel égal assurent la même correspondance horaire entre production et consommation."],"passage":"Un collectif achète de l'électricité produite par plusieurs sources. Il demande des informations sur la méthode de comptage pour comprendre les engagements annoncés. Les responsables veulent savoir sur quelle période la production est rapprochée de la consommation et quels documents permettent de le vérifier. Ils souhaitent présenter ces informations aux membres avec des exemples simples. Le contrat sera discuté après cette clarification. Une promesse générale ne leur paraît pas suffisante pour comprendre ce qui sera réellement acheté ni pour comparer honnêtement plusieurs offres. Deux contrats promettent une même quantité annuelle d'électricité renouvelable. L'un compare production et usage heure par heure; l'autre utilise un bilan annuel sans coïncidence temporelle. Le collectif demande que la distinction soit explicitée.","question":"Pourquoi la période de comptage change-t-elle l'interprétation de la garantie ?","explanation":"A sépare le volume annuel annoncé des heures effectives de correspondance. B n'est pas une conséquence tarifaire, C néglige l'origine et D assimile un total annuel à une coïncidence heure par heure."},{"number":27,"points":21,"correct":"D","options":["Un contrôle visuel suffit à garantir la résistance de toute structure déposée.","Les matériaux anciens sont nécessairement plus solides que ceux proposés aujourd'hui.","Le réemploi est valable seulement si le matériau revient exactement au même emplacement.","La résistance réelle de chaque pièce et son adéquation à la structure prévue."],"passage":"Une rénovation conserve les matériaux encore utilisables. L'équipe vérifie leur état et leur compatibilité avant de décider du réemploi. Les matériaux sont inventoriés avant le démontage, puis stockés de façon à éviter leur dégradation. Certains éléments pourront être utilisés directement, d'autres devront être adaptés ou écartés après contrôle. Le chantier documente ces décisions pour conserver la trace de leur origine et de leurs caractéristiques. Deux poutres déposées paraissent intactes. Le contrôle montre que l'une résiste à la nouvelle charge envisagée, mais que l'autre présente une faiblesse interne. Le chantier ne réemploie que l'élément jugé compatible.","question":"Pourquoi conserver la matière ne constitue-t-il pas une raison suffisante pour réutiliser chaque pièce ?","explanation":"Le réemploi est subordonné à une vérification technique de compatibilité. D. B/A/C imposent des règles non soutenues."},{"number":28,"points":21,"correct":"C","options":["Les résidents utilisent plus souvent la salle parce qu'une nouvelle information a renforcé leur intérêt pour les économies possibles.","Les réservations simplifiées expliquent la hausse, plutôt que les horaires.","L'accessibilité de l'usage quotidien conditionne la réalisation des bénéfices attendus.","Le nouvel horaire améliore principalement les performances de la ventilation, ce qui rend le séchage matériellement plus rapide."],"passage":"Un immeuble installe un espace de séchage collectif ventilé. Certains habitants réduisent l'usage d'appareils électriques, mais le service doit rester assez accessible pour être utilisé régulièrement. Le gestionnaire étudie les horaires, les modalités d'accès et la durée nécessaire pour libérer les emplacements. Une salle disponible seulement à des moments peu pratiques serait rapidement délaissée. Les résidents peuvent signaler les difficultés pendant une période d'essai. Les règles seront ajustées avant d'installer davantage de supports. La salle de séchage est peu fréquentée malgré des économies potentielles. Après une extension des horaires et des réservations plus simples, les habitants l'utilisent plus régulièrement sans changer le matériel.","question":"Quel facteur explique l'amélioration obtenue sans nouvel investissement technique ?","explanation":"C relie le changement à l'accès pratique au service, amélioré par les horaires et les réservations. A invente une campagne d'information, B hiérarchise deux facteurs sans preuve, D attribue à la ventilation un changement technique absent."},{"number":29,"points":21,"correct":"D","options":["La baisse d'intensité permet d'affirmer une diminution globale si l'entreprise suit également le volume produit.","L'amélioration de l'efficacité par unité montre que les deux indicateurs évoluent dans le même sens chaque année.","Une moindre consommation par exemplaire signifie que la production totale ne peut pas effacer le gain initial.","La baisse de consommation par unité implique une baisse identique de la consommation totale de l'entreprise."],"passage":"Une entreprise affiche ses économies d'énergie par unité produite. Le volume total de production ayant augmenté, elle publie aussi sa consommation globale. Les deux indicateurs sont présentés sur la même page avec une explication de leur différence. Les responsables souhaitent montrer les progrès réalisés dans les procédés sans donner l'impression que les besoins globaux ont forcément diminué. Le public peut ainsi examiner l'effet des gains techniques et celui de l'activité. La consommation par unité baisse de 15 %, mais l'entreprise produit 30 % d'unités en plus. Son besoin total peut donc augmenter malgré l'efficacité accrue du procédé.","question":"Quelle conclusion serait trompeuse à partir de la seule baisse par unité ?","explanation":"D est la conclusion trompeuse: avec +30 % de production et -15 % par unité, le total peut augmenter. A demande justement le volume, B ignore la divergence possible et C exclut cet effet de volume."},{"number":30,"points":26,"correct":"B","options":["Le tarif d'achat peut expliquer une partie des écarts, même lorsque les réglages et les horaires d'utilisation diffèrent.","Les paramètres d'installation et les pratiques réelles peuvent modifier ce que la machine permet d'obtenir.","La performance annoncée n'est utile qu'en laboratoire, car les conditions d'installation rendent toute comparaison impossible.","Deux appareils identiques doivent donner un rendement comparable dès lors que le modèle et la fiche technique sont les mêmes."],"passage":"Un équipement très performant sur le papier peut donner des résultats décevants s'il est mal réglé ou utilisé dans un lieu inadapté. Une évaluation sérieuse doit donc articuler les caractéristiques techniques, l'installation et les usages. Les techniciens relèvent les températures, les horaires et les paramètres réellement employés. Ils vérifient ensuite si les conditions correspondent à celles retenues dans la documentation commerciale. Un écart peut venir de plusieurs facteurs et nécessite parfois plusieurs essais. Deux machines identiques donnent des résultats différents. Dans l'un des bâtiments, les réglages restent ceux de l'installation par défaut; dans l'autre, les horaires ont été adaptés aux usages. Les techniciens vérifient les conditions avant d'attribuer l'écart à l'équipement.","question":"Pourquoi la fiche de performance ne prédit-elle pas à elle seule le résultat sur place ?","explanation":"B rappelle l'impact des réglages et des horaires sur le fonctionnement réel. A privilégie le prix non discuté, C rend les fiches inutiles à tort et D déduit une performance identique malgré des conditions différentes."},{"number":31,"points":26,"correct":"C","options":["Les travaux ont atteint leur objectif de confort, ce qui rend secondaire la différence entre économies prévues et mesurées.","Les besoins initiaux avaient été sous-estimés, comme le prouve la facture finale.","Une partie du gain énergétique a pu être consacrée au confort, dans le logement rénové.","Le confort accru constitue un bénéfice distinct, mais sa valeur doit être convertie en économies de chauffage pour juger la rénovation."],"passage":"Des travaux réduisent les besoins de chauffage. Les occupants gagnent aussi en confort, parfois en chauffant un peu plus qu'avant. Ce bénéfice ne rend pas les travaux inutiles ; il invite à distinguer économie mesurée et amélioration des conditions de vie. Le suivi demande aux habitants de décrire leurs conditions avant et après l'intervention. Une pièce auparavant évitée en hiver peut désormais être utilisée normalement. Avant rénovation, un foyer chauffait peu une pièce inconfortable. Après travaux, il la maintient à une température agréable; la facture baisse moins que prévu, mais la pièce devient utilisable.","question":"Comment interpréter le résultat si l'économie d'énergie reste inférieure au calcul initial ?","explanation":"C indique qu'une part du gain d'efficacité a pu être utilisée pour chauffer davantage une pièce devenue habitable. A minimise à tort les économies mesurées, B attribue l'écart à une sous-estimation non établie, D impose une conversion énergétique que le suivi ne demande pas."},{"number":32,"points":26,"correct":"A","options":["Des arbres et des sols conçus sans cohérence avec les usages prévus et les besoins de croissance des plantations.","Une conception commune des arbres et des sols assure un résultat même si les fosses restent trop petites pour les racines.","Planter des arbres peut améliorer l'ombre indépendamment de la surface de sol disponible pour leur croissance.","L'observation des lieux fréquentés suffit à établir l'efficacité écologique sans étudier les conditions de développement des arbres."],"passage":"Une ville cherche à rafraîchir une place. Les arbres, l'ombre et les sols perméables demandent une conception commune. Additionner des éléments présentés comme vertueux ne garantit pas leur efficacité si leurs fonctions et leurs conditions d'entretien se contredisent. Un arbre a besoin d'un sol et d'un volume suffisants pour se développer. Une zone ombragée doit aussi correspondre aux endroits où les habitants s'arrêtent. Le projet sera donc examiné comme un ensemble avant le lancement des travaux. Des arbres sont plantés sur une place, mais leurs fosses trop petites empêchent un bon développement. L'ombre prévue ne se forme pas et le sol choisi reste trop imperméable pour leurs besoins.","question":"Quelle erreur de conception explique l'échec malgré l'ajout d'éléments réputés favorables ?","explanation":"A identifie le manque de cohérence entre les arbres, leur espace racinaire et le sol. B et C supposent l'efficacité sans volume adapté; D retient les usages sans les conditions techniques des plantations."},{"number":33,"points":26,"correct":"B","options":["Un système de réservation facile permet de réduire les acquisitions mais rend superflue la maintenance du matériel partagé.","Une réservation simplifiée facilite le partage et évite certains achats individuels qui auraient remplacé un emprunt.","La simplification des créneaux garantit que tous les usagers renonceront aux achats individuels d'équipements.","Un calendrier accessible dispense d'examiner les prêts interrompus ou les motifs de retour du matériel."],"passage":"Le partage d'un équipement réduit parfois les achats individuels. Mais si sa réservation est compliquée, les utilisateurs finissent par acheter leur propre appareil. L'économie de matière dépend donc aussi d'une organisation suffisamment simple pour durer. Les gestionnaires simplifient les créneaux, précisent les conditions de retour et prévoient une réponse en cas de panne. Ils suivent les abandons de réservation pour repérer les obstacles. Une réservation de matériel partagé demande plusieurs confirmations et entraîne des attentes. Une famille achète alors son propre équipement malgré son faible usage; les gestionnaires simplifient le prêt.","question":"Pourquoi l'amélioration du service de réservation peut-elle modifier le bilan matériel du partage ?","explanation":"B relie une réservation praticable au remplacement effectif de certains achats. A omet l'entretien, C garantit un changement universel non démontré, D néglige les abandons à suivre."},{"number":34,"points":26,"correct":"A","options":["Un taux d'aide égal ne signifie pas un reste à charge également accessible.","La valeur de la subvention doit être identique en euros pour produire le même effet.","Le taux de 40 % empêche nécessairement les ménages les plus aisés de rénover.","L'aide devient inutile dès que les conseillers examinent les délais de remboursement."],"passage":"Une aide publique couvre une part du coût des rénovations. Les ménages doivent néanmoins avancer le reste, parfois inaccessible à leur budget. Un taux d'aide identique ne produit donc pas la même possibilité d'agir pour tous. Les conseillers examinent les possibilités d'avance et les délais de versement. Ils observent aussi les dossiers abandonnés, qui n'apparaissent pas dans les chiffres des chantiers terminés. Deux ménages reçoivent une subvention de 40 %. L'un dispose de liquidités pour avancer les 60 % restants; l'autre abandonne le chantier faute de trésorerie en attendant le remboursement.","question":"Quelle limite de l'égalité du pourcentage ressort de cet exemple ?","explanation":"Les contraintes de trésorerie et de reste à charge restent inégales. A; B/C/D ne cadrent pas."},{"number":35,"points":26,"correct":"C","options":["Un calcul de facture directement applicable à toute maison équipée du même type de fenêtre, selon le tarif actuel.","Une comparaison qui révèle les pertes des murs et du toit dès lors que les fenêtres sont testées en laboratoire.","Une comparaison relative à compléter selon les conditions propres au logement, en particulier pour son isolation.","Un diagnostic individuel possible sans relever les usages réels ni l'étanchéité des autres parties du logement."],"passage":"Une démonstration compare deux fenêtres sous des conditions contrôlées. Elle aide à comprendre leurs performances respectives, mais ne permet pas d'annoncer directement l'économie exacte de chaque logement. Celle-ci dépend aussi des murs, des usages et du climat. Le conseiller utilise donc la démonstration comme point de départ pour expliquer les différences techniques. Une estimation individualisée demandera d'autres informations sur le bâtiment. Les résultats présentés au public précisent les conditions dans lesquelles la comparaison a été effectuée. Une fenêtre réduit davantage les pertes de chaleur dans le test, mais une maison possède aussi de grandes fuites d'air au niveau du toit. Le résultat expérimental ne permet pas de prédire seul sa facture après changement.","question":"Quelle portée faut-il attribuer à la comparaison contrôlée de deux fenêtres ?","explanation":"C limite l'essai à une comparaison technique qu'il faut compléter par les caractéristiques du bâtiment. A/D prétendent à un diagnostic individualisé, B attribue à l'essai des fenêtres des mesures sur le reste de la maison."},{"number":36,"points":33,"correct":"D","options":["Le prix d'achat et la garantie permettent d'estimer les ressources de fabrication si l'appareil est utilisé très rarement.","La seule économie électrique suffit à justifier le remplacement lorsque la consommation de l'appareil neuf est divisée par deux.","L'emballage et les consommables représentent l'essentiel des matières nécessaires à produire un nouveau modèle efficace.","Les ressources de fabrication et l'utilisation effective, en tenant compte du maintien possible de l'ancien équipement."],"passage":"Une campagne encourage à remplacer les appareils anciens par des modèles efficaces. Pour un équipement encore peu utilisé, l'énergie et les matériaux nécessaires à la fabrication du nouveau peuvent peser dans le bilan. La décision doit donc considérer le cycle de vie et l'usage, plutôt qu'une comparaison limitée au fonctionnement instantané. Le conseiller propose de comparer plusieurs scénarios : continuer à utiliser l'appareil, le réparer si nécessaire ou le remplacer. Il demande combien de fois il fonctionne et pendant combien de temps. La disponibilité des pièces, les consommables et les possibilités de fin de vie entrent aussi dans l'examen. Un modèle récent peut être intéressant dans certaines situations, sans que le même choix soit préférable pour tous les ménages. Présenter ces conditions aide à décider à partir des besoins réels et des ressources engagées, au lieu de déduire automatiquement la meilleure solution de l'âge inscrit sur l'étiquette. Un appareil neuf consomme moitié moins d'électricité, mais sa fabrication exige des matériaux importants. Dans un ménage qui utilise l'ancien très rarement, le remplacement immédiat pourrait ne pas compenser ces ressources avant longtemps.","question":"Quel bilan manque à la comparaison limitée à l'électricité en fonctionnement ?","explanation":"D impose un bilan des matériaux de fabrication et de l'usage prévu, avec maintien ou réparation possibles. A déduit les ressources du prix, B ignore la fabrication et C réduit abusivement les matériaux à des accessoires."},{"number":37,"points":33,"correct":"D","options":["Le modèle installé était techniquement efficace mais les économies restaient indépendantes des réglages réellement choisis.","Les utilisateurs connaissaient les commandes courantes mais préféraient des réglages professionnels plus avancés.","La rénovation a supprimé une procédure de secours qui expliquait l'essentiel des économies annoncées.","Le potentiel technique reste peu utilisé lorsque les commandes sont difficiles à comprendre."],"passage":"Un immeuble rénové reçoit un système de commande complexe. Les occupants évitent certains réglages par peur de faire une erreur. L'équipe simplifie l'interface et organise un accompagnement. Une performance théorique ne devient réelle que si les personnes peuvent effectivement piloter les usages attendus. Les premières réunions avaient surtout présenté les capacités techniques du dispositif. Elles n'avaient pas montré les gestes ordinaires, comme modifier un horaire ou revenir à un réglage connu. Des essais avec les habitants révèlent des libellés difficiles à comprendre et des confirmations peu visibles. La nouvelle version distingue les actions courantes des paramètres réservés aux professionnels. Un guide court reste disponible près de la commande et un contact est prévu pour les questions. Les habitants pourront revenir poser leurs questions. Les nouveaux thermostats offrent une programmation fine, mais des résidents craignent de modifier les réglages. Après des essais accompagnés et une interface plus simple, ils utilisent les fonctions prévues sans changer la machine.","question":"Quel décalage explique les performances initialement décevantes ?","explanation":"D décrit l'écart entre potentiel théorique et utilisation effective dû aux commandes difficiles. A nie l'effet du réglage, B inverse les difficultés des utilisateurs, C invente une suppression de secours non évoquée."},{"number":38,"points":33,"correct":"D","options":["La baisse brute correspond au progrès énergétique à service comparable tant que les équipements utilisent les mêmes technologies.","Les deux séries doivent être identiques si les bâtiments encore ouverts conservent leurs surfaces et leurs horaires.","L'effet des fermetures doit être retiré du bilan financier plutôt que présenté comme une baisse réelle des dépenses.","Le total enregistré et l'efficacité à activité constante répondent à des questions distinctes sur le service fourni."],"passage":"Une ville annonce une baisse de consommation dans ses bâtiments. Plusieurs équipements ont pourtant été fermés pendant la période observée. Les responsables recalculent les résultats à usage comparable. Un chiffre peut être exact tout en donnant une interprétation trompeuse s'il ne précise pas ce qui a changé autour de la mesure. Une piscine fermée pour entretien et une salle inutilisée pendant plusieurs mois expliquent une partie de la différence annoncée. Ces fermetures ont bien réduit les dépenses, mais ne démontrent pas à elles seules une meilleure efficacité des installations. Le nouveau bilan sépare donc l'évolution liée aux surfaces et aux horaires de celle observée dans les équipements restés ouverts. Il conserve le chiffre initial en précisant sa signification. Les élus pourront ainsi discuter des économies techniques sur une base comparable, tandis que les habitants disposeront d'une présentation plus claire des services effectivement assurés pendant chacune des périodes étudiées. La consommation totale baisse de 20 %, mais un gymnase reste fermé toute la saison. Le recalcul à surfaces et horaires comparables montre une économie technique plus modeste.","question":"Pourquoi conserver le chiffre brut tout en présentant une seconde comparaison ?","explanation":"D distingue la consommation réellement facturée de l'efficacité à surfaces et horaires comparables. A ignore la fermeture, B exige une convergence inexistante et C écarte un effet budgétaire réel."},{"number":39,"points":33,"correct":"A","options":["La possibilité effective pour les habitants d'influer sur l'affectation des recettes et les règles de décision, en tenant compte des obstacles à leur représentation.","La proximité des installations, qui rend la gouvernance citoyenne dès lors que les résidents connaissent les investisseurs porteurs du projet.","Le nombre de réunions tenues et la présence régulière d'un public nombreux, considérés comme des preuves suffisantes de participation même lorsqu'un petit groupe d'investisseurs conserve le veto sur les décisions financières essentielles.","La part du capital détenue par chaque membre, utilisée comme mesure unique de représentation sans examen des droits de vote."],"passage":"Un projet collectif veut produire de l'énergie près des habitants. Il organise aussi les décisions sur l'investissement et la répartition des bénéfices. Les initiateurs refusent de définir le caractère citoyen du projet par sa seule localisation. La proximité physique ne remplace pas une participation réelle aux choix qui structurent le service. Les réunions abordent notamment l'entrée de nouveaux membres, les droits de vote et l'utilisation des recettes. Les documents financiers sont présentés dans un langage accessible, avec un temps pour poser des questions avant chaque décision. Les fondateurs veulent aussi éviter que seules les personnes ayant beaucoup de temps ou de capital puissent peser sur les orientations. Ils prévoient donc plusieurs formes de contribution et des modalités de représentation. Le projet sera évalué sur la production réalisée, mais également sur la manière dont les habitants peuvent comprendre, discuter et modifier les choix qui engagent leur participation dans la durée. Le projet installe des panneaux sur un terrain proche, mais le conseil définit aussi comment les riverains votent sur l'investissement et l'usage des recettes. Le comité refuse que la seule distance aux habitations suffise à l'appellation citoyenne. Lors d'une assemblée, deux propositions reçoivent un soutien populaire comparable. L'une concerne le tarif de revente; l'autre, l'affectation des bénéfices à un fonds d'aide pour les ménages modestes. Les statuts donnent cependant un droit de veto à trois investisseurs qui détiennent la majorité du capital, même lorsque les autres membres sont plus nombreux. Les fondateurs affichent une forte participation aux réunions, mais constatent que les habitants n'ont pas pu modifier l'affectation des recettes. Ils étudient une réforme distinguant apport financier et capacité de décision, avec des règles d'information préalable et un vote sur les usages des bénéfices. L'association locale précise qu'aucune répartition des voix ne supprimera à elle seule les inégalités de disponibilité pour participer; elle souhaite donc également des mandats de représentation et des comptes rendus accessibles.","question":"Quel critère permettrait de vérifier que la participation dépasse la simple présence aux réunions ?","explanation":"A retient un pouvoir réel sur les décisions financières et les mécanismes de représentation, au-delà de la présence aux assemblées. B substitue proximité à gouvernance; C ne considère pas le veto qui neutralise la participation; D confond apport capitalistique et capacité démocratique effectivement exercée."}]}$paper_19$::jsonb),
('tcf-reading-20','tcf-reading-2026-11-distractor-polish-v5',$paper_20${"id":"tcf-reading-20","title":"TCF Reading · Test 20","seconds":3600,"version":"tcf-reading-2026-11-distractor-polish-v5","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"A","options":["Le début des nouvelles parties après seize heures","L'arrivée de tous les visiteurs après quatorze heures","La présence des animateurs","La possibilité de jouer avant seize heures"],"passage":"L'atelier de jeux commence à quatorze heures. Vous pouvez arriver plus tard, mais aucune nouvelle partie ne sera lancée après seize heures.\n\nL'accueil vous indiquera les tables encore disponibles. Les parties déjà commencées pourront se terminer normalement après cette heure.","question":"Quelle limite est annoncée ?","explanation":"Le passage indique : « L'atelier de jeux commence à quatorze heures. Vous pouvez arriver plus tard, mais aucune nouvelle partie ne sera lancée après seize heures. » Cela justifie la réponse : Le début des nouvelles parties après seize heures."},{"number":2,"points":3,"correct":"A","options":["La zone balisée du chantier","Tout le parc","Le jardin voisin","Toutes les allées"],"passage":"Le parc reste ouvert pendant les travaux du kiosque. Seule la zone entourée de barrières est inaccessible.\n\nLes autres allées restent accessibles. Merci de suivre les panneaux temporaires pour rejoindre l'aire de jeux.","question":"Quel espace est fermé ?","explanation":"Le passage indique : « Le parc reste ouvert pendant les travaux du kiosque. Seule la zone entourée de barrières est inaccessible. » Cela justifie la réponse : La zone balisée du chantier."},{"number":3,"points":3,"correct":"B","options":["Acheter le matériel","S'inscrire","Venir chercher son certificat","Payer immédiatement"],"passage":"Les inscriptions au stage ferment demain. Le paiement peut être effectué la semaine suivante.\n\nRemplissez le formulaire en ligne pour réserver votre place. Vous recevrez ensuite les indications nécessaires pour régler les frais.","question":"Quelle démarche est urgente ?","explanation":"Le passage indique : « Les inscriptions au stage ferment demain. Le paiement peut être effectué la semaine suivante. » Cela justifie la réponse : S'inscrire."},{"number":4,"points":3,"correct":"A","options":["Le lieu de rassemblement","La durée de la promenade","Le jour choisi","L'heure du départ"],"passage":"Le rendez-vous de la promenade passe de la mairie à la gare. Le départ reste prévu à dix heures.\n\nLe groupe vous attendra devant l'entrée principale. Merci de transmettre ce changement aux personnes qui viennent avec vous.","question":"Qu'est-ce qui change ?","explanation":"Le passage indique : « Le rendez-vous de la promenade passe de la mairie à la gare. Le départ reste prévu à dix heures. » Cela justifie la réponse : Le lieu de rassemblement."},{"number":5,"points":9,"correct":"B","options":["Prolonger le trajet","Préserver un temps de récupération","Ajouter une visite obligatoire","Organiser une compétition"],"passage":"Je préfère réserver une soirée sans programme après notre voyage. Nous aurons besoin de temps pour nous reposer et ranger les affaires.\n\nOn pourra faire les courses le lendemain matin. Préviens simplement nos amis que nous préférons les retrouver un autre jour de la semaine.","question":"Quelle intention est exprimée ?","explanation":"Le passage indique : « Je préfère réserver une soirée sans programme après notre voyage. Nous aurons besoin de temps pour nous reposer et ranger les affaires. » Cela justifie la réponse : Préserver un temps de récupération."},{"number":6,"points":9,"correct":"D","options":["Une personne ayant déjà terminé","Seulement un vendeur d'outils","Uniquement un professionnel","Une personne avec un projet modeste"],"passage":"Notre atelier fournit les outils de base. Vous pouvez apporter votre projet inachevé, même s'il est très simple.\n\nUn animateur vous aidera à choisir la prochaine étape. Pensez à apporter les pièces déjà réalisées.","question":"Qui est accueilli ?","explanation":"Le passage indique : « Notre atelier fournit les outils de base. Vous pouvez apporter votre projet inachevé, même s'il est très simple. » Cela justifie la réponse : Une personne avec un projet modeste."},{"number":7,"points":9,"correct":"D","options":["Éviter tout échange","Choisir uniquement selon le poids","Vendre tous les ouvrages","Découvrir les livres par la discussion"],"passage":"Je te propose d'échanger nos livres au café. Nous pourrons en parler avant de choisir ceux que nous emporterons.\n\nJ'apporterai les deux romans dont je t'ai parlé et tu pourras les feuilleter tranquillement. Dis-moi quel jour te conviendrait pour nous retrouver la semaine prochaine.","question":"Quel intérêt présente la rencontre ?","explanation":"Le passage indique : « Je te propose d'échanger nos livres au café. Nous pourrons en parler avant de choisir ceux que nous emporterons. » Cela justifie la réponse : Découvrir les livres par la discussion."},{"number":8,"points":9,"correct":"B","options":["Une présence quotidienne obligatoire","Une fréquentation occasionnelle","Une activité réservée aux abonnés","Un accès sans horaire"],"passage":"Le centre propose des entrées sans abonnement pour les personnes qui viennent rarement. Le tarif à la séance reste distinct du forfait.\n\nLes prix sont affichés à l'accueil. Demandez conseil avant de choisir votre formule pour le trimestre.","question":"À quel besoin répond cette formule ?","explanation":"Le passage indique : « Le centre propose des entrées sans abonnement pour les personnes qui viennent rarement. Le tarif à la séance reste distinct du forfait. » Cela justifie la réponse : Une fréquentation occasionnelle."},{"number":9,"points":9,"correct":"B","options":["Parce que la salle a été vendue","Pour permettre davantage de participation","Parce que le rangement est terminé","Pour supprimer toute consultation"],"passage":"Nous reportons le rangement collectif : trop de voisins sont absents dimanche. Une nouvelle date sera choisie par sondage.\n\nChacun pourra indiquer plusieurs disponibilités. Nous confirmerons ensuite le créneau retenu et la liste du matériel à apporter.","question":"Pourquoi le rendez-vous est-il reporté ?","explanation":"Le passage indique : « Nous reportons le rangement collectif : trop de voisins sont absents dimanche. Une nouvelle date sera choisie par sondage. » Cela justifie la réponse : Pour permettre davantage de participation."},{"number":10,"points":9,"correct":"A","options":["Laisser du temps sans objectif productif","Transformer chaque pause en tâche","Renoncer à tout repos","Organiser toutes les journées de la même façon"],"passage":"Je ne veux pas remplir toutes mes pauses avec des activités utiles. Certaines resteront simplement des moments de repos.\n\nJe me sens mieux lorsque je peux parfois marcher sans objectif ou regarder par la fenêtre. Cela m'aide à reprendre ensuite mes tâches.","question":"Quel choix est défendu ?","explanation":"Le passage indique : « Je ne veux pas remplir toutes mes pauses avec des activités utiles. Certaines resteront simplement des moments de repos. » Cela justifie la réponse : Laisser du temps sans objectif productif."},{"number":11,"points":15,"correct":"A","options":["Définir la fonction du meuble","Acheter un meuble neuf","Vendre immédiatement les outils","Choisir une couleur au hasard"],"passage":"Un atelier transforme des meubles récupérés. Les participants décident d'abord de l'usage recherché avant de choisir la décoration.\n\nUne petite armoire pourra par exemple devenir un rangement pour les chaussures ou un support pour des plantes. Les dimensions et la solidité sont vérifiées avant de commencer. Les animateurs montrent comment démonter une pièce et préparer les surfaces sans abîmer le reste du meuble. La couleur est discutée ensuite, en fonction du lieu où l'objet sera installé. Les participants repartent avec une fiche des gestes réalisés pour pouvoir entretenir leur réalisation. Le projet associe ainsi choix pratique, apprentissage technique et transformation esthétique.","question":"Quelle étape est prioritaire ?","explanation":"Le passage indique : « Un atelier transforme des meubles récupérés. Les participants décident d'abord de l'usage recherché avant de choisir la décoration. » Cela justifie la réponse : Définir la fonction du meuble."},{"number":12,"points":15,"correct":"C","options":["Venir uniquement regarder","S'inscrire dans une autre ville","Emprunter les pièces","Acheter une table"],"passage":"Une ville installe des tables d'échecs dans un parc. Les habitants peuvent apporter leurs pièces ; un prêt est aussi proposé à l'accueil voisin.\n\nLes tables sont accessibles sans réservation aux heures d'ouverture du parc. Un panneau explique comment emprunter le matériel et où le rapporter après la partie. Des bénévoles proposent parfois une initiation aux débutants. Les dates seront affichées sur le panneau près des tables.","question":"Quelle solution évite d'avoir son propre matériel ?","explanation":"Le passage indique : « Une ville installe des tables d'échecs dans un parc. Les habitants peuvent apporter leurs pièces ; un prêt est aussi proposé à l'accueil voisin. » Cela justifie la réponse : Emprunter les pièces."},{"number":13,"points":15,"correct":"B","options":["Le déplacement le plus rapide","L'attention au quotidien proche","La recherche exclusive de records","L'évitement de toute observation"],"passage":"Un groupe propose des promenades sans destination spectaculaire. Les participants découvrent les détails des rues ordinaires à un rythme lent.\n\nLe guide invite le groupe à observer une façade, une plante entre les pavés ou les sons d'une place. Les arrêts sont choisis selon ce qui attire l'attention pendant la marche. Aucune liste de monuments à voir absolument n'est distribuée au départ. Les participants peuvent partager un souvenir lié au quartier ou demander de revenir sur un détail. La promenade propose ainsi une autre façon de regarder un environnement familier, sans exiger un long déplacement ni la recherche d'un événement exceptionnel à chaque étape.","question":"Quel regard est encouragé ?","explanation":"Le passage indique : « Un groupe propose des promenades sans destination spectaculaire. Les participants découvrent les détails des rues ordinaires à un rythme lent. » Cela justifie la réponse : L'attention au quotidien proche."},{"number":14,"points":15,"correct":"B","options":["Supprimer les livres de loisir","Accueillir différents usages du lieu","Réserver tout le bâtiment aux candidats","Fermer pendant les examens"],"passage":"Une bibliothèque élargit ses horaires pendant les examens. Elle réserve cependant des espaces aux lecteurs qui ne préparent pas d'épreuve.\n\nLes étudiants disposent de davantage de tables pour réviser, mais le prêt, la lecture sur place et les visites habituelles continuent. Des panneaux distinguent les zones silencieuses des espaces où l'on peut discuter doucement. L'équipe observe les besoins à différents moments de la journée pour ajuster l'organisation. Elle souhaite répondre à l'affluence particulière de la période sans laisser penser que les autres usages doivent disparaître.","question":"Quel équilibre est recherché ?","explanation":"Le passage indique : « Une bibliothèque élargit ses horaires pendant les examens. Elle réserve cependant des espaces aux lecteurs qui ne préparent pas d'épreuve. » Cela justifie la réponse : Accueillir différents usages du lieu."},{"number":15,"points":15,"correct":"B","options":["Une réalisation automatique de chaque idée","Sa faisabilité dans le cadre du centre","L'absence de toute discussion","Le choix exclusif des adultes sans consultation"],"passage":"Un centre de loisirs demande aux adolescents de proposer les activités. L'équipe vérifie ensuite les moyens nécessaires et les règles de sécurité.\n\nLes jeunes commencent par présenter ce qu'ils aimeraient découvrir et la manière dont ils souhaitent participer. Les animateurs les aident à estimer le budget, le temps de préparation et les besoins d'encadrement. Une proposition trop ambitieuse peut être adaptée plutôt que rejetée sans discussion. Le programme final indiquera ce qui a été retenu et les raisons des principaux choix. Cette étape doit permettre aux adolescents de voir les conséquences concrètes de leur contribution, tout en comprenant les responsabilités qui accompagnent l'organisation d'une activité collective.","question":"Quelle limite encadre la proposition ?","explanation":"Le passage indique : « Un centre de loisirs demande aux adolescents de proposer les activités. L'équipe vérifie ensuite les moyens nécessaires et les règles de sécurité. » Cela justifie la réponse : Sa faisabilité dans le cadre du centre."},{"number":16,"points":15,"correct":"D","options":["Éviter toute évaluation","Augmenter artificiellement le nombre de réunions","Mesurer uniquement la taille des salles","Vérifier si le travail a simplement été déplacé"],"passage":"Une entreprise expérimente une semaine de réunions plus courtes. Elle recueille ensuite les tâches reportées en dehors des réunions pour évaluer le résultat réel.\n\nCertains échanges supprimés de l'ordre du jour peuvent en effet réapparaître dans des messages individuels ou dans des discussions tardives. Les salariés notent ces déplacements pendant la période d'essai. L'équipe compare le temps total consacré à la coordination et la qualité des décisions obtenues. Elle cherche une organisation plus utile, sans considérer la seule durée inscrite au calendrier comme une preuve suffisante d'amélioration.","question":"Pourquoi regarder aussi ces tâches ?","explanation":"Le passage indique : « Une entreprise expérimente une semaine de réunions plus courtes. Elle recueille ensuite les tâches reportées en dehors des réunions pour évaluer le résultat réel. » Cela justifie la réponse : Vérifier si le travail a simplement été déplacé."},{"number":17,"points":15,"correct":"C","options":["Encourager à venir malgré l'annulation","Remplacer les dates par des photos","Informer ceux qui avaient vu la première annonce","Masquer les changements"],"passage":"Des habitants partagent un agenda de quartier. Les événements annulés y restent visibles avec une mention claire, pour éviter les déplacements inutiles.\n\nUne couleur et une date de modification permettent de distinguer une annulation d'un événement encore confirmé. Les habitants peuvent consulter l'agenda sur leur téléphone ou sur un affichage à l'accueil du centre. L'équipe vérifie régulièrement les informations les plus proches, car une fiche oubliée peut rester visible longtemps. Le service vise à faciliter la participation en donnant des renseignements fiables, y compris lorsqu'une activité ne pourra finalement pas avoir lieu.","question":"Pourquoi conserver cette trace ?","explanation":"Le passage indique : « Des habitants partagent un agenda de quartier. Les événements annulés y restent visibles avec une mention claire, pour éviter les déplacements inutiles. » Cela justifie la réponse : Informer ceux qui avaient vu la première annonce."},{"number":18,"points":15,"correct":"D","options":["Remplacer systématiquement chaque vêtement","Réparer tout objet sans exception","Éviter d'observer la matière","Reconnaître les limites d'une réparation"],"passage":"Un atelier de couture accueille les réparations courantes. Les animateurs conseillent aussi de renoncer lorsque le tissu est trop fragile pour supporter une nouvelle intervention.\n\nLes participants apportent leurs vêtements et expliquent l'usage qu'ils souhaitent en faire. L'équipe examine les coutures et la matière avant de proposer une technique. Une petite reprise peut suffire dans certains cas, tandis qu'une zone très usée risquerait de se déchirer juste à côté de la réparation. Les animateurs montrent comment reconnaître ces limites et envisager d'autres usages du tissu.","question":"Quelle compétence est également transmise ?","explanation":"Le passage indique : « Un atelier de couture accueille les réparations courantes. Les animateurs conseillent aussi de renoncer lorsque le tissu est trop fragile pour supporter une nouvelle intervention. » Cela justifie la réponse : Reconnaître les limites d'une réparation."},{"number":19,"points":15,"correct":"D","options":["Supprimer toute règle","Désigner un perdant obligatoire","Récompenser uniquement le plus rapide","Réussir ensemble"],"passage":"Une association propose des jeux coopératifs. Les participants cherchent une solution commune plutôt que l'élimination des autres.\n\nLes animateurs choisissent des règles où les informations et les ressources doivent être partagées. Certains groupes découvrent qu'une personne a organisé toutes les actions sans vraiment écouter les autres. La séance suivante peut alors modifier la répartition des rôles. Réussir ensemble ne signifie donc pas seulement atteindre un résultat, mais aussi apprendre comment chacun trouve sa place dans la recherche commune.","question":"Quel objectif organise le jeu ?","explanation":"Le passage indique : « Une association propose des jeux coopératifs. Les participants cherchent une solution commune plutôt que l'élimination des autres. » Cela justifie la réponse : Réussir ensemble."},{"number":20,"points":21,"correct":"D","options":["Tout temps d'attente est totalement libre","Tous les loisirs demandent le même temps","Les responsabilités disparaissent hors du bureau","L'absence de travail visible ne signifie pas une liberté complète"],"passage":"Une enquête sur les loisirs distingue le temps libre apparent et le temps réellement disponible. Attendre un proche tout en restant responsable de son retour n'offre pas les mêmes possibilités qu'une période sans contrainte. Les chercheurs demandent ce que les personnes peuvent faire pendant ces périodes et si elles doivent pouvoir s'interrompre immédiatement. Une heure passée à attendre près d'un établissement ne permet pas toujours de rejoindre une activité éloignée. Le rapport distingue donc les durées sur le calendrier et les possibilités concrètes d'en disposer, pour éviter de présenter comme équivalentes des situations très différentes.","question":"Quelle distinction est faite ?","explanation":"Le passage indique : « Une enquête sur les loisirs distingue le temps libre apparent et le temps réellement disponible. Attendre un proche tout en restant responsable de son retour n'offre pas les mêmes possibilités qu'une période sans contrainte. » Cela justifie la réponse : L'absence de travail visible ne signifie pas une liberté complète."},{"number":21,"points":21,"correct":"D","options":["La valeur de tous les équipements","Le programme de l'année suivante seulement","Le résultat garanti du trimestre","La manière de vivre l'activité dans le groupe"],"passage":"Un centre autorise les participants à assister à une séance avant de s'engager pour un trimestre. L'essai aide à apprécier l'ambiance autant que le contenu. La personne peut observer les échanges, essayer le matériel et poser des questions à l'animateur. Aucune décision immédiate n'est demandée à la sortie. Le centre présente également les horaires, les frais et les conditions d'absence afin que l'engagement soit bien compris. Les retours des visiteurs serviront à améliorer l'accueil.","question":"Quel aspect peut être évalué avant l'inscription ?","explanation":"Le passage indique : « Un centre autorise les participants à assister à une séance avant de s'engager pour un trimestre. L'essai aide à apprécier l'ambiance autant que le contenu. » Cela justifie la réponse : La manière de vivre l'activité dans le groupe."},{"number":22,"points":21,"correct":"C","options":["Remplacer la rue chaque semaine","Garantir un projet définitif sans essai","Permettre une expérimentation réversible","Interdire toute participation"],"passage":"Un quartier transforme une rue en espace de jeux quelques dimanches. Les aménagements restent démontables pour observer l'usage avant une décision plus durable. Les équipes relèvent les moments de forte présence et les difficultés signalées par les riverains. Elles observent aussi si des enfants de différents âges peuvent trouver leur place. Les barrières et les tables seront retirées après chaque journée. Le bilan permettra de discuter d'une éventuelle installation permanente avec davantage d'informations.","question":"Pourquoi choisir du matériel démontable ?","explanation":"Le passage indique : « Un quartier transforme une rue en espace de jeux quelques dimanches. Les aménagements restent démontables pour observer l'usage avant une décision plus durable. » Cela justifie la réponse : Permettre une expérimentation réversible."},{"number":23,"points":21,"correct":"A","options":["Mieux distinguer accès à l'information et interruption","Imposer une réaction immédiate à chacun","Rendre les informations confidentielles","Supprimer tous les messages"],"passage":"Une équipe supprime les alertes non urgentes sur son outil commun. Les informations restent consultables, mais n'interrompent plus automatiquement chaque personne. Les messages nécessitant une réponse rapide gardent un canal identifié. Pour les autres, les membres consultent les nouvelles à des moments choisis dans la journée. Une période d'essai permettra de vérifier qu'aucune information importante n'est perdue. Les responsables souhaitent réduire les interruptions sans empêcher la coordination. Ils expliquent donc les nouvelles règles et les situations dans lesquelles une alerte reste nécessaire.","question":"Quel changement est recherché ?","explanation":"Le passage indique : « Une équipe supprime les alertes non urgentes sur son outil commun. Les informations restent consultables, mais n'interrompent plus automatiquement chaque personne. » Cela justifie la réponse : Mieux distinguer accès à l'information et interruption."},{"number":24,"points":21,"correct":"B","options":["La suppression des rencontres libres","Un accueil sans programme imposé","Une obligation permanente d'apprendre","Un accès réservé aux animateurs"],"passage":"Un lieu associatif ouvre des plages sans activité organisée. Les habitants peuvent s'y rencontrer sans devoir participer à un atelier. Des sièges, de l'eau et quelques documents sont disponibles, mais aucune production n'est attendue. Une personne de l'équipe accueille les nouveaux visiteurs et explique les règles du lieu. Certains viennent discuter quelques minutes, d'autres lisent ou attendent un voisin. Les responsables veulent conserver ces usages simples dans le programme, car toutes les rencontres ne commencent pas par une inscription à une activité précise.","question":"Quel besoin est reconnu ?","explanation":"Le passage indique : « Un lieu associatif ouvre des plages sans activité organisée. Les habitants peuvent s'y rencontrer sans devoir participer à un atelier. » Cela justifie la réponse : Un accueil sans programme imposé."},{"number":25,"points":21,"correct":"A","options":["Comparer l'état consigné au départ avec celui du retour afin de distinguer les pertes réellement récentes.","La fiche dispense de recompter les pièces au retour lorsque l'absence initiale avait été clairement notée.","Le relevé initial garantit que chaque carte manquante pourra être retrouvée avant la prochaine réservation.","La fiche sert avant tout à calculer la capacité du jeu à accueillir des joueurs lorsque des cartes ont disparu."],"passage":"Des bénévoles gèrent une collection de jeux. Ils notent les pièces manquantes avant le prêt, afin de distinguer un état ancien d'une perte récente. La fiche accompagne la boîte et peut être complétée au retour. Une pièce déjà absente est signalée clairement afin que le prochain emprunteur sache si le jeu reste utilisable. L'équipe peut ainsi rechercher une solution de remplacement sans attribuer automatiquement le problème au dernier utilisateur. Une boîte revient avec une carte en moins; la fiche du départ indiquait déjà cette absence. L'équipe distingue ainsi un défaut connu d'une nouvelle perte et propose un remplacement sans accuser à tort l'emprunteur.","question":"Quelle information la fiche de prêt rend-elle possible lors du retour ?","explanation":"A autorise une comparaison de l'état au départ et au retour; l'absence connue n'est pas attribuée à tort au dernier emprunteur. B supprime une vérification, C promet de retrouver la pièce, D détourne la fiche de sa fonction."},{"number":26,"points":21,"correct":"C","options":["Les ateliers sont gratuits uniquement si le participant devient client du magasin.","Tout produit apporté peut être remplacé gratuitement pour éviter un nouvel achat.","L'atelier est gratuit sans achat, mais seulement pour les modèles effectivement admis.","Les modèles concernés sont décidés après la réparation pour adapter la publicité."],"passage":"Un magasin organise des ateliers de réparation gratuits. Il précise quels produits sont concernés et ne conditionne pas l'accès à un nouvel achat. Les participants peuvent vérifier leur modèle avant de se déplacer grâce à une liste disponible à l'accueil. Les animateurs précisent aussi les opérations qu'ils ne peuvent pas réaliser sur place. Le magasin espère faire connaître son service, mais les places ne sont pas réservées aux clients qui commandent un autre produit. Une cliente vient faire réparer un appareil éligible sans acheter de nouvel article. Une autre, dont le modèle n'est pas pris en charge, reçoit une explication avant de réserver sa place.","question":"Quelle différence le magasin distingue-t-il dans les conditions de participation ?","explanation":"L'atelier est sans achat obligatoire mais limité à certains modèles et opérations. C; B/A/D confondent ces conditions."},{"number":27,"points":21,"correct":"A","options":["La surestimation d'usages visibles uniquement à une heure au détriment de ceux pratiqués à d'autres moments.","Une consultation du samedi peut équilibrer celle du mardi si chaque catégorie d'usagers reçoit un poids identique.","Le nombre d'entretiens devrait rester stable d'un créneau à l'autre afin de rendre les avis directement représentatifs.","Exclure les réponses écrites pour mieux interpréter les entretiens réalisés aux différents horaires."],"passage":"Une commune consulte les usagers d'un parc en semaine et le week-end. Les profils présents diffèrent selon les horaires. Des retraités, des salariés et des familles ne fréquentent pas nécessairement les mêmes zones au même moment. Les enquêteurs varient donc les jours et les points de rencontre. Le projet d'aménagement s'appuiera sur ces observations et sur les contributions écrites, plutôt que sur un seul après-midi de consultation. Une enquête menée le mardi matin recueille surtout les avis des retraités. Le samedi, des salariés et des familles signalent d'autres usages du même parc. La commune maintient les deux sessions.","question":"Quel biais la diversité des créneaux cherche-t-elle à réduire ?","explanation":"A corrige la surreprésentation des personnes présentes le mardi matin. B propose une pondération sans fondement, C assimile quotas horaires et représentativité, D rejette des contributions complémentaires prévues."},{"number":28,"points":21,"correct":"C","options":["Elle garantit seulement la disponibilité d'un bus à n'importe quelle heure de la journée.","Elle ne sert qu'aux personnes qui possèdent déjà leur propre véhicule.","Les possibilités de retour et leurs horaires font partie du trajet réellement praticable.","Elle ne renseigne pas sur la difficulté des jeux pratiqués pendant l'activité."],"passage":"Un club propose des sorties courtes proches des transports. Les nouveaux participants peuvent rejoindre facilement l'activité sans posséder de voiture. Le descriptif indique la distance à parcourir depuis l'arrêt et les horaires possibles pour le retour. Un contact est prévu en cas de changement. Le club souhaite ainsi que la facilité annoncée soit réelle pendant tout le trajet, pas seulement entre le point de départ de la marche et son arrivée. Une sortie commence à proximité d'un bus, mais le dernier départ est avancé le week-end. Le club vérifie désormais l'horaire du retour avant de présenter l'activité comme accessible sans voiture.","question":"Pourquoi la proximité d'un arrêt au départ ne suffit-elle pas à garantir l'accessibilité ?","explanation":"Le retour doit aussi être possible. C. D/A/B sont des conclusions erronées."},{"number":29,"points":21,"correct":"A","options":["Expliquer les gestes pour sécuriser l'usage et le retour du matériel.","Il transfère au bénévole toutes les opérations futures de l'emprunteur.","Il supprime la nécessité de vérifier l'appareil lorsque son prêt a été expliqué.","Il permet de limiter les prêts aux personnes déjà expertes, indépendamment de leur besoin."],"passage":"Une bibliothèque d'objets prépare des fiches simples. Un prêt devient plus utile lorsque les personnes savent installer, utiliser et rapporter correctement l'équipement. Les bénévoles montrent les gestes essentiels lors de la première remise du matériel. Les fiches rappellent les vérifications et les situations où il faut demander de l'aide. Les emprunteurs peuvent signaler une consigne difficile à comprendre pour qu'elle soit reformulée. Une perceuse partagée revient endommagée après une mauvaise installation. L'association ajoute un bref essai pratique et un guide de retour, puis vérifie que les consignes sont comprises.","question":"Quel rôle l'accompagnement ajoute-t-il à la simple disponibilité de l'objet ?","explanation":"Le prêt efficace demande connaissance des gestes et du retour. A; D/B/C ignorent la progression vers l'autonomie."},{"number":30,"points":26,"correct":"D","options":["Le choix d'un loisir local doit toujours être expliqué principalement par sa facilité d'accès plutôt que par le goût.","Une activité désirée dans d'autres conditions devient nécessairement la préférence réelle même si la personne apprécie le choix local.","L'enquêteur devrait classer les horaires et les coûts comme causes suffisantes sans examiner les préférences des participants.","Assimiler l'activité choisie parce qu'elle est accessible à la préférence personnelle réellement souhaitée par les personnes inscrites."],"passage":"Les loisirs sont parfois décrits comme un choix purement personnel. Les horaires, l'offre locale, le coût et les responsabilités familiales orientent pourtant les possibilités. Étudier les goûts sans regarder ces conditions risque de confondre préférence et adaptation à des contraintes. Une personne qui choisit une activité proche peut en apprécier le contenu tout en ayant renoncé à d'autres possibilités trop coûteuses ou éloignées. Les entretiens demandent donc aussi quelles propositions auraient intéressé les participants dans d'autres conditions. Deux personnes choisissent une activité locale. L'une la préfère à toute autre; l'autre aurait souhaité un sport plus éloigné mais n'a pas de voiture. Le choix observé ne révèle pas à lui seul la préférence initiale.","question":"Quelle erreur ferait l'enquêteur en interprétant les deux inscriptions comme un goût identique ?","explanation":"D est erroné: deux inscriptions identiques peuvent refléter une préférence ou un renoncement lié au transport. A inverse simplement la priorité, B déduit une préférence exclusive et C ignore les goûts effectivement déclarés."},{"number":31,"points":26,"correct":"A","options":["Il ne mesure pas le temps supplémentaire de préparation, d'apprentissage et de correction.","Le gain annoncé dépend surtout de la formation préalable des utilisateurs, avant même qu'ils commencent à préparer leurs données.","Le temps de préparation hebdomadaire peut être exclu du calcul quotidien.","La complexité des dossiers explique la variation de durée, tandis que les corrections seraient déjà incluses dans la promesse initiale."],"passage":"Un service promet de faire gagner du temps. Il demande toutefois à l'utilisateur de saisir régulièrement des données et de corriger les erreurs. Le gain doit être évalué sur l'ensemble des tâches, pas seulement sur celle que le service accomplit automatiquement. L'évaluation note aussi le temps nécessaire pour apprendre le fonctionnement et vérifier les résultats. Une tâche réalisée en quelques secondes peut déplacer une partie du travail vers d'autres moments. Le logiciel réalise la saisie en deux minutes au lieu de dix, mais exige quinze minutes de préparation hebdomadaire et plusieurs corrections. Le bilan inclut désormais ces tâches auparavant invisibles.","question":"Pourquoi le gain de huit minutes affiché pour une étape peut-il être trompeur ?","explanation":"A rappelle qu'un gain de huit minutes sur la saisie ne tient pas compte de la préparation, de l'apprentissage et des corrections. B donne à la formation une priorité non mesurée, C isole artificiellement les préparations régulières et D suppose à tort que les corrections étaient comptées."},{"number":32,"points":26,"correct":"C","options":["Renoncer à toute règle afin que chaque groupe trouve naturellement une solution.","Supprimer l'une des activités pour éviter toute négociation sur les horaires.","Organiser les contraintes entre usages différents plutôt que présumer une compatibilité spontanée.","Réserver toute la place aux activités les plus nombreuses lors de la première consultation."],"passage":"Une place publique accueille des usages variés qui ne s'accordent pas spontanément : repos, jeux, passage et manifestations. Un aménagement réussi ne supprime pas forcément les différences ; il peut organiser leur coexistence par des espaces, des horaires et des règles discutées. Les habitants discutent des nuisances, des accès et des moments où certaines activités peuvent se dérouler. Il cherche à rendre les usages compatibles, sans supposer qu'un même espace répondra spontanément à toutes les attentes. Les réunions publiques et les jeux d'enfants se gênent à certaines heures, mais peuvent coexister si les espaces et les horaires sont discutés. La commune élabore un calendrier partagé avec les usagers.","question":"Quelle approche de l'espace commun ce projet privilégie-t-il ?","explanation":"La pluralité demande coordination et règles. C. B/D/A privilégient un seul usage ou nient l'organisation."},{"number":33,"points":26,"correct":"D","options":["Elles démontrent que le projet n'a pas de valeur tant qu'il demande plusieurs essais.","Elles prouvent que toutes les méthodes rapides sont pédagogiquement inférieures.","Elles doivent être imposées à tous les participants avec un nombre identique de tentatives.","Elles peuvent constituer une part du processus d'apprentissage, non seulement un retard à supprimer."],"passage":"Un atelier valorise le fait de terminer un projet lentement. Les participants découvrent des gestes qu'une solution rapide aurait évités. La durée n'est pas automatiquement un défaut lorsqu'elle fait partie de ce que l'activité permet d'apprendre ou d'éprouver. Les animateurs laissent une place aux essais et aux reprises, sans fixer un objectif identique pour chaque séance. Les participants peuvent expliquer ce qu'ils ont découvert pendant le travail. Lorsqu'un participant reprend plusieurs fois une pièce de bois, il apprend à identifier les défauts d'assemblage. Terminer plus vite aurait évité ces essais et une partie de l'apprentissage.","question":"Quelle fonction les reprises jouent-elles dans cette activité ?","explanation":"Les reprises font découvrir le geste, D. A/B/C exagèrent."},{"number":34,"points":26,"correct":"B","options":["Elle garantit que les événements imprévisibles pourront être traités en dehors de tout planning.","Elle efface les marges utiles aux imprévus et au repos, fragilisant l'organisation.","Elle empêche de planifier à l'avance les activités principales déjà prévues.","Elle réduit nécessairement le nombre de tâches terminées même en l'absence d'incidents."],"passage":"Un agenda collectif rend visibles les activités d'un groupe, mais peut devenir envahissant si chaque créneau libre paraît disponible pour une nouvelle tâche. Les membres décident de protéger aussi des périodes sans rendez-vous. Une absence de rendez-vous peut correspondre à un besoin de repos ou à une réserve pour les imprévus. Le calendrier indique désormais les périodes qui doivent rester protégées. Une équipe voit des cases libres et y ajoute de nouvelles missions. Les membres n'ont alors plus de temps pour traiter un incident urgent ni récupérer après une période chargée. Des plages protégées sont instaurées.","question":"Quel risque présente l'assimilation de toute case vide à un créneau disponible ?","explanation":"La réserve protège la résilience du programme. B. A/D/C ne suivent pas le scénario."},{"number":35,"points":26,"correct":"C","options":["Une activité pratiquée rarement a moins de valeur personnelle, sauf lorsque plusieurs membres de la famille y participent.","La diversité des expériences constitue un indicateur plus direct d'attachement que les récits des participants.","Le sentiment d'attachement ne suit pas nécessairement le nombre de sorties, dans l'expérience vécue des participants.","Une fréquence élevée révèle en général une satisfaction supérieure, y compris lorsque la personne rapporte peu d'attachement."],"passage":"Une enquête mesure le nombre d'activités pratiquées. Des participants ayant peu d'activités déclarent pourtant y être très attachés. La richesse d'un loisir ne se confond pas toujours avec la diversité ou la fréquence mesurable des sorties. Les entretiens demandent ce que l'activité apporte : une relation, une découverte ou un moment attendu dans la semaine. Ces réponses complètent les données de fréquentation. Une personne participe à une seule rencontre mensuelle, mais dit qu'elle compte beaucoup pour elle. Une autre multiplie les sorties sans retrouver le même sentiment d'attachement.","question":"Quelle conclusion évite de réduire l'expérience de loisir à sa fréquence ?","explanation":"C constate que l'attachement déclaré ne varie pas mécaniquement avec les sorties. A et D font de la fréquence une mesure affective, B substitue la diversité à l'expérience racontée."},{"number":36,"points":33,"correct":"C","options":["Les séances sans réservation devraient remplacer les activités régulières parce qu'elles répondent aux horaires changeants de certains.","La variété des disciplines peut compenser une organisation rigide si le programme propose suffisamment de créneaux au choix.","Des conditions d'inscription identiques excluent certains publics, malgré la variété des activités et des disciplines effectivement proposées.","L'offre abondante améliore l'accès uniquement lorsque chaque activité demande un engagement régulier et anticipé."],"passage":"La multiplication des activités proposées peut donner l'impression d'un choix toujours plus large. Mais si toutes exigent réservation anticipée et présence régulière, les personnes aux horaires imprévisibles restent exclues. La diversité des contenus ne garantit pas une diversité des conditions de participation. Les responsables interrogent les personnes qui ont abandonné une inscription ou qui consultent les programmes sans jamais réserver. Certaines travaillent sur des créneaux changeants, d'autres ne peuvent pas prévoir longtemps à l'avance leurs possibilités de déplacement. Le centre teste donc des séances indépendantes, des places accessibles le jour même et des engagements plus courts. Ces formules seront évaluées avec les activités régulières, qui répondent à d'autres besoins. Il ne s'agit pas d'imposer un modèle unique, mais d'offrir plusieurs manières d'entrer dans les propositions et de rendre les contraintes visibles dès la présentation du programme. Un centre affiche vingt activités mais exige une inscription trois semaines avant chacune. Les salariés à horaires variables restent absents; des séances à accès spontané permettent ensuite une autre forme de participation.","question":"Pourquoi le nombre d'activités proposées n'est-il pas un indicateur suffisant d'ouverture du programme ?","explanation":"C relève que des règles identiques de réservation écartent certains publics malgré vingt disciplines. A supprime des activités utiles à d'autres, B suppose que des contenus variés corrigent des créneaux rigides et D privilégie précisément la condition qui produit l'exclusion."},{"number":37,"points":33,"correct":"C","options":["La subvention couvre l'accueil, rendant les autres contributions secondaires pour le budget.","L'absence de billet laisse principalement des dépenses de personnel, le loyer pouvant être assumé par les contributions volontaires.","Un accueil sans paiement à l'entrée suppose néanmoins des moyens pour financer son fonctionnement.","Les soutiens publics et les dons assurent la continuité du lieu dès lors que les organisateurs publient leur budget régulièrement."],"passage":"Un lieu de rencontre souhaite rester ouvert sans obligation d'achat. Pour durer, il doit néanmoins financer le local et l'accueil. Les organisateurs rendent ces coûts visibles et recherchent plusieurs soutiens. L'absence de paiement à l'entrée ne signifie pas l'absence de ressources nécessaires à l'existence du service. Le budget distingue le loyer, les charges, l'entretien et le temps des personnes qui assurent la présence sur place. Une partie peut être soutenue par la commune et une autre par des contributions volontaires ou des partenariats. Les décisions doivent toutefois préserver l'accueil des visiteurs qui ne peuvent pas donner. Les organisateurs publient donc des informations régulières sur les besoins et sur l'utilisation des aides reçues. Cette transparence permet de discuter des choix, notamment des horaires d'ouverture, sans faire peser silencieusement toute la continuité du lieu sur quelques bénévoles ou sur des dépenses personnelles invisibles. Le lieu ne facture aucun billet, mais le loyer augmente et les permanences exigent du temps de travail. Les organisateurs présentent un budget et sollicitent des soutiens qui n'imposent pas de contribution aux visiteurs.","question":"Quelle distinction économique la transparence budgétaire cherche-t-elle à faire comprendre ?","explanation":"C distingue le prix nul à l'entrée des dépenses réelles de loyer, entretien et accueil. A et B attribuent arbitrairement les postes de dépenses à une source unique, D prend la transparence et la recherche d'aides pour une garantie de financement."},{"number":38,"points":33,"correct":"D","options":["Le temps non affecté ne devient utile que s'il est réattribué à une tâche avant la fin de la journée.","Une marge de calendrier remplace la nécessité de hiérarchiser les urgences lorsqu'un incident survient.","Une réserve prévue dans le planning évite les incidents techniques plutôt que de faciliter leur prise en charge.","Une réserve de temps absorbe les variations de charge imprévues, sans devoir occuper chaque minute libérée."],"passage":"Une équipe mesure le temps gagné par un nouvel outil et souhaite remplir immédiatement les minutes libérées. Certains salariés proposent d'en conserver une partie pour traiter les imprévus. Un planning occupé en permanence devient fragile face à la moindre variation. Une marge non affectée peut contribuer au bon fonctionnement plutôt que représenter un temps perdu. Les salariés décrivent des demandes urgentes, des absences et des problèmes techniques impossibles à prévoir précisément. Lorsque toutes les heures sont attribuées, ces événements déplacent les tâches vers la fin de journée ou obligent à abandonner une priorité sans discussion. L'équipe teste donc une réserve et observe comment elle est utilisée. Les responsables regarderont les délais, la qualité du travail et la fatigue, plutôt que le seul taux d'occupation du calendrier. Un nouveau logiciel libère trente minutes de travail quotidien; la direction les remplit immédiatement de nouvelles tâches. Au premier incident, tout le programme déborde et les heures supplémentaires augmentent.","question":"Pourquoi une réserve de temps peut-elle être productive même sans tâche assignée ?","explanation":"D décrit une marge permettant d'absorber les variations imprévues sans allonger les journées. A confond temps disponible et temps perdu, B écarte la priorisation, C confond capacité à répondre et prévention des incidents."},{"number":39,"points":33,"correct":"C","options":["La demande forte justifie de maintenir une ouverture hebdomadaire tant que les soutiens financiers sont seulement envisagés.","Une subvention d'un an et un prêt de matériel passé peuvent être comptés comme ressources de long terme fiables pour annoncer le calendrier.","Retenir provisoirement la cadence compatible avec les équipes et les ressources garanties, puis réévaluer l'extension quand le financement et les relais seront établis.","Les bénévoles mobilisés pendant l'essai peuvent garantir des permanences régulières si les associations se relaient sans budget de maintenance."],"passage":"Un quartier lance une initiative temporaire qui rencontre un grand succès. Les habitants veulent la prolonger, mais les bénévoles n'ont pas prévu un engagement permanent. Le projet doit être réorganisé et financé autrement. Le succès d'une expérience ne garantit pas que les conditions qui l'ont rendue possible puissent durer sans transformation. Pendant l'essai, les organisateurs avaient utilisé du matériel prêté et consacré plusieurs week-ends exceptionnels à la préparation. Ces ressources ne seront pas disponibles chaque mois. Le groupe établit donc un budget, clarifie les responsabilités et recherche des relais avant d'annoncer un calendrier durable. Les habitants seront informés des changements nécessaires, y compris d'une éventuelle réduction de fréquence. Cette préparation ne retire rien à la valeur de l'expérience initiale : elle distingue ce qu'une mobilisation ponctuelle a permis de réaliser et ce qu'une organisation régulière devra pouvoir soutenir sans épuiser les personnes qui la font vivre. Pendant l'essai, une équipe a pu utiliser des véhicules prêtés et travailler tous les samedis. Une activité permanente exigerait des véhicules financés et des remplaçants prévus dans le calendrier. Six mois après l'essai, les habitants réclament une ouverture hebdomadaire. Le collectif chiffre deux formules: chaque samedi nécessiterait deux véhicules et quatre personnes formées, alors qu'une ouverture deux fois par mois pourrait fonctionner avec un véhicule financé et une équipe de remplacement. Le nombre de demandes reste élevé dans les deux scénarios. Une subvention peut financer l'achat d'un véhicule, mais elle n'est accordée que pour un an; le prêt initial de matériel est terminé. Une partie des anciens bénévoles accepte de venir ponctuellement, pas de garantir un samedi sur deux. Deux associations proposent d'alterner les permanences à condition qu'un calendrier écrit et un budget de maintenance soient adoptés. Les organisateurs refusent de compter une promesse ponctuelle comme un engagement régulier et préfèrent annoncer une fréquence plus basse mais soutenable. Ils précisent que la satisfaction des habitants pendant l'essai ne permet ni de prévoir les disponibilités futures ni d'assurer le financement de la deuxième année.","question":"Quelle décision traduit le mieux la différence entre une forte demande et une capacité durable à assurer le service ?","explanation":"C s'appuie sur la cadence compatible avec les ressources financées et les personnes réellement engagées, en réévaluant l'extension. A confond demandes et capacité, B traite des ressources temporaires comme pérennes, D supprime une condition budgétaire et des engagements de relève."}]}$paper_20$::jsonb);
do $check_and_activate$
declare rec record; n integer; oldq jsonb; newq jsonb; correct_index integer; changed_rows integer;
begin
 for rec in select p.id, p.content as new_content, old.content as old_content, s.changed
 from academy_tcf_reading.papers p
 join academy_tcf_reading.papers old on old.id=p.id and old.version='tcf-reading-2026-11-close-reading-v4'
 join cleanup_scope s on s.test_id=p.id
 where p.version='tcf-reading-2026-11-distractor-polish-v5'
 loop
   if (rec.new_content - 'questions' - 'version') <> (rec.old_content - 'questions' - 'version')
   then raise exception 'Non-question paper metadata modified %',rec.id; end if;
   if jsonb_array_length(rec.new_content->'questions')<>39 or (rec.new_content->>'maxPoints')::integer<>699 or (rec.new_content->>'seconds')::integer<>3600
   then raise exception 'Test structure modified %',rec.id; end if;
   for n in 1..39 loop
     newq=rec.new_content->'questions'->(n-1);
     oldq=rec.old_content->'questions'->(n-1);
     if not (n=any(rec.changed)) then
       if newq<>oldq then raise exception 'Untargeted question changed % Q%',rec.id,n; end if;
     else
       if (newq - 'options' - 'explanation') <> (oldq - 'options' - 'explanation')
       then raise exception 'Passage, stem, key, scoring, or extra metadata changed % Q%',rec.id,n; end if;
       correct_index=case newq->>'correct' when 'A' then 0 when 'B' then 1 when 'C' then 2 when 'D' then 3 else -1 end;
       if correct_index<0 or newq->'options'->>correct_index <> oldq->'options'->>correct_index
       then raise exception 'Correct answer changed % Q%',rec.id,n; end if;
     end if;
   end loop;
 end loop;
 update academy_tcf_reading.published_papers set version='tcf-reading-2026-11-distractor-polish-v5'
 where test_id in ('tcf-reading-15','tcf-reading-16','tcf-reading-17','tcf-reading-18','tcf-reading-19','tcf-reading-20') and version='tcf-reading-2026-11-close-reading-v4';
 get diagnostics changed_rows=row_count;
 if changed_rows<>6 then raise exception 'Expected 6 pointer updates, got %',changed_rows; end if;
end $check_and_activate$;
do $postcheck$ begin
 if (select count(*) from academy_tcf_reading.published_papers)<>20 then raise exception 'Catalog was modified'; end if;
 if (select count(*) from academy_tcf_reading.published_papers where test_id in ('tcf-reading-15','tcf-reading-16','tcf-reading-17','tcf-reading-18','tcf-reading-19','tcf-reading-20') and version='tcf-reading-2026-11-distractor-polish-v5')<>6 then raise exception 'Target catalog not updated'; end if;
 if exists((select test_id,version from cleanup_other_pointers except select test_id,version from academy_tcf_reading.published_papers)
 union all (select test_id,version from academy_tcf_reading.published_papers where test_id not in ('tcf-reading-15','tcf-reading-16','tcf-reading-17','tcf-reading-18','tcf-reading-19','tcf-reading-20') except select test_id,version from cleanup_other_pointers)) then raise exception 'Other tests changed'; end if;
 if (select count(*) from academy_tcf_reading.papers)<>(select banks+6 from cleanup_before) then raise exception 'Historical bank row count changed'; end if;
 if (select md5(coalesce(string_agg(to_jsonb(p)::text,'' order by id,version),'')) from academy_tcf_reading.papers p where not (id in ('tcf-reading-15','tcf-reading-16','tcf-reading-17','tcf-reading-18','tcf-reading-19','tcf-reading-20') and version='tcf-reading-2026-11-distractor-polish-v5'))<>(select banks_digest from cleanup_before) then raise exception 'Historical bank data changed'; end if;
 if (select count(*) from academy_tcf_reading.attempts)<>(select attempts from cleanup_before) or
 (select md5(coalesce(string_agg(to_jsonb(a)::text,'' order by id),'')) from academy_tcf_reading.attempts a)<>(select attempts_digest from cleanup_before) then raise exception 'Student attempts changed'; end if;
end $postcheck$;
commit;